def insertAtTail(head, data):
    node = Node(data)
    if head is None:
        head = node
        return head
    curr = head
    while curr.next:
        curr = curr.next
    curr.next = node
    return head

func deleteNode(head: Node<T>?, index: Int) -> Node<T>? {
  guard let head = head else {
    return nil
  }

  if index == 0 {
    return head.next
  }

  head.next = deleteNode(head.next, index-1)
  return head
}

