int main()
{
    int A[3][3]= { {5,6,7}, {1,2,3}, {3,4,5}};
    int inv[3][3], det = 0;
    int i, j;

    //Calculate the determinant of the 3x3 matrix
    for (i = 0; i < 3; i++)
        det = det + (A[0][i] * (A[1][(i+1)%3] * A[2][(i+2)%3] - A[1][(i+2)%3] * A[2][(i+1)%3]));

    printf("Determinant of the matrix: %d \n", det);

    //Find inverse of the matrix
    for (i = 0; i < 3; i++)
    {
        for (j = 0; j < 3; j++)
        {
            inv[i][j] = ((A[(i+1)%3][(j+1)%3] * A[(i+2)%3][(j+2)%3]) - (A[(i+1)%3][(j+2)%3] * A[(i+2)%3][(j+1)%3]))/ det;
        }
    }

    //Print the inverse of the matrix
    printf("Inverse of the matrix:\n");
    for (i = 0; i < 3; i++)
    {
        for (j = 0; j < 3; j++)
            printf("%d \t", inv[i][j]);
        printf("\n");
    }
    return 0;
}

