public static int findClosestValue(int[] arr, int target) {
  int closestValue = arr[0];
  int minDiff = Math.abs(target - arr[0]);
  for (int i = 1; i < arr.length; i++) {
    int currentDiff = Math.abs(target - arr[i]);
    if (currentDiff < minDiff) {
      closestValue = arr[i];
      minDiff = currentDiff;
    }
  }
  return closestValue;
}

