public static int findClosestValue(int[] arr, int target) {
  int left = 0;
  int right = arr.length - 1;
  while (left < right - 1) {
    int mid = (left + right) / 2;
    if (arr[mid] < target) left = mid;
    else right = mid;
  }
  return (Math.abs(arr[left] - target) <= Math.abs(arr[right] - target))
      ? arr[left] : arr[right];
}

