int lis( int arr[], int n )  
{  
    int lis[n]; 

    lis[0] = 1;    

    for (int i = 1; i < n; i++ )  
    { 
        lis[i] = 1; 
        for (int j = 0; j < i; j++ )   
            if ( arr[i] > arr[j] && lis[i] < lis[j] + 1)  
                lis[i] = lis[j] + 1;  
    } 

    int lisLength = 0; // Initialize result 
    for (int i = 0; i < n; i++ ) 
        if (lisLength < lis[i]) 
            lisLength = lis[i]; 

    return lisLength; // Return result 
