public static String longestRepeatedSubstring(String text) {
    int n = text.length();

    // Auxiliary array to store
    // possible starting of longest
    // Common string
    int[] pos = new int[n + 1];

    // Array to store LCS
    // Length
    int[] cnd = new int[n + 1];

    int i, j, k = 0, l = 0;

    // Moving from left side
    for (i = 1; i < n; i++)
    {
        for (j = i + 1; j <= n; j++)
        {
            // If it is same as previous
            // one
            if (text.charAt(i - 1) == (text.charAt(j - 1))) {

                // Storing this value
                cnd[j] = cnd[i] + 1;

                // Store starting position
                pos[j] = i;

                // Update result
                if (cnd[j] > l)
                {
                    k = i;
                    l = cnd[j];
                }
            }
        }
    }

    // For printing
    return text.substring(k - 1, k + l - 1);
}

