#include <iostream>
#include <algorithm>
#include <random>
#include <vector>

const int population_size = 10;
const int n_chromosomes = 4;
const int n_generations = 100;

std::vector<std::pair<std::vector<int>, int> > population;

// Function to generate a random population
void generate_population(std::vector<int> numbers) {
    std::random_device r;
    std::default_random_engine engine(r());
    std::uniform_int_distribution<int> distribution(0, numbers.size()-1);

    for (int i = 0; i < population_size; i++) {
        std::vector<int> chromosome;
        for (int j = 0; j < n_chromosomes; j++) {
            int index = distribution(engine);
            chromosome.push_back(numbers[index]);
        }
        int min = *(std::min_element(chromosome.begin(), chromosome.end()));
        population.push_back(std::make_pair(chromosome, min));
    }
}

// Function to select best chromosomes in the population
std::vector<std::pair<std::vector<int>, int>> select(std::vector<std::pair<std::vector<int>, int>> pop) {
    std::sort(pop.begin(), pop.end(), [](const std::pair<std::vector<int>, int>& a,
                                        const std::pair<std::vector<int>, int>& b)
                                    {
                                        return a.second < b.second;
                                    });
    std::vector<std::pair<std::vector<int>, int>> parents;
    for (int i = 0; i < pop.size()/2; i++) {
        parents.push_back(pop[i]);
    }
    return parents;
}

// Crossover between two chromosome 
void crossover(std::vector<int>& chromosome1, std::vector<int>& chromosome2) {
    std::random_device r;
    std::default_random_engine engine(r());
    std::uniform_int_distribution<int> distribution(0, n_chromosomes-1);
    int crossover_point = distribution(engine);

    for (int i = crossover_point; i <= n_chromosomes; i++) {
        int temp = chromosome1[i];
        chromosome1[i] = chromosome2[i];
        chromosome2[i] = temp;
    }
}

// Mutation in a single chromosome 
void mutation(std::vector<int>& chromosome) {
    std::random_device r;
    std::default_random_engine engine(r());
    std::uniform_int_distribution<int> distribution(0, n_chromosomes-1);

    int mutation_point = distribution(engine);
    chromosome[mutation_point] = std::rand();
}

// Function to evolve the population
void evolve() {
    // Select best chromosomes
    std::vector<std::pair<std::vector<int>, int>> parents = select(population);

    // Reset Population
    population.clear();

    // Perform crossover and mutation to generate offsprings
    for (int i = 0; i < parents.size()-1; i+=2) {
        // Perform Crossover
        crossover(parents[i].first, parents[i+1].first);
        // Perform Mutation 
        mutation(parents[i].first);
        mutation(parents[i+1].first);

        // Calculate minimum in each chromosome
        int min1 = *(std::min_element(parents[i].first.begin(), parents[i].first.end()));
        int min2 = *(std::min_element(parents[i+1].first.begin(), parents[i+1].first.end()));
        population.push_back(std::make_pair(parents[i].first, min1));
        population.push_back(std::make_pair(parents[i+1].first, min2));
    }
}

// Function to find the minimum number
int genetic_algorithm(std::vector<int> numbers) {
    generate_population(numbers);

    // Evolve over n number of generations
    for (int i = 0; i < n_generations; i++) {
        evolve();
    }

    // Select best chromosomes
    std::vector<std::pair<std::vector<int>, int>> parent = select(population);

    // Return minimum number
    return parent[0].second;
}

// Main function
int main() {
    std::vector<int> numbers{2, 3, 5, 7, 8, 10};

    int min = genetic_algorithm(numbers);
    std::cout<<"Minimum is: "<<min<<std::endl;

    return 0;
}

