def minDeletionsPalindrome(inputStr):
    strLen = len(inputStr)
    table = [[0 for i in range(strLen)] for i in range(strLen)]

    for i in range(strLen):
        table[i][i] = 1

    for cl in range(2, strLen + 1):
        for i in range(strLen - cl + 1):
            j = i + cl - 1

            if inputStr[i] == inputStr[j] and cl == 2:
                table[i][j] = 2
            elif inputStr[i] == inputStr[j]:
                table[i][j] = table[i + 1][j - 1] + 2
            else:
                table[i][j] = max(table[i][j - 1], table[i + 1][j]);

    return strLen - table[0][strLen - 1]

