function findSumSubarray(arr) {
    // keep track of the current and maximum sums
    let curr_sum = 0;
    let max_sum = 0;

    // keep track of the start and end indices
    let start = 0;
    let end = 0;

    // loop through the array
    for (let i = 0; i < arr.length; i++) {
        // add the current element to the current sum
        curr_sum += arr[i];

        // if the current element is positive, update the maximum sum and 
        // the end indices
        if (curr_sum > max_sum && arr[i] > 0) {
            max_sum = curr_sum;
            end = i;
        }

        // if the current sum is negative, reset the current sum to 0
        // and store the current index as the start index
        if (curr_sum < 0) {
            curr_sum = 0;
            start = i + 1;
        }
    }

    console.log("Maximum sum is " + max_sum);
    console.log("Subarray is " + arr.slice(start, end + 1));
}

