function isAnagram(str1, str2) {
    if (str1.length !== str2.length) {
        return false;
    }

    let count = new Map();
    for (let i = 0; i < str1.length; i++) {
        let c = str1.charAt(i);
        if (count.has(c)) {
            count.set(c, count.get(c) + 1);
        } else {
            count.set(c, 1);
        }
    }

    for (let i = 0; i < str2.length; i++) {
        let c = str2.charAt(i);
        if (count.has(c)) {
            count.set(c, count.get(c) - 1);
        } else {
            return false;
        }
    }

    for (const c of count.values()) {
        if (c !== 0) {
            return false;
        }
    }

    return true;
}

