    {
        string time = "16:30";
        string result = ConvertTime(time);
        Console.WriteLine("24-hour time: {0}", time);
        Console.WriteLine("12-hour time: {0}", result);
    }

    public static string ConvertTime(string time)
    {
        string[] tokens = time.Split(':');
        int hour = int.Parse(tokens[0]);
        int min = int.Parse(tokens[1]);

        string result = hour.ToString("D2") + ":" + min.ToString("D2");
        if (hour > 12)
        {
            hour -= 12;
            result = hour.ToString("D2") + ":" + min.ToString("D2") + " PM";
        }
        else
        {
            result += " AM";
        }
        return result;
    }
}

