public class MainActivity extends AppCompatActivity {
  TextView stockPricesTextView;
  @Override
  protected void onCreate(Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);
    setContentView(R.layout.activity_main);
    stockPricesTextView = findViewById(R.id.stockPricesTextView);
  }

  public void fetchStockPrices(View v) {
    GetStockPricesTask task = new GetStockPricesTask();
    task.execute();
  }

  class GetStockPricesTask extends AsyncTask<Void, Void, String> {

    String targetURL;

    @Override
    protected void onPreExecute() {
      targetURL = "https://api.iextrading.com/1.0/stock/market/list/mostactive";
    }

    @Override
    protected String doInBackground(Void... voids) {
      URL url;
      HttpURLConnection connection = null;
      try {
        url = new URL(targetURL);
        connection = (HttpURLConnection)url.openConnection();
        connection.setRequestProperty("content-type", "application/json;  charset=utf-8");
        connection.setRequestProperty("Content-Language", "en-US");  
        connection.setUseCaches (false);
        connection.setDoInput(true);
        connection.setDoOutput(false);

        InputStreamReader isr = new InputStreamReader(connection.getInputStream());
        BufferedReader reader = new BufferedReader(isr);
        StringBuilder builder = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
          builder.append(line);
        }

        return builder.toString();
      } catch (Exception e) {
        e.printStackTrace();
      } finally {
        if (connection != null) {
          connection.disconnect(); 
        }
      }
      return null;
    }

    @Override
    protected void onPostExecute(String s) {
      try {
        JSONArray array = new JSONArray(s);
        String message = "";
        for (int i=0; i<10; i++) {
          JSONObject object = array.getJSONObject(i);
          String symbol = object.getString("symbol");
          String price = object.getString("latestPrice");
          message += symbol + ": $" + price + "\\n"; 
        }
        stockPricesTextView.setText(message);
      } catch (JSONException e) {
        e.printStackTrace();

      }

    }

  }

}

