import heapq

def huffman_encoding(data):
    freq_dict = dict()
    encoded_list = list()
    output_string = ""

    # Populate frequency dictionary
    for char in data:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1

    # Create a heap of all the nodes for Huffman Tree
    huffman_heap = []
    for key in freq_dict:
        huffman_heap.append([freq_dict[key], [key, ""]])

    heapq.heapify(huffman_heap)

    while len(huffman_heap) > 1:
        left_node = heapq.heappop(huffman_heap)[1]
        right_node = heapq.heappop(huffman_heap)[1]
        for pair in left_node:
            pair[1] = '0' + pair[1]
        for pair in right_node:
            pair[1] = '1' + pair[1]
        heapq.heappush(huffman_heap, [left_node[0][0]+right_node[0][0], left_node+right_node])

    huff_tree = heapq.heappop(huffman_heap)[1]
    for i in range(len(huff_tree)):
        encoded_list.append([huff_tree[i][0],huff_tree[i][1]])

    encoded_list = sorted(encoded_list,key=lambda x: len(x[1]))
    # encoding string
    for char in data:
        for item in encoded_list:
            if char == item[0]:
                output_string += item[1]
    return output_string

