def generate_random_word():
    """Generate a random five letter word."""
    vowels = ['a', 'e', 'i', 'o', 'u']
    consonants = list(map(chr, range(ord('a'), ord('z')+1)))
    consonants = [x for x in consonants if x not in vowels]

