def viterbi(obs, states, start_p, trans_p, emit_p):
    V = [{}]
    for st in states:
        V[0][st] = start_p[st] * emit_p[st][obs[0]]
    for t in range(1, len(obs)):
        V.append({})
        for st in states:
            max_tr_prob = max(V[t-1][prev_st] * trans_p[prev_st][st] for prev_st in states)
            V[t][st] = max_tr_prob * emit_p[st][obs[t]]
    opt = []
    max_prob = max(value for value in V[-1].values())
    previous = None
    for st, value in V[-1].items():
        if value == max_prob:
            opt.append(st)
            previous = st
    for t in range(len(V)-2, -1, -1):
        opt.insert(0, previous)
        max_tr_prob = max(V[t][prev_st] * trans_p[prev_st][previous] for prev_st in states)
        for prev_st in states:
            if V[t][prev_st] * trans_p[prev_st][previous] == max_tr_prob:
                previous = prev_st
    return max_prob, opt

