// Iterative QuickSort
public static void iterativeQuicksort(int start, int end, int[] numbers) {
    int i = start, j = end;
    int pivot = numbers[(start + end) / 2];

    while (i <= j) {
        while (numbers[i] < pivot)
            i++;
        while (numbers[j] > pivot)
            j--;

        if (i <= j) {
            int temp = numbers[i];
            numbers[i] = numbers[j];
            numbers[j] = temp;
            i++;
            j--;
        }
    }
    if (start > j)
        iterativeQuicksort(start, j, numbers);
    if (i < end)
        iterativeQuicksort(i, end, numbers);
}

// Recursive QuickSort
public static void recursiveQuicksort(int start, int end, int[] numbers) {
    int i = start, j = end;
    int pivot = numbers[(start + end) / 2];

    if (end - start >= 1) {
        while (i < j) {
            while (i < j && numbers[i] < pivot)
                i++;
            while (j > i && numbers[j] > pivot)
                j--;
            if (i < j) {
                int temp = numbers[i];
                numbers[i] = numbers[j];
                numbers[j] = temp;
                j--;
            }
        }

        recursiveQuicksort(start, j, numbers);
        recursiveQuicksort(i, end, numbers);
    }
}

