int findDiff(int arr[], int n) 
{ 
    // Initialize maximum and minimum 
    int max_num = arr[0], min_num = arr[0]; 

    // maximum and minimum number of 
    // the array 
    for (int i = 1; i < n; i++) 
    { 
        // Maximum element 
        if (arr[i] > max_num) 
            max_num = arr[i]; 

        // minimum element 
        if (arr[i] < min_num) 
            min_num = arr[i]; 
    } 

    // Return the difference 
    // between the maximum and 
    // the minimum element 
    return max_num - min_num; 
