import scala.io.Source
import scala.util.{Try, Success, Failure}
import java.sql.{Connection, DriverManager, ResultSet}

class DatabaseConnector {
  val url : String = "jdbc:sqlite:database.sqlite"
  var connection : Option[Connection] = None

  def connect() : Try[Connection] = {
    if (connection.isEmpty) {
      val conn = DriverManager.getConnection(url)
      connection = Some(conn)
      Success(conn)
    } else {
      Success(connection.get)
    }
  }

  def executeQuery(query : String) : Try[ResultSet] = {
    connect().map(conn => {
      val statement = conn.createStatement
      val resultSet = statement.executeQuery(query)
      resultSet
    })
  }

  def update(query : String) : Try[Int] = {
    connect().map(conn => {
      val statement = conn.createStatement
      val affectedRows = statement.executeUpdate(query)
      affectedRows
    })
  }

  def close() : Try[Unit] = {
    connection match {
      case Some(conn) => {
        conn.close()
        connection = None
        Success(())
      }
      case None => Failure(new Exception("Connection already closed"))
    }
  }
}

