public class Chess { 

    // creates chess board of size 8x8 
    static char[][] chessBoard(int n) { 

        // construct a chessboard 
        char[][] board = new char[n][n]; 

        // loop to construct a random chessboard 
        for (int i = 0; i < n; i++) { 
            for (int j = 0; j < n; j++) { 

                // Randomly assign either 'w' or 'b'  
                // to each of the 64 squares of the board 
                Random rand = new Random(); 
                int randomNumber = rand.nextInt(2); 
                if (randomNumber == 1) 
                    board[i][j] = 'w'; 
                else
                    board[i][j] = 'b'; 
            } 
        } 
        return board; 
    } 

    // main function 
    public static void main(String[] args) { 

        // size of the chessboard 
        int n = 8; 
        char[][] board = chessBoard(n); 

        // print the chessboard 
        for (int i = 0; i < n; i++) { 
            for (int j = 0; j < n; j++) 
                System.out.print(board[i][j] + " "); 
            System.out.println(); 
        } 
    } 
}

