vector<string> alphabetizeWords(string words) {
    // Initialize empty and vector
    vector<string> wordsList;

    // Split the string using a comma as the delimiter
    stringstream ss(words);
    string token;
    while (getline(ss, token, ',')) {
        wordsList.push_back(token);
    }

    // Sort the vector and remove duplicates
    sort(wordsList.begin(), wordsList.end());
    wordsList.erase(unique(wordsList.begin(), wordsList.end()), wordsList.end());

    return wordsList;      
}

function knapsack(items, capacity) {
    let dpTable = new Array(items.length + 1)
        .fill(null)
        .map(() => new Array(capacity + 1).fill(0));

    for (let i = 0; i <= items.length; i++) {
        for (let c = 0; c <= capacity; c++) {
            const itemValue = i > 0 ? items[i - 1][1] : 0;
            const itemWeight = i > 0 ? items[i - 1][0] : 0;
            if (i === 0 || c === 0) {
                dpTable[i][c] = 0;
            } else if (itemWeight > c) {
                dpTable[i][c] = dpTable[i - 1][c];
            } else {
                dpTable[i][c] =
                    Math.max(
                        dpTable[i - 1][c],
                        dpTable[i - 1][c - itemWeight] + itemValue
                    );
            }
        }
    }

    return dpTable;
}

