class CardGame extends Component {
  constructor(props) {
    super(props);
    this.state = {
      hand: [],
      board: [],
      discard: [],
    };
  }

  render() {
    const { hand, board, discard } = this.state;

    const playCard = (card) => {
      // Place card on board
      this.setState({
        board: [...board, card],
        discard: [...discard, card],
        hand: hand.filter(c => c !== card)
      });
    };

    const discardCard = (card) => {
      // Place card in discard pile
      this.setState({
        hand: hand.filter(c => c !== card),
        discard: [...discard, card]
      });
    };

    return (
      <div>
        <div>Board: {board.map(card => card.name).join(', ')}</div>
        <div>
          Hand: {hand.map(card => (
          <button key={card.name} onClick={() => playCard(card)}>
            {card.name}
          </button>
        ))}
        </div>
        <div>
          Discard: {discard.map(card => (
            <button key={card.name} onClick={() => discardCard(card)}>
              {card.name}
            </button>
          ))}
        </div>
      </div>
    );
  }
}

