  private static final String DATABASE_USERNAME = "root";
  private static final String DATABASE_PASSWORD = "password";

  //creating the connection string
  static Connection con = null;
  static Statement stmt = null;

  static {
    try {
      //establishing the connection
      con = DriverManager.getConnection(DATABASE_URL, DATABASE_USERNAME, DATABASE_PASSWORD);

      //creating the required database Table
      stmt = con.createStatement();
      stmt.execute("CREATE Table If Not Exists Users (id int, name varchar(25))");

    } catch (SQLException e) {
      e.printStackTrace();
    }
  }

  public boolean addUser(Long uId, String userName) {
    //function to add a new user to the database table
    PreparedStatement stmt = con.prepareStatement("INSERT INTO Users VALUES (?,?)");
    stmt.setLong(1, uId);
    stmt.setString(2, userName);
    return stmt.execute();

  }

  public boolean deleteUser(Long uId) {
    //function to delete an existing user from the database
    PreparedStatement stmt = con.prepareStatement("DELETE FROM Users WHERE id = ?");
    stmt.setLong(1, uId);
    return stmt.execute();

  }

  public String checkUserName(Long uId) {
    //function to check a user's existence in the database
    String userName = null;
    PreparedStatement stmt = con.prepareStatement("SELECT name FROM Users WHERE id = ?");
    stmt.setLong(1, uId);
    ResultSet resultSet = stmt.executeQuery();
    if (resultSet.next())
      userName = resultSet.getString(1);
    return userName;

  }

