def edit_distance(str1, str2):
    """Returns the minimum edit distance between two strings"""
    m = len(str1)
    n = len(str2)

    # Create a matrix to store all the distances
    dp = mat = [[0 for _ in range(n+1)] for _ in range(m+1)]

    # Initialize base conditions
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j

    for i in range(1, m+1):
        for j in range(1, n+1):
            # If the characters match, there is no cost
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            # Otherwise, there is a cost of 1
            else:
                dp[i][j] = 1 + min(dp[i-1][j],        # Del
                                   dp[i][j-1],        # Ins
                                   dp[i-1][j-1])      # Rep

    return dp[m][n]

