def crack_caesar_cipher(cipher_text):
    for i in range(25):
        plain_text = ""
        for char in cipher_text:
            ascii_val = ord(char)
            if char.isalpha():
                if char.isupper():
                    ascii_val -= i
                    if ascii_val < 65:
                        ascii_val += 26
                elif char.islower():
                    ascii_val -= i
                    if ascii_val < 97:
                        ascii_val += 26
            plain_text += chr(ascii_val)
        print(plain_text + " (key=" + str(i) + ")")

