class Stack
{
    private:
        int top;
        int *stack;
        int size;

    public:
        Stack(int);
        ~Stack();
        void push(int);
        int pop();
        void display();
};

Stack::Stack(int n)
{
    top = -1;
    size = n;
    stack = new int[size];
    cout<<"Stack Initialized!"<<endl;
}

Stack::~Stack()
{
    delete []stack;
    cout<<"Stack Destroyed!"<<endl;
}

void Stack::push(int x)
{
    if(top == size - 1)
    {
        cout<<"Stack Overflow!"<<endl;
    }
    else
    {
        top++;
        stack[top] = x;
    }
}

int Stack::pop()
{
    int x = -1;
    if(top == -1)
    {
        cout<<"Stack Underflow!"<<endl;
    }
    else
    {
        x = stack[top];
        top--;
    }
    return x;
}

void Stack::display()
{
    if(top == -1)
    {
        cout<<"Stack Underflow!"<<endl;   
    }
    else
    {
        for(int i = top; i >= 0; i--)
        {
            cout<<stack[i]<<"  ";
        }
    }
    cout<<endl;  
}

