public static int numWaysToMakeSum(int[] denominations, int sum) {
    int[][] dp = new int[denominations.length + 1][sum + 1];
    dp[0][0] = 1;

    // pos: number of coins, currSum: the current sum
    for (int pos = 1; pos <= denominations.length; pos++) {
        for (int currSum = 0; currSum <= sum; currSum++) {
            int coin = denominations[pos - 1];

            if (coin <= currSum) {
                dp[pos][currSum] = dp[pos - 1][currSum] + dp[pos][currSum - coin];
            } else {
                dp[pos][currSum] = dp[pos - 1][currSum];
            }
        }
    }

    return dp[denominations.length][sum];
}

