    left_sum = 0
    right_sum = 0

    if root.left:
        left_sum = root.left.data
        if root.left.left or root.left.right:
            left_sum = get_sum(root.left)

    if root.right:
        right_sum = root.right.data
        if root.right.left or root.right.right:
            right_sum = get_sum(root.right)

    return (root.data == left_sum + right_sum and is_sum_tree(root.left) and is_sum_tree(root.right))

def get_sum(root):
    if root is None:
        return 0

    left_sum = 0
    right_sum = 0

    if root.left:
        left_sum = root.left.data
        if root.left.left or root.left.right:
            left_sum = get_sum(root.left)

    if root.right:
        right_sum = root.right.data
        if root.right.left or root.right.right:
            right_sum = get_sum(root.right)

    return (left_sum + right_sum)

