def k_nearest_neighbors(data, k):
    n = len(data)
    distances = []
    for i in range(n):
        distances.append([data[i], calculate_distance(data[i], data)])

    # Sort the distances in ascending order
    distances = sorted(distances, key=lambda x: x[1])

    # Get the k nearest neighbors
    k_nearest = []
