// Push an element to the stack
void push(int x)
{
 // Allocate memory for new node
 struct node *temp = (struct node*)malloc(sizeof(struct node));

 // Assign data to new node
 temp->data =x;

 // Point new node's next pointer to current top
 temp->next = top;

 // Change top pointer to point to new node 
 top = temp;
}

// Pop an element from the stack
int pop() 
{
 struct node *temp;
 int x;

 // Return -1 if stack empty
 if (top == NULL) 
  return -1; 
 else
 { 
 // Store top node data to return and change top
  temp = top;
  x = temp->data;
  top = top->next;

 // Deallocate memory
  free(temp);

  return x;
 }
}  

