public int calculateUniquePaths(int row, int col) {
  if (row == 0 && col == 0)
    return 0;

  int[][] mat = new int[row + 1][col + 1]; 

  // initialize the first row and first column to all 0's
  for (int i = 0; i <= row; i++)
    mat[i][0] = 0; 
  for (int j = 0; j <= col; j++)
    mat[0][j] = 0; 

  for (int i = 1; i <= row; i++) { 
    for (int j = 1; j <= col; j++) { 
      // if at any point we reach the destination 
      if (i == row && j == col) 
        mat[i][j] = 1; 

      else 
        mat[i][j] = mat[i - 1][j] + mat[i][j - 1];
    } 
  } 

  return mat[row][col];
}

