def sort(arr): 
    '''This function uses the Bubble Sort algorithm to sort the given array of numbers in ascending order.'''
    n = len(arr) 

    # Traverse through all elements of the array 
    for i in range(n): 

        # Last i elements are already in order 
        for j in range(0, n-i-1): 

            # Swap if the element found is lesser than the next element 
            if arr[j] > arr[j+1] : 
                arr[j], arr[j+1] = arr[j+1], arr[j] 

