def findClosestPairOfPoints(points):
 # Initialize minDistance to maximum possible value 
 minDistance = 9999999

 # Iterate over all unique combination of points
 for i in range(len(points)):
 for j in range(i+1, len(points)):
 # Calculate the distance between any two points
 d = calculateDistance(points[i], points[j])

 # If distance is less than minDistance, update the minDistance and points.
 if (d < minDistance): 
 minDistance = d
 closestPair = [points[i], points[j]]

 return closestPair;

# Calculate the distance between two points
