// A binary tree node 
class Node { 
    int data; 
    Node left, right; 

    Node(int item) 
    { 
        data = item; 
        left = right = null; 
    } 
} 

class BinaryTree { 

    Node root; 

    // Finds the path from root node to given root of the tree, Stores the 
    // path in a vector path[], returns true if path exists otherwise false 
    boolean findPath(Node root, ArrayList<Integer> path, int k) 
    { 
        // base case 
        if (root == null) 
            return false; 

        // Store this node . The node will be removed if 
        // not in path from root to k 
        path.add(root.data); 

        if (root.data == k) 
            return true; 

        // Check if k is found in left or right sub-tree 
        if (root.left != null && findPath(root.left, path, k)) 
            return true; 
        if (root.right != null && findPath(root.right, path, k)) 
            return true; 

        // If not present in subtree rooted with root, remove root from 
        // path[] and return false 
        path.remove(path.size()-1); 

        return false; 
    } 

    // Returns LCA if node n1 , n2 are present in the given binary tree, 
    // otherwise return -1 
    int findLCA(int n1, int n2) 
    { 
        // to store paths to n1 and n2 from the root 
        ArrayList<Integer> path1 = new ArrayList<Integer>(); 
        ArrayList<Integer> path2 = new ArrayList<Integer>(); 

        // Find paths from root to n1 and root to n2. 
        // If either n1 or n2 is not present , return -1 
        if (!findPath(root, path1, n1) || !findPath(root, path2, n2)) 
            return -1; 

        /* Compare the paths to get the first different value */
        int i; 
        for (i = 0; i < path1.size() && i < path2.size(); i++) 
        { 
             // Log.d("bb", path1.get(i) + " " + path2.get(i)); 
            if (!path1.get(i).equals(path2.get(i))) 
                break; 
        } 

        return path1.get(i-1); 
    } 

    // Driver code 
    public static void main(String[] args)  
    { 
        BinaryTree tree = new BinaryTree(); 
        int n1 = 7, n2 = 4; 
        tree.root = new Node(2); 
        tree.root.left = new Node(7); 
        tree.root.right = new Node(4); 
        tree.root.left.left = new Node(9); 
        tree.root.left.right = new Node(1); 
        tree.root.right.left = new Node(3); 
        tree.root.right.right = new Node(6); 

        System.out.println("LCA(7, 4) = " + 
                            tree.findLCA(n1, n2)); 
    } 
}

