func getPrimeSum(lowerLimit: Int, upperLimit: Int) -> Int {
    var result = 0
    for number in lowerLimit...upperLimit {
        if isPrime(number: number) {
            result += number
        }
    }
    return result
}

func isPrime(number: Int) -> Bool {
    if number <= 1 {
        return false
    } else if number == 2 {
        return true
    } else {
        for i in 2..<number {
            if number % i == 0 {
                return false
            }
        }
        return true
    }
}

