    let mut left = 0;
    let mut right = arr.len() - 1;

    while left <= right {
        let mid = (left + right) / 2;
        if arr[mid] == target {
            return mid as i32;
        }
        if arr[mid] > target {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

