#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Item {
 int size;
 int value;
};

// Function to solve the knapsack problem using dynamic programming
int knapsack(int capacity, vector<Item> items) {
 // Create an array to store the solutions of the subproblems
 int dp[items.size() + 1][capacity + 1];

 // Base case
 for (int i = 0; i <= items.size(); i++) {
 dp[i][0] = 0;
 }
 for (int i = 0; i <= capacity; i++) {
 dp[0][i] = 0;
 }

 // Recursive case
 for (int i = 1; i <= items.size(); i++) {
 for (int j = 1; j <= capacity; j++) {
 // If the item is more than capacity j, we can't add it
 if (items[i-1].size > j)
 dp[i][j] = dp[i-1][j];

 // Otherwise, we find the maximum of two cases:
 else
 dp[i][j] = max(dp[i-1][j], dp[i-1][j - items[i-1].size] + items[i-1].value);
 }
 }

 // Return the maximum value
 return dp[items.size()][capacity];
}

int main()
{
 int capacity = 8;
 vector<Item> items = {{5, 8}, {6, 5}, {7, 11}};
 cout << knapsack(capacity, items);
 return 0;
}

