int findMaxFrequencyNumber(int a[], int n)
{
    // Map to store frequency of each array element
    int* frequency = (int*)calloc(n, sizeof(int));
    int max_frequency = 0;
    int result;

    // Finding frequency of each element
    for(int i = 0; i < n; i++)
        frequency[a[i]]++;

    // Finding the most frequent number
    for (int j = 0; j < n; j++)
    {
        if (frequency[j] > max_frequency)
        {
            result = j;
            max_frequency = frequency[j];
        }
    }

    // Free the memory occupied by frequency array
    free(frequency);

    return result;
}

