int max_sum_submatrix(vector<vector<int> > &matrix) 
{ 
    int maxSum = INT_MIN;  

    for (int left = 0; left < matrix[0].size(); left++) 
    { 
        // initialize a temp array with size = row of matrix 
        vector<int> temp(matrix.size(), 0); 

        for (int right = left; right < matrix[0].size(); right++) 
        { 
            // Add all elements in the vertical line between 
            // left and right index as we move right 
            for (int i = 0; i < matrix.size(); i++) 
                temp[i] += matrix[i][right]; 

            // find the maximum subarray sum involved with 
            // the temp array 
            int maximum_sum = INT_MIN; 
            int currentSum = 0; 
            for (int i = 0; i < matrix.size(); i++) 
            { 
                currentSum += temp[i]; 
                if (maximum_sum < currentSum) 
                    maximum_sum = currentSum; 

                if (currentSum < 0) 
                    currentSum = 0; 
            } 

            if (maxSum < maximum_sum) 
                maxSum = maximum_sum; 
        } 
    } 
    return maxSum; 
}

