const PrimeNumberList = ({ number = 10 }) => {
  const [ primeNumbers, setPrimeNumbers ] = useState([]);

  useEffect(() => {
    const calculatePrimes = (range) => {
      let primes = [];
      for (let num = 2; num <= range; num++) {
        let isPrime = true;
        for (let divisor = 2; divisor < num; divisor++) {
          if (num % divisor === 0) {
            isPrime = false;
            break;
