// Function to obtain the shortest distance between two cities
function shortestDistance(city1, city2) {
    // Create an array to store the locations of each city
    let locations = new Array();
    locations.push(city1);
    locations.push(city2);

    // Create a 2D matrix to represent all available routes
    let routes = new Array();

    // Go through the array to find all possible routes
    let minDistance = Infinity;
    let shortestRoute = [];
    while (locations.length > 0) {
        // Obtain the current city 
        let currCity = locations.pop();

        // Check to see if this is the destination
        if (currCity === city2) {
            // Find the distances of all routes
            let currDistance = 0;
            for (let i = 0; i < routes.length; i++) {
                currDistance += routes[i][2];
            }

            // Check if this route is shorter than the existing shortest route
            if (currDistance < minDistance) {
                minDistance = currDistance;
                shortestRoute = routes.slice();
            } 
        } 
        else {
            // Obtain all available routes
            let availableRoutes = currCity.availableRoutes();
            for (let i = 0; i < availableRoutes.length; i++) {
                // Expland the route
                let nextCity = availableRoutes[i][0];
                let distance = availableRoutes[i][1];
                routes.push([currCity, nextCity, distance]);

                // Add the next city to the list to process
                locations.push(nextCity);
            }
        }
    }

    // Return the shortest route if it exists
    return minDistance === Infinity ? null : shortestRoute;
}

function parseXMLtoJSON(xmlDoc) {
    var json = {};
    if (xmlDoc.nodeType == Node.ELEMENT_NODE) {
        if (xmlDoc.attributes.length > 0) {
            json["@attributes"] = {};
            for (var j = 0; j < xmlDoc.attributes.length; j++) {
                var attribute = xmlDoc.attributes.item(j);
                json["@attributes"][attribute.nodeName] = attribute.nodeValue;
            }
        }
    } else if (xmlDoc.nodeType == Node.TEXT_NODE) {
        json = xmlDoc.nodeValue;
    }

    if (xmlDoc.hasChildNodes()) {
        for (var i = 0; i < xmlDoc.childNodes.length; i++) {
            var item = xmlDoc.childNodes.item(i);
            var nodeName = item.nodeName;
            if (typeof(json[nodeName]) == "undefined") {
                json[nodeName] = parseXMLtoJSON(item);
            } else {
                if (typeof(json[nodeName].push) == "undefined") {
                    var old = json[nodeName];
                    json[nodeName] = [];
                    json[nodeName].push(old);
                }
                json[nodeName].push(parseXMLtoJSON(item));
            }
        }
    }
    return json;
}

