    { 
        // Assigning data points 
        // to respective clusters 
        for (int i = 0; i < n; i++) 
        { 
            int min = INT_MAX, distance = 0; 
            for (j = 0; j < k; j++) 
            { 
                for (int l = 0; l < n; l++) 
                    distance += (data[i][l] - centroids[j][l]) *  
                                (data[i][l] - centroids[j][l]); 

                // Assigning clusterID for 
                // data point with min distance 
                if (distance < min) 
                { 
                    min = distance; 
                    clusterId[i] = j; 
                } 
            } 
        } 

        // Updating centroidsof each cluster 
        flag = 0; 
        for (i = 0; i < k; i++) { 
            int sum[n]; 
            int cnt = 0; 
            for (j = 0; j < n; j++) { 
                sum[j] = 0; 
            } 
            for (j = 0; j < n; j++) { 
                if (clusterId[j] == i) { 
                    for (int l = 0; l < n; l++) { 
                        sum[l] += data[j][l]; 
                    } 
                    cnt++; 
                } 
            } 
            for (j = 0; j < n; j++) { 
                centroids[i][j] = sum[j] / cnt; 
            } 

            // If any centroids is replaced then  
            // Setting flag is 1 
            if (centroids[i] != centroids[i]) 
                flag = 1; 
        } 
    } 

    // Printing final clusters 
    for (int i = 0; i < k; i++) {
        printf("\nCluster %d:\n", i + 1); 
        for (j = 0; j < n; j++) {
            if (clusterId[j] == i) 
                printf("%d ", data[j]);
        } 
    } 
}

