    m = len(str2) 

    ans = 0 

    dp = [[0 for j in range(m + 1)] for i in range(n + 1)] 

    for i in range(1, n + 1): 
        for j in range(1, m + 1): 
            if str1[i - 1] == str2[j - 1]: 
                dp[i][j] = dp[i - 1][j - 1] + 1
            else: 
                dp[i][j] = 0

            if dp[i][j] > ans: 
