void longestCommonSubstring(string string1, string string2) {
    int maxLen = 0;
    int xStart = 0, xEnd = 0;
    int len1 = string1.length();
    int len2 = string2.length();
    int endIndex, startIndex;

    int** table = new int*[len1 + 1];
    for (int i = 0; i <= len1; ++i)
        table[i] = new int[len2 + 1];

    // Longest common substring
    for (int x = 1; x <= len1; x++) {
        for (int y = 1; y <= len2; y++) {
            if (string1[x - 1] == string2[y - 1]) {
                table[x][y] = 1 + table[x - 1][y - 1];

                if (table[x][y] > maxLen) {
                    maxLen = table[x][y];

                    xStart = x;
                    xEnd = y;
                }
            }
            else 
                table[x][y] = 0;
        }
    }
    delete[] table;

    startIndex = xStart - maxLen;
    endIndex = xEnd;

    cout << "Longest common substring is: ";
    cout << string1.substr(startIndex, maxLen) << endl;
 }

