// A BST Node
struct Node
{
 int data;
 struct Node* left;
 struct Node* right;
};

/* Function to insert a node into BST */
struct Node* insertNode(struct Node* node, int data)
{
 // If the tree is empty, return a new node 
 if (node == NULL)
  return new Node(data);

 // Otherwise, recur down the tree 
 if (data < node->data) 
  node->left = insertNode(node->left, data); 
 else if (data > node->data) 
  node->right = insertNode(node->right, data);  

 // return the node pointer 
 return node;
} 

/* Function to search a node into BST */
struct Node* searchNode(struct Node* node, int data) 
{
 // If the tree is empty, return null
 if (node == NULL)
  return NULL; 

 // Otherwise, recur down the tree 
 if (data < node->data) 
  node = searchNode(node->left, data); 
 else if (data > node->data) 
  node = searchNode(node->right, data); 
 else
  return node;

 // return the node pointer 
 return node;
} 

/* Function to delete a node from BST */
struct Node* deleteNode(struct Node *node, int data) 
{ 
 // If the tree is empty
 if (node == NULL)
  return node;

 // Otherwise, recur down the tree 
 if (data < node->data)
  node->left = deleteNode(node->left, data); 
 else if (data > node->data) 
  node->right = deleteNode(node->right, data);

 //if the data to be deleted is same as the root's data
 else
 { 
  // node with only one child or no child 
  if (node->left == NULL)
  { 
   struct Node *temp = node->right; 
   free(node); 
   return temp; 
  } 
  else if (node->right == NULL)
  { 
   struct Node *temp = node->left; 
   free(node); 
   return temp; 
  } 

  // node with two children: get the inorder successor (smallest 
  // in the right subtree) 
  struct Node* temp = minValueNode(node->right); 

  // Copy the inorder successor's content to this node 
  node->data = temp->data; 

  // Delete the inorder successor 
  node->right = deleteNode(node->right, temp->data); 
 } 
 return node; 
} 

