#define MAX 100

struct Stack { 
    int top; 
    char arr[MAX]; 
}; 

void push(struct Stack* s, char element) 
{ 
    if (s->top == MAX - 1) { 
        printf("Stack overflow"); 
        return; 
    } 
    else { 
        s->top++; 
        s->arr[s->top] = element; 
    } 
} 

char pop(struct Stack* s) 
{ 
    if (s->top == -1) { 
        printf("Stack underflow"); 
        return '\0'; 
    } 
    else { 
        char element = s->arr[s->top]; 
        s->top--; 
        return element; 
    } 
} 

void reverse_string_using_stack(char* str) 
{ 
    struct Stack s; 
    int i; 

    s.top = -1; 

    int len = strlen(str); 

    for (i = 0; i < len; i++) { 
        push(&s, str[i]); 
    } 

    for (i = 0; i < len; i++) { 
        char c = pop(&s); 
        str[i] = c; 
    } 
} 

