public class PasswordGenerator
{
    public static string Generate()
    {
        const string lowerCaseLetters = "abcdefghijklmnopqrstuvwxyz";
        const string upperCaseLetters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        const string numbers = "0123456789";
        const string specialCharacters = "!@#$%^&*()_+-";

        var chars = new char[12];
        var rng = new Random(); 

        // Set a flag for each type of character required
        bool lowerCaseFlag = false;
        bool upperCaseFlag = false;
        bool numberFlag = false;
        bool specialCharacterFlag = false;

        for (int i = 0; i < 12; i++)
        {
            // Generate a random number that will determine the type of character to be added to the password
            int rand = rng.Next(4);

            // Ensure that the password meets the criteria
            while (!lowerCaseFlag && !upperCaseFlag && !numberFlag && !specialCharacterFlag)
            {
                if (rand == 0 && !lowerCaseFlag)
                    lowerCaseFlag = true;
                else if (rand == 1 && !upperCaseFlag)
                    upperCaseFlag = true;
                else if (rand == 2 && !numberFlag)
                    numberFlag = true;
                else if (rand == 3 && !specialCharacterFlag)
                    specialCharacterFlag = true;
            }

            // Set the character to be added
            if (lowerCaseFlag)
                chars[i] = lowerCaseLetters[rng.Next(0, lowerCaseLetters.Length)];
            else if (upperCaseFlag)
                chars[i] = upperCaseLetters[rng.Next(0, upperCaseLetters.Length)];
            else if (numberFlag)
                chars[i] = numbers[rng.Next(0, numbers.Length)];
            else if (specialCharacterFlag)
                chars[i] = specialCharacters[rng.Next(0, specialCharacters.Length)];
        }
        return new string(chars);
    }
}

