def generatePermutations(str, n):
    if n == 0:
        return [""]
    result = []
    for i in range(len(str)):
        sub_permutations = generatePermutations(str, n-1)
        for sub_permutation in sub_permutations:
            result.append(str[i] + sub_permutation)
    return result

