const schema = new GraphQLSchema({
    query: new GraphQLObjectType({
        name: 'Query',
        fields: () => ({
            list: {
                type: new GraphQLList(itemType),
                resolve: () => items
            },
            find: {
                type: itemType,
                args: {
                    id: { type: GraphQLID }
                },
                resolve: (_, { id }) => items.find(item => item.id == id)
            }
        })
    }),
    mutation: new GraphQLObjectType({
        name: 'Mutation',
        fields: () => ({
            create: {
                type: itemType,
                args: {
                    input: {
                        type: new GraphQLNonNull(
                            new GraphQLInputObjectType({
                                name: 'CreateItemInput',
                                fields: {
                                    name: { type: GraphQLString },
                                    age:  { type: GraphQLInt }
                                }
                            })
                        )
                    }
                },
                resolve: (_, { input }) => {
                    items.push({
                        id: (items.length + 1).toString(),
                        name: input.name,
                        age: input.age
                    });
                    return items[items.length - 1];
                }
            },
            update: {
                type: itemType,
                args: {
                    id: { type: GraphQLID },
                    input: {
                        type: new GraphQLNonNull(
                            new GraphQLInputObjectType({
                                name: 'UpdateItemInput',
                                fields: {
                                    name: { type: GraphQLString },
                                    age:  { type: GraphQLInt }
                                }
                            })
                        )
                    }
                },
                resolve: (_, { id, input }) => {
                    let item = items.find(item => item.id == id);
                    if (!item) {
                        throw new Error('Item not found!');
                    }
                    item.name = input.name;
                    item.age = input.age;
                    return item;
                }
            },
            delete: {
                type: GraphQLID,
                args: {
                    id: { type: GraphQLID }
                },
                resolve: (_, { id }) => {
                    let itemIndex = items.findIndex(item => item.id == id);
                    if (itemIndex < 0) {
                        throw new Error('Item not found!');
                    }
                    let deletedId = items[itemIndex].id; 
                    items.splice(itemIndex, 1);
                    return deletedId;
                }
            }
        })
    })
});

def check(row, col):
  for (i, j) in zip(row[:col], range(col)):
    if abs(i - row[col]) == abs(j - col) or i == row[col]:
      return False
  return True

def nQueens(n, row=None):
  if row is None:
    row = [0] * n
  if len(row) == n and check(row, n - 1):
    return [list(x) for x in set(tuple(x) for x in solutions)]
  else:
    for i in range(n):
      row[len(row)] = i
      if check(row, len(row) - 1):
        solutions.append(row[:])
        x = nQueens(n, row[:])
        if x != None:
          return x

