def are_anagrams(s1, s2):
    if len(s1) != len(s2):
        return False
    s1_dict = {}
    s2_dict = {}
    for c in s1:
        s1_dict[c] = s1_dict.get(c, 0) + 1
    for c in s2:
        s2_dict[c] = s2_dict.get(c, 0) + 1
    return s1_dict == s2_dict

