//Define the function to be optimized
float f(float x) {
    return (2 * x * x) + (3 * x) + 1;
}

//Function to generate random numbers between min and max
float random(float min, float max) {
    return (float) (min + (max - min)*rand() / RAND_MAX);
}

//Basic genetic algorithm
void geneticAlgorithm(float min, float max, int populationSize) {
    //Create a population array
    float population[populationSize];

    //Initialize the population array with random numbers
    for(int i=0; i<populationSize; i++) {
        population[i] = random(min, max);
    }

    //Perform the optimization for n generations
    for(int i=0; i<100; i++) {

        //Find the best member of the population
        float bestMember = population[0];
        for(int j=1; j<populationSize; j++) {
            if( f(population[j]) > f(bestMember) ) {
                bestMember = population[j];
            }
        }

        //Perform mutation
        for(int j=0; j<populationSize; j++) {
            if( random(0, 1) < 0.1 ) {
                population[j] = random(min, max);
            }
        }

        //Print the best member of the population
        printf("Generation %d -- Best member: %f, best score: %f\n", i, bestMember, f(bestMember));
    }
}

//Driver program
int main() {
    //Seed the random number generator
    srand(time(NULL));

    //Set the minimum and maximum values for the function
    float min, max;
    min = -5.0;
    max = 5.0;

    //Set the population size
    int populationSize = 10;

    //Run the genetic algorithm
    geneticAlgorithm(min, max, populationSize);

    return 0;
}

