public static bool IsPrime(int n) {
    // Stores odd numbers from 3 to n
    List<int> oddNums = Enumerable.Range(3, n - 2).Where(x => x % 2 != 0).ToList();

    // Edge cases
    if (n <= 1) return false;
    if (n == 2) return true;

    // Iterate over odd numbers up to sqrt of n
    foreach (int num in oddNums) {
        if (num * num > n) break;

        if (n % num == 0)
            return false;
    }

    return true;
}

