    stack<char> ops; 
    for(int i = 0; i < expression.length(); i++) 
    { 
        if(expression[i] == ' ') 
            continue; 
        else if(expression[i] == '(') 
            ops.push(expression[i]); 
        else if(isdigit(expression[i])) 
        { 
            int val = 0; 
            while(expression[i] >= '0' && expression[i] <= '9') 
            { 
                val = (val*10) + (expression[i]-'0') ;
                i++; 
            } 
            i--;  
            values.push(val); 
        } 
        else if(expression[i] == ')') 
        { 
            while(!ops.empty() && ops.top() != '(') 
            { 
                int val2 = values.top(); 
                values.pop(); 

                int val1 = values.top(); 
                values.pop(); 

                char op = ops.top(); 
                ops.pop(); 

                values.push(applyOp(val1, val2, op)); 
            } 

            if(!ops.empty()) 
               ops.pop(); 
        } 
        else
        {  
            while(!ops.empty() && getPriority(ops.top()) >= getPriority(expression[i])) 
            { 
                int val2 = values.top(); 
                values.pop(); 

                int val1 = values.top(); 
                values.pop(); 

                char op = ops.top(); 
                ops.pop(); 

                values.push(applyOp(val1, val2, op)); 
            } 
            ops.push(expression[i]); 
        } 
    } 
    while(!ops.empty()) 
    { 
        int val2 = values.top(); 
        values.pop(); 

        int val1 = values.top(); 
        values.pop(); 

        char op = ops.top(); 
        ops.pop(); 

        values.push(applyOp(val1, val2, op)); 
    } 
    return values.top(); 
}

