namespace FindMaxProduct
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] numbers = new int[] { -10, -10, 5, 2 };

            int max1, max2, max3, min1, min2;
            max1 = max2 = max3 = Int32.MinValue;
            min1 = min2 = Int32.MaxValue;

            foreach (int number in numbers)
            {
                if (number > max1)
                {
                    max3 = max2;
                    max2 = max1;
                    max1 = number;
                }
                else if (number > max2)
                {
                    max3 = max2;
                    max2 = number;
                }
                else if (number > max3)
                {
                    max3 = number;
                }

                if (number < min1)
                {
                    min2 = min1;
                    min1 = number;
                }
                else if (number < min2)
                {
                    min2 = number;
                }
            }

