import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class DatabaseManager {
 private Connection connection;

 public DatabaseManager(Connection connection) {
 this.connection = connection;
 }

 public void createTable(String tableName) {
 try {
 PreparedStatement statement = connection.prepareStatement("CREATE TABLE IF NOT EXISTS " + tableName + "()");
 statement.executeUpdate();
 statement.close();
 } catch (SQLException e) {
 e.printStackTrace();
 }
 }

 public void insertData(String tableName, String[] columnNames, Object[] data) {
 try {
 String columns = String.join(", ", columnNames);
 String values = String.join(", ", data);
 PreparedStatement statement = connection.prepareStatement("INSERT INTO " + tableName + " (" + columns + ") VALUES (" + values + ")");
 statement.executeUpdate();
 statement.close();
 } catch (SQLException e) {
 e.printStackTrace();
 }
 }

 public ResultSet selectData(String tableName, String[] columnNames) {
 try {
 String columns = String.join(", ", columnNames);
 PreparedStatement statement = connection.prepareStatement("SELECT " + columns + " FROM " + tableName);
 return statement.executeQuery();
 } catch (SQLException e) {
 e.printStackTrace();
 return null;
 }
 }

 public void deleteData(String tableName, int id) {
 try {
 PreparedStatement statement = connection.prepareStatement("DELETE FROM " + tableName + " WHERE id = ?");
 statement.setInt(1, id);
 statement.executeUpdate();
 statement.close();
 } catch (SQLException e) {
 e.printStackTrace();
 }
 }

 public void updateData(String tableName, String columnName, Object newData, int id) {
 try {
 PreparedStatement statement = connection.prepareStatement("UPDATE " + tableName + " SET " + columnName + " = ? WHERE id = ?");
 statement.setObject(1, newData);
 statement.setInt(2, id);
 statement.executeUpdate();
 statement.close();
 } catch (SQLException e) {
 e.printStackTrace();
 }
 }
}

