function generateRandomNumbers() {
  // Create an array to store the random numbers
  let randomNumbers = [];

  // Create an array of all the numbers up to 100
  let numbers = Array(100).fill().map((_, i) => i + 1);

  // Iterate over numbers while the array has elements
  while (numbers.length > 0) {
    // Choose a random index in the array
    let randomIndex = Math.floor(Math.random() * numbers.length);

    // Add the number at the random index to the randomNumbers array
    randomNumbers.push(numbers[randomIndex]);

    // Remove the number from the array
    numbers.splice(randomIndex, 1);
  }

  // Return the generated array of random numbers
  return randomNumbers;
}

