//Function to classify a given point using KNN algorithm
int classify(vector<pair<int, int>> points, vector<int> labels, int k, int x, int y)
{
    vector<pair<float, int>> distances;
    int size = (int)points.size();

    //Calculating the distances between the given point and all the training points
    for(int i=0; i<size; i++)
        distances.push_back(make_pair(calculateDistance(x, y, points[i].first, points[i].second), labels[i]));

    //Sorting the distances
    sort(distances.begin(), distances.end()); 

    //Selecting the K nearest neighbors
    vector<pair<float, int>> knn;
    for(int i=0; i<k; i++)
        knn.push_back(distances[i]);

    //Calculating the frequency of labels of the K nearest neighbors
    int freq[10]={0}; 
    for (int i = 0; i < (int)knn.size(); i++) 
        freq[knn[i].second]++; 

    //Finding the label with maximum frequency
    int maxIndex = 0;
    for (int i = 0; i<10; i++)
        if (freq[maxIndex] < freq[i])
            maxIndex = i;

    //Returning the label with the maximum frequency
    return maxIndex;
}

