public class CommonString {

    public static String longestCommonSubstring(String a, String b) {
        int m = a.length();
        int n = b.length();

        int[][] table = new int[m+1][n+1];
        int result = 0;
        int endCellRow = 0;
        int endCellCol = 0;

        for (int i = 0; i <= m; i++) { 
            for (int j = 0; j <= n; j++) { 

            if (i == 0 || j == 0) table[i][j] = 0; 

            else if (a.charAt(i-1) == b.charAt(j-1)) { 
                table[i][j] = table[i - 1][j - 1] + 1; 

                if (table[i][j] > result) {
                    result = table[i][j];
                    endCellRow = i;
                    endCellCol = j;
                }
            }
            else 
                table[i][j] = 0; 
            } 
        }

        return a.substring(endCellRow-result, endCellRow);
    }
}

