use std::cmp::min;

fn shortest_path(maze: &[&[i32]]) -> i32 {
 let n = maze.len();
 let m = maze[0].len();

 let mut dp = vec![vec![i32::max_value(); m]; n];

 for i in 0..n {
 for j in 0..m {
 dp[i][j] = maze[i][j];

 if i > 0 {
 dp[i][j] = min(dp[i][j], dp[i - 1][j] + maze[i][j]);
 }
 if j > 0 {
 dp[i][j] = min(dp[i][j], dp[i][j - 1] + maze[i][j]);
 }
 }
 }

 return dp[n - 1][m - 1];
}

