import itertools 

def travelling_salesman(adj_matrix):
    n = len(adj_matrix[0])

    min_dist = float('inf')
    min_path = []

    for path in itertools.permutations(range(n)):
        dist = 0
        for i in range(1, n):
            dist += adj_matrix[path[i-1]][path[i]]
        if dist < min_dist:
            min_dist = dist
            min_path = path

    return min_path, min_dist

