public class Scrambler {    
    private static Random random = new Random();

    public static String scrambleWord(String word) {
        char[] scramble = word.toCharArray();
        int length = scramble.length;

        while(length > 0) {
            int index = random.nextInt(length);
            char temp = scramble[--length];
            scramble[length] = scramble[index];
            scramble[index] = temp;
        }

        return new String(scramble);
    }

    public static void main(String[] args) {
        System.out.println(scrambleWord("Hello")); // Output: lelOh
    }
}

class Matrix {
 constructor(arr) {
  this.matrix = arr;
 }

 multiply(matrix2) {
  let result = []; 
  for (let i = 0; i < this.matrix.length; i++) {
   result[i] = []; 
   for (let j = 0; j < matrix2[0].length; j++) { 
    let sum = 0;
    for (let k = 0; k < matrix2.length; k++) { 
     sum += this.matrix[i][k] * matrix2[k][j];
    }
    result[i][j] = sum;
   }
  }
  return result;
 }

 transpose() {
  let result = [];
  for (let i = 0; i < this.matrix.length; i++) {
   for (let j = 0; j < this.matrix[0].length; j++) {
    if (i === 0) {
     result.push([]);
    }
    result[j].push(this.matrix[i][j]);
   }
  }
  return result;
 }
}

