import java.util.HashMap; 

public class Evaluate { 

 static int evaluateExpression(String expression) 
 { 
     // array to store the operands  
     // and operators in the expression 
     String[] tokens = expression.split(" "); 

     // take a empty hashmap 
     HashMap<String, Integer> hash_map 
         = new HashMap<>(); 

     // go through each token of expression 
     for (String t : tokens) { 

         // if token is an operand 
         // update hashmap with  
         // corresponding value 
         if (t.matches("-?\\d+")) 
             hash_map.put(t, Integer.parseInt(t)); 
     } 

     // evaluate the expression for each 
     // operator that appear 
     return evalExp(expression, 0,  
                            expression.length() - 1, 
                            hash_map); 
 } 

 // recursive function to evaluate 
 // the expression 
 static int evalExp(String exp, int start,  
                                  int end,  
                      HashMap<String, Integer> map) 
 { 

     // Indices of operators 
     int opInd = -1; 

     // store the precedence of  
     // each operator in array 
     int maxPrec = -1; 

     // go from start to end  
     // for each operator precedence 
     for (int i = start; i < end; i++)  
     { 
         char c = exp.charAt(i); 

         // check if current character is 
         // an operator and is it of higher 
         // precedence than previous  
         // higher precedence one.  
         if (IsOperator(c) && maxPrec <  
            prec(c)) 
         { 
             opInd = i; 
             maxPrec = prec(c); 
         } 
     } 

     // no operator present in the 
     // expression 
     if (opInd == -1)  
     { 

         // if one operand is present 
         // then return its value 
         if (exp.length() == 1) 
             return map.get(exp); 

         // if two operand are present,  
         // return the simple expression 
         // evaluation answer 
         return eval(exp, map); 
     } 

     // evaluate the left part  
     // of the expression 
     int left = evalExp(exp, start,  
                        opInd - 1, map); 

     // evaluate the right part 
     // of the expression 
     int right = evalExp(exp, opInd + 1,  
                              end, map); 

     // evaluate entire expression 
     return eval(left, exp.charAt(opInd), right, map); 
 } 

 // is character operators 
 static boolean IsOperator(char x) 
 { 
     switch (x) { 
         case '+': 
         case '-': 
         case '/': 
         case '*': 
             return true; 
     } 
     return false; 
 } 

 // evaluate a simple expression 
 // consists of one operator 
 static int eval(String exp, 
                 HashMap<String, Integer> map) 
 { 
     // split the expression into 
     // operands  
     String[] tokens = exp.split(" "); 

     int res = map.get(tokens[0]); 

     for (int i = 1; i < tokens.length; i = i + 2) 
     { 
         int val = map.get(tokens[i + 1]); 

         switch (tokens[i]) { 
         case "+": 
             res += val; 
             break; 

         case "-": 
             res -= val; 
             break; 

         case "*": 
             res *= val; 
             break; 

         case "/": 
             res /= val; 
             break; 
         } 
     } 
     return res; 
 } 

 // Evaluate two operands and 
 // one operator 
 static int eval(int left, char op,  
                                 int right,  
                     HashMap<String, Integer> map) 
 { 

     switch (op) { 
     case '+': 
         return left + right; 

     case '-': 
         return left - right; 

     case '*': 
         return left * right; 

     case '/': 
         return left / right; 
     } 

     return -1; 
 } 

 // returns precedence of a  
 // given operator 
 static int prec(char ch) 
 { 
     switch (ch) { 
     case '+': 
     case '-': 
         return 1; 

     case '*': 
     case '/': 
         return 2; 
     } 

     return -1; 
 } 

 // Driver code 
 public static void main (String[] args)  
 { 
     String expression =  
             "x + y * 2 - 4 / 2"; 

     HashMap<String, Integer> hash_map 
         = new HashMap<>(); 

     // add values to the hash map 
     hash_map.put("x", 2); 
     hash_map.put("y", 3); 

     System.out.println( 
         evaluateExpression(expression) 
         ); 
 } 
