def is_anagram(s1, s2):
    if len(s1) != len(s2):
        return False

    s1 = s1.lower()
    s2 = s2.lower()

    map_count = {}

    for char in s1:
        if char not in map_count:
            map_count[char] = 1
        else:
            map_count[char] += 1

    for char in s2:
        if char not in map_count:
            return False
        else:
            map_count[char] -= 1

    for key, _ in map_count.items():
        if map_count[key] != 0:
            return False
        return True

