int kadane(int arr[], int n)
{
 // Initialize maximum sum to 0
 int sum = 0;
 int max_sum = 0;

 // Take each element in array
 for (int i = 0; i < n; i++)
 {
 sum = sum + arr[i];

 // Negate if required 
 if (sum < 0)
 sum = 0;

 // Update max_sum
 max_sum = max(max_sum, sum);
 }

 return max_sum;
}

int circular_subarray_sum(int arr[], int n)
{
 // Case 1 - when all elements in array are positive
 int max_kadane = kadane(arr, n);

 // Case 2 - When more than one element is negative
 int arr_sum = 0;
 for (int i = 0; i < n; i++)
 {
 arr_sum = arr_sum + arr[i];
 arr[i] = -arr[i];
 }

 // Kadane of negated array
 arr_sum = arr_sum + kadane(arr, n);

 // Maximum circular subarray sum
 return max(max_kadane, arr_sum);
}

