public int mostCommon(int[] arr){ 
    // keeps track of count of each element 
    Map< Integer, Integer> countMap = new HashMap<>(); 

    // traverse the array input 
    for (int i = 0; i < arr.length; i++) 
    { 
        // if element already exists: increment the count in map 
        if (countMap.containsKey(arr[i])) 
        { 
            int count = countMap.get(arr[i]); 
            countMap.put(arr[i], count + 1); 
        } 

        // else: put the element in map with count as 1 
        else
            countMap.put(arr[i], 1); 
    } 

    // to get the most frequently occurring element 
    int maxCount = 0; 
    Integer element = null; 
    for (Map.Entry< Integer, Integer> entry : countMap.entrySet()) 
    { 
        if (entry.getValue() > maxCount) 
        { 
            maxCount = entry.getValue(); 
            element = entry.getKey(); 
        } 
    } 

    return element;    
}

