int MaxProduct(int[] array) {
  int max_product = int.MinValue;

  // Iterate over each subset of size 2 
  for (int i = 0; i < array.Length - 1; i++) 
  { 
    // Get the product of current subset 
    int current_product = array[i] * array[i + 1]; 

    // Update current max product 
    max_product = Math.Max(current_product, max_product); 
  } 

  // Return maximum product 
  return max_product;
}

