public class IntArrayMedian {
    private int[] array;

    public IntArrayMedian(int[] arr) {
        this.array = arr;
    }

    public int findMedian() {
        Arrays.sort(array);

        if (array.length % 2 != 0) {
            return array[array.length / 2];
        }

        int middleIndex1 = array.length / 2;
        int middleIndex2 = middleIndex1 - 1;
        return (array[middleIndex1] + array[middleIndex2]) / 2;
    }
}

