def find_longest_increasing_sequence(nums):
    current_sequence = [nums[0]]
    longest_sequence = [nums[0]]

    for n in nums[1:]:
        if n > current_sequence[-1]:
            current_sequence.append(n)
            if len(current_sequence) > len(longest_sequence):
                longest_sequence = list(current_sequence)
        else:
            current_sequence = [n]

    return longest_sequence

