int hex_to_decimal(char hex) {
    int n = 0;
    for (int i=0; hex[i]!='\0';i++) {
        if(hex[i]>='0' && hex[i]<='9') {
            n = 16 * n + (hex[i] -48);
        }
        else if (hex[i]>='A' && hex[i]<='F') {
            n = 16 * n + (hex[i] - 55);
        }
    }
    return n;
}

