def is_anagram(str1, str2):
    if len(str1) != len(str2):
        return False
    # get frequency of each character of str1 
    freq_map = {}
    for ch in str1:
        if ch not in freq_map:
            freq_map[ch] = 1
        else:
            freq_map[ch] += 1

    # check whether frequency of characters in str2 is same as str1
    for ch in str2:
        if ch not in freq_map:
            return False
        else:
            freq_map[ch] -= 1

    for value in freq_map.values():
        if value != 0:
            return False

    return True

def recursive_search(text, substring): 

    # Base Case 1: If substring is empty, return true 
    if len(substring) == 0: 
        return True

    # Base Case 2: If text is empty, return false 
    if not text: 
        return False

    # Recursive case: 
    if text[0] == substring[0]: 
        return recursive_search(text[1:], substring[1:]) 
    else: 
        return recursive_search(text[1:], substring) 

