public static int minSteps(int[] arr) {
   int[] dp = new int[arr.length];
   dp[arr.length - 1] = 0; // 0 steps to sort the last element

   // start from the second last element
   for (int i = arr.length - 2; i >= 0; i--) {
      int minSteps = Integer.MAX_VALUE;
      for (int j = i + 1; j < arr.length; j++) {
         if (arr[i] > arr[j]) {
            // if the current element is greater than the next,
            // we can use that step to sort and increase the value
            minSteps = Math.min(minSteps, dp[j] + 1);
         }
      }
