// Function to divide two integers 
int divide(int x, int y) 
{ 
    int result = 0;     
    int power = 32;      
    int y_power = y << power; 

    // iterate the result in terms of y_power 
    while (x >= y) 
    { 
        while (y_power > x) 
        { 
            y_power = y_power >> 1; 
            power--; 
        } 

        result += 1 << power; 
        x -= y_power; 
    } 
    return result; 
}

