using namespace std;

// Data structure to store a linked list node
struct Node
{
	int priority;
	int data;
	Node* next;

	Node (int priority, int data) {
		this->priority = priority;
		this->data = data;
		next = NULL;
	}
};

// Priority queue (Max Heap) class 
class PriorityQueue {
	Node* head;

	// Function to insert a node into priority queue
	void push(int priority, int data)
	{
		Node* temp = new Node(priority, data);

		if (head == NULL || priority > head->priority) {
			temp->next = head;
			head = temp;
		}
		else {
			// traverse the list and find a 
			// position to insert new node.
			Node* start = head;
			while (start->next != NULL)
			{
				if (start->next->priority < priority) {
					break;
				}
				start = start->next;
			}
			temp->next = start->next;
			start->next = temp;
		}
	}

// Function to pop element from priority queue
	int pop()
	{
		// if queue is empty, return NULL
		if (head == NULL)
			return -1;

		Node* temp = head;
		head = head->next;

		// store the popped element
		int popped = temp->data;
		delete temp;

		return popped;
	}
};

// main function
int main()
{
	// create a Priority Queue
	PriorityQueue pq;

	// insert elements into the priority queue
	pq.push(10, 1);
	pq.push(20, 2);
	pq.push(15, 3);

	// remove top element from the priority queue
	cout << pq.pop() << endl;

	return 0;
}

