function solveSudoku(board) {
    // Find empty cell
    let cell = findEmptyCell(board);
    if (!cell) {
        // puzzle is solved
        return true;
    }

    // Attemp placing each number from 1 to 9 in the empty cell
    for (let n = 1; n <= 9; n++) {
        if (isValid(board, n, cell)) {
            // Place the valid number
            board[cell.row][cell.col] = n;

            if (solveSudoku(board)) {
                // Will only return true if all cells are filled
                return true;
            }

            // Reset the cell if there is no valid solution
            board[cell.row][cell.col] = 0;
        }
    }

    // Backtrack
    return false;
}

