// Function to return top N vowels
void printTopNVowels(int n, const string& str){
    string top_vowels;
    set<char> vowels {'a', 'e', 'i', 'o', 'u'};
    int max_occur;

    // search for each vowel one by one
    for (char ch: vowels){
        // count number of occurrence of current vowel
        int current_occur = CountVowels(str, {ch}); 

        // if current occurrence > max occurrence 
        // update max_occur variable and add new character
        if (current_occur >= max_occur){
            if (top_vowels.length() < n)
                top_vowels += ch;
            else
                top_vowels = top_vowels.substr(1) + ch;
            max_occur = current_occur;
        }
    }
    cout << "Top " << n << " vowels: " << top_vowels;
}

