def solve_maze(maze):
    stack = [maze[0][0]]
    while stack:
        current_pos = stack.pop()
        x,y = current_pos
        maze[x][y] = 2

        if maze[-1][-1] == 2:
            break

        for i,j in [(1,0), (-1,0), (0,-1), (0,1)]:
            if maze[x+i][y+j] == 0:
                stack.append((x+i, y+j))

    return maze

function findPrimeNums(n) {
 let primeNums = [];

 for (let i = 2; i <= n; i++) {
 let isPrime = true;

 for (let j = 2; j < i; j++) {
 if (i % j == 0) {
 isPrime = false;
 break;
 }
 }

 if (isPrime) {
 primeNums.push(i);
 }
 }

 return primeNums;
}

