let chatrooms = {};

// Handle new websocket connection
wss.on('connection', (connection, request) => {
 let username = '';
 let currentRoom = null;

 // Handle message from client
 connection.on('message', (message) => {
	 let data = JSON.parse(message);

  switch (data.type) {
    // When client sends a message
    case 'message':
      // Broadcast message to all users in the same room
      broadcast(data, currentRoom);
      break;

    // Update user list when a new user joins
    case 'join-room':
      // Set the username
      username = data.username;
      // Set the current room
      currentRoom = data.room;
      // Add user to chatroom
      addUserToRoom(username, currentRoom);
      // Send list of users and messages
      sendRoomInfo(connection, currentRoom);
      break;

    // Remove user on disconnect
    case 'disconnect':
      removeUserFromRoom(username, currentRoom);
      break;
   }
 });	
});

// Add user to chatroom
function addUserToRoom(username, room) {
 if (!chatrooms[room]) {
  chatrooms[room] = { 
    users: [], 
    messages: [] 
  }
 }

 chatrooms[room].users.push(username);
}

// Remove user from chatroom
function removeUserFromRoom(username, room) {
 let users = chatrooms[room].users;
 let index = users.indexOf(username);
 chatrooms[room].users.splice(index, 1);
} 

// Broadcast message to all users in the same room
function broadcast(data, room) {
 wss.clients.forEach((client) => {
  if (client.room === room) {
   client.send(JSON.stringify(data));
  }
 });
}

// Send list of users and messages
function sendRoomInfo(connection, room) {
 let data = {
  type: 'room-info',
  users: chatrooms[room].users,
  messages: chatrooms[room].messages
 };

 connection.send(JSON.stringify(data));
}

