def caesarCipherEncrypt(text):
	outputText = ""
	for char in text:
		if (char.isalpha()):
			asciiVal = ord(char) + 3
			if (asciiVal > 122):
				asciiVal -= 26
			elif (asciiVal > 90 and asciiVal < 97):
				asciiVal -= 26
			outputText += chr(asciiVal)
		else:
			outputText += char
	return outputText	

