public static void permutation(char[] a, int l, int r) 
{ 
	if (l == r) 
		System.out.println(String.valueOf(a)); 
	else
	{ 
		for (int i = l; i <= r; i++) 
		{ 
			swap(a, l, i); 
			permutation(a, l + 1, r); 
			swap(a, l, i); 
		} 
	} 
} 

public static void swap(char[] a, int l, int r) 
{ 
	char temp = a[l]; 
	a[l] = a[r]; 
	a[r] = temp; 
}

