def maxFour(a):
    m1 = max(a[0], a[1])
    m2 = min(a[0], a[1])
    m3 = max(a[2], a[3])
    m4 = min(a[2], a[3]) 
    for i in range(4, len(a)): 
        if a[i] > m1: 
            m2 = m1
            m1 = a[i] 
        elif a[i] > m2: 
            m2 = a[i] 
        elif a[i] > m3: 
            m4 = m3
            m3 = a[i] 
        elif a[i] > m4: 
            m4 = a[i] 
    return m1, m2, m3, m4

