def kthSmallest(A, k):
    left = 0 
    right = len(A) - 1

    while left < right:
        pivot = A[left]
        i, j = left, right

        while i < j:
            while A[i] <= pivot and i < right:
                i += 1
            while A[j] > pivot and j > left:
                j -= 1
            if i < j:
                A[i], A[j] = A[j], A[i]
        A[left] = A[j]
        A[j] = pivot
        if j == k - 1:
            return pivot
        if j > k - 1:
            right = j - 1
        else:
            left = j + 1

