string getDay(string date)
{
    // Split date string on dots
    vector<string> dat = split(date, '.');

    // Set variables for day, month, year
    int day = stoi(dat[0]);
    int month = stoi(dat[1]);
    int year = stoi(dat[2]);

    // Handle the special case that Julian and Gregorian calendar cutovers
    if (month < 3)
        year -= 1;
    month += 10;

    // Calculate day of the week
    int a = (14 - month) / 12;
    int y = year + 4800 - a;
    int m = month + 12 * a - 3;
    int julianDay = day + (153 * m +2)/5 + 365 * y + y /4 - y/100 + y/400 - 32045;
    int dayOfWeek = (julianDay +1) % 7;

    // Map day integer to corresponding weekday
    vector<string> days = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    return days[dayOfWeek];
}

