 return [...word].map(letter => {
  lettercount++
  if (correctLetters.includes(letter) || wrongLetters.includes(letter)) {
   return <span key={lettercount}>{letter}</span>;
  } else {
   return <span key={lettercount}>_</span>;
  };
 });
}

 const handleClear = () => {
 setWrongLetters([]);
 setCorrectLetters([]);
 setIsWon(false);
 setIsLost(false);
}

const handleGuess = letter => {
 if (word.includes(letter)) {
  // add letter to correctLetters
  setCorrectLetters([...correctLetters, letter]);
  if ([...correctLetters, letter].length === word.length) {
   setIsWon(true);
  }
 } else {
  // add letter to wrongLetters
  setWrongLetters([...wrongLetters, letter]);
  if ([...wrongLetters, letter].length === wrongLettersLimit) {
   setIsLost(true);
  }
 }
}

return (
