              name: user.name,
              email: user.email
            }
          })
        }
      )
    })
  })
})

def closest_points(points):
    min_distance = float('inf')
    closest_points = []

    # Iterate over all points
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            # Calculate distance between two points
            distance = ((points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2)**0.5
            if distance < min_distance:
                min_distance = distance
                closest_points = [points[i], points[j]]

    return closest_points

import { useState, useEffect } from 'react';

const useStateManager = () => {
 const [state, setState] = useState({});
 const stateHandlers = [];

 useEffect(() => {
 stateHandlers.map(handler => handler(state));
 }, [state, stateHandlers]);

 const updateState = (stateUpdate) => {
 setState(Object.assign({}, state, stateUpdate));
 };

 const getState = () => {
 return state;
 };

 const registerStateHandler = (handler) => {
 if (stateHandlers.indexOf(handler) === -1) {
 stateHandlers.push(handler);
 }
 };

 return {
 state,
 updateState,
 getState,
 registerStateHandler
 };
};

