public class ChessGame {

 // Create a board with 8x8 fields
 private int[][] board = new int[8][8];

 // Place pieces at the beginning of the game
 public void placePieces() {
  for (int i = 0; i < 8; i++) {
   board[1][i] = 1;
   board[6][i] = 2;
  }
 }

 // Move a piece
 public void movePiece(int piece, int xFrom, int yFrom, int xTo, int yTo) {
  if (inBounds(xFrom, yFrom) && inBounds(xTo, yTo)) {
   board[xTo][yTo] = piece;
   board[xFrom][yFrom] = 0;
  }
 }

 // Check if coordinates of a field are in bounds
 private boolean inBounds(int x, int y) {
  if (x >= 0 && x < 8 && y >= 0 && y < 8) {
   return true;
  }
  return false;
 }

 // Get the current winner of the game
 public int getWinner() {
  int numPieces1 = 0;
  int numPieces2 = 0;
  for (int i = 0; i < 8; i++) {
   for (int j = 0; j < 8; j++) {
    if (board[i][j] == 1) {
     numPieces1++;
    } else if (board[i][j] == 2) {
     numPieces2++;
    }
   }
  }

  if (numPieces1 > numPieces2) {
   return 1;
  } else if (numPieces1 < numPieces2) {
   return 2; 
  }
  return 0; 
 }
}

public static void rearrangeArray(int[] arr) {
