def anagrams(word):
    # Create an empty list to store the anagrams
    anagrams = []

    # Edge case: if the length of the word is 1, return the only anagram of the word
    if len(word) == 1:
        return [word]

    # Iterate through the characters of the word
    for i, c in enumerate(word):
        # Generate all the anagrams of the word without the character at index i
        partials = anagrams(word[:i] + word[i + 1:])
        for p in partials:
            # Add the character at index i to the end of each partial, and add to anagrams
            anagrams.append(p + c)

    return anagrams

