import java.util.Arrays;

public class KnapSack {
 public static void main(String[] args) {
  int[] weights = { 5, 7, 3, 4, 6 };
  int[] values = { 10, 15, 7, 9, 11 };
  int maxWeight = 10;

  int[][] knapsackTable = new int[weights.length + 1][maxWeight + 1];

  // fill table according to knapsack algorithm
  for (int i = 0; i <= weights.length; i++) {
   for (int j = 0; j <= maxWeight; j++) {
    int noItemWeight = j;
    if (i == 0 || j == 0) {
     knapsackTable[i][j] = 0;
    } else if (weights[i - 1] <= noItemWeight) {
     knapsackTable[i][j] = Math.max(values[i - 1] + knapsackTable[i - 1][j - weights[i - 1]], knapsackTable[i - 1][j]);
    } else {
     knapsackTable[i][j] = knapsackTable[i - 1][j];
    }
   }
  }

  // trace table to find optimum items to put into knapsack
  int residueWeight = maxWeight;
  int[] selectedItems = new int[weights.length];
  int i = weights.length;
  while (residueWeight > 0 && i >= 1) {
   if (knapsackTable[i][residueWeight] != knapsackTable[i - 1][residueWeight]) {
    selectedItems[i - 1] = 1;
    residueWeight -= weights[i - 1];
   }
   i -= 1;
  }

  System.out.println("Selected Items: " + Arrays.toString(selectedItems));
 }
}

