import numpy as np

# define board size
height = 3
width = 3

# define player symbols
player1 = 'X'
player2 = 'O'

# define empty board
board = np.zeros((height,width))

# define game as a class
class Game:
    # init
    def __init__(self):
        self.board = board
        # init current player
        self.current_player = player1

    # make a move
    def make_move(self, x, y):
        # check to make sure spot is empty
        if (self.board[x,y] == 0):
            # assign current player
            self.board[x,y] = self.current_player

            # update current player
            self.update_player()

    # check for win condition
    def check_win(self):
        # check for three in a row
        for i in range(height):
            if np.all(self.board[i,:] == self.current_player):
                return True
        # check for three in a column  
        for j in range(width):
            if np.all(self.board[:,j] == self.current_player):
                return True

        # check diagonals
        if np.all(np.diag(self.board) == self.current_player):
            return True

        if np.all(np.diag(self.board[:,::-1]) == self.current_player):
            return True
        # return False if no win condition is found
        else:
            return False

    # update current player
    def update_player(self):
        # change current player
        if self.current_player == player1:
            self.current_player = player2
        else:
            self.current_player = player1

def max_jobs_on_computers(m, start_times, finish_times):
    jobs = [(start, finish) for start, finish in zip(start_times, finish_times)]    
    jobs.sort(key=lambda x: x[1]) 
    total_jobs = 0
    i = 0
    for _ in range(m):
        if jobs[i][1] <= 0:
            break 

        while i < len(jobs) and jobs[i][0] < 0: 
            total_jobs += 1
            i += 1
            while i < len(jobs) and jobs[i][0] < jobs[i-1][1]: 
                i += 1
    return total_jobs

