def is_subset_sum(arr, n): 
    # Base Cases
    if n == 0:
        return True
    if len(arr) == 0 and n != 0:
        return False

    # If last element is greater than n, then 
    # ignore it
    if arr[-1] > n:
        return is_subset_sum(arr[:-1], n)

    # If last element is equal to n, 
    # return true
    if arr[-1] == n:
        return True

    # Else, check if sum can be obtained  
    # by any of the following
    # (a) including the last element  
    # (b) excluding the last element    
    return is_subset_sum(arr[:-1], n) or is_subset_sum(arr[:-1], n-arr[-1])

