"""
Implement a program in Java to reverse each word of an input string
"""

public class ReverseEachWord {

    static void reverseEachWord(String inputString) {
        // split the string around spaces in a 
        String[] words = inputString.split(" ");

        String reversedString = "";

        // iterate over a words array
        for (int i = 0; i < words.length; i++) {
            // reverse each word
            String word = words[i];
            String reverseWord = "";

            // iterate over each character of word
            for (int j = word.length()-1; j >= 0; j--) {
                reverseWord = reverseWord + word.charAt(j);
            }
            reversedString = reversedString + reverseWord + " ";
        }
        // display the reversed string
        System.out.println(reversedString);
    }

    public static void main(String[] args) {
        reverseEachWord("This is a test");
    }
}

