// Function to query the products list
function queryProducts(queryParams) {
 // Filter results based on query params
 let results = products.filter((product) => {
 // Check if quantity is greater than the passed value
 if (queryParams.quantity && queryParams.quantity.startsWith('gt')) {
 let value = parseInt(queryParams.quantity.split(' ')[1]);
 if (product.quantity <= value) {
 return false;
 }
 }

 // Check if price is less than the passed value
 if (queryParams.price && queryParams.price.startsWith('lt')) {
 let value = parseInt(queryParams.price.split(' ')[1]);
 if (product.price >= value) {
 return false;
 }
 }

 return true;
 });

 // Sort the results
 if (queryParams.sort) {
 if (queryParams.sort === 'asc') {
 results = results.sort((a, b) => a.price - b.price);
 } else if (queryParams.sort === 'desc') {
 results = results.sort((a, b) => b.price - a.price);
 }
 }

 return results;
}

// API endpoint
app.get('/products', (req, res) => {
 let queryParams = req.query;
 let results = queryProducts(queryParams);
 res.json(results);
});

