def calendar(month, year):

    # Initializing Variables
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    weeks = [["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]]
    days = range(1, days_in_month[month - 1 ] + 1)

    # Adding number of days in the month and adjusting for leap year
    if month == 2 and ((year % 400 == 0) or (year % 100 != 0 and year % 4 == 0)):
        days_in_month[month - 1] += 1

    # Generating Calendar
    for day in days:
        if day % 7 == 1 or day == 1:
            weeks.append([day])
        else:
            weeks[-1].append(day)

    # Outputting the Calendar
    print("\t\t\t\t{0} {1}".format(calendar.month_name[month], year))
    print("\t", "\t".join(weeks[0]))
    for week in weeks[1:]:
        print("\t", "\t".join(map(str,week)))

