def memoize(f):
    memo = {}

    def helper(x):
        if x not in memo:            
            memo[x] = f(x)
        return memo[x]

    return helper

@memoize
def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

