import java.awt.Color;

public class TemperatureSort {

 public static Color[] sortTemps(double[] temps) {
  // Find the highest and lowest temperatures
  double highestTemp = Double.MIN_VALUE;
  double lowestTemp = Double.MAX_VALUE;
  for (int i=0; i<temps.length; i++) {
   highestTemp = Math.max(highestTemp, temps[i]);
   lowestTemp = Math.min(lowestTemp, temps[i]);
  }

  // Sort the temperatures
  int h = 0;
  int l = 0;
  Color[] colors = new Color[temps.length];
  for (int i=0; i<temps.length; i++) {
   if (temps[i] == highestTemp) {
    colors[h] = Color.red;
    h++;
   } else if (temps[i] == lowestTemp) {
    colors[l] = Color.blue;
    l++;
   } else {
    colors[i] = Color.black;
   }
  }

  return colors;
 }

 public static void main(String[] args) {
  double[] temps = {38.8, 37.6, 38.8, 40.8, 43.3};
  Color[] colors = sortTemps(temps);
  // The highest temperature is "red"
  // The lowest temperature is "blue"
  // All other temperatures are "black"
  for (int i=0; i<colors.length; i++) {
   System.out.println(colors[i]);
  }
 }

}

#include <vector>

vector<vector<int>> reverseMatrix(vector<vector<int>> matrix) 
{ 
    int row = matrix.size(); 
    int col = matrix[0].size(); 

    for (int i = 0; i < row; i++) { 
        for (int j = i; j < col; j++) { 
            swap(matrix[i][j], matrix[j][i]); 
        } 
    } 

    for (int i =0 ; i < row; i++) 
        reverse(matrix[i].begin(), matrix[i].end()); 

    return matrix; 
}

