def find_sum(arr_nums, target):
    length = len(arr_nums)
    outer_index, inner_index = 0, 1

    while outer_index < length - 1:
        while inner_index < length:
            if arr_nums[outer_index] + arr_nums[inner_index] == target:
                return arr_nums[outer_index], arr_nums[inner_index]
            inner_index += 1
        outer_index += 1
        inner_index = outer_index + 1

    return None, None

