class VigenereCipher {
    constructor(key) {
        this.key = new Uint8Array(key);
    }

    encrypt(message) {
        const code = new Uint8Array(message.length);
        for (let i = 0; i < message.length; i++) {
            const c = message.charCodeAt(i);
            code[i] = (c + this.key[i % this.key.length]) % 256;
        }
        return code;
    }

    decrypt(data) {
        const message = new Array(data.length);
        for (let i = 0; i < data.length; i++) {
            const c = data[i];
            message[i] = String.fromCharCode((c - this.key[i % this.key.length] + 256) % 256);
        }
        return message.join('');
    }
}

