def convert_milliseconds_to_hms(milliseconds):
    hours = milliseconds // 3600000
    minutes = (milliseconds - hours * 3600000) // 60000
    seconds = (milliseconds - hours * 3600000 - minutes * 60000) // 1000
    return (hours, minutes, seconds)

