# This is the Boyer-Moore majority voting algorithm
def majority_element(element_list):
    # Initialize the tracking variables
    max_element = element_list[0]
    max_count = 0

    # Iterate through the list
    for element in element_list:
        if element == max_element:
            max_count += 1
        else:
            max_count -= 1
            if max_count == 0:
                max_element = element
                max_count = 1

    # Check that the max element is actually more than half of the list
    occurances = 0
    for element in element_list:
        if element == max_element:
            occurances += 1

    # Output the result
    if occurances > len(element_list)/2:
        return max_element, occurances
    else:
        return None

