class DataStore(object):
    def __init__(self):
        self.conn = sqlite3.connect("data_store.db")
        self.cursor = self.conn.cursor()

    def insert_data(self, data, metadata):
        datetime_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

        try:
            self.cursor.execute("INSERT INTO user_data (data, metadata, timestamp) VALUES (?, ?, ?)",
                                    (data, metadata, datetime_str))
            self.conn.commit()
        except sqlite3.Error as e:
            print("Error inserting data:", e)
            self.conn.rollback()

    def retrieve_data(self, metadata):
        try:
            self.cursor.execute(
                "SELECT * FROM user_data WHERE metadata = ?", (metadata,))
            data = self.cursor.fetchall()
            return data   
        except sqlite3.Error as e:
            print("Error retrieving data:", e)   
