        Data = data;
        Next = null;
    }
}

public Node MergeLists(Node headA, Node headB)
{
    // base cases 
    if (headA == null) 
        return headB; 

    if (headB == null) 
        return headA; 

    Node result; 

    if (headA.Data <= headB.Data) { 
        result = headA; 
        result.Next = MergeLists(headA.Next, headB); 
    } 
    else { 
        result = headB; 
        result.Next = MergeLists(headA, headB.Next); 
    } 

    return result; 
}

