def is_prime(num):
    """
    Check if a given number is prime or not
    Parameters:
    num: the number to check
    Returns: 
    True if the number is prime, False otherwise
    """
    if num <= 1:
        return False
    elif num<= 3:
        return True
    elif num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i*i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

