// Function to detect and remove duplicate elements in an array
function removeDuplicates(arr) { 

  // Check if array is empty
  if (arr.length === 0) return; 

  // Create an empty object to store the occurrences of each item
  let seenItems = {}; 

  // Iterate through array
  for (let i=0; i<arr.length; i++) { 

    // Check if seenItems object already contains key for the current item
    if (seenItems[arr[i]]) { 

      // Remove current item from array 
      arr.splice(i,1); 

      // Decrement i by 1 as an element has been removed
      i--; 

    // If element in array is not present in seenItems 
    } else {
      // Store the current item as key in seenItems object
      seenItems[arr[i]] = true; 
    } 
  } 
  // Return the modified array
  return arr; 
} 

