def longest_substring(string):
    n = len(string)
    result_length = 0
    longest_string = ""
    for i in range(n):
        substring = ""
        for j in range(i, n):
            if string[j] in substring:
                break
            substring += string[j]
        if len(substring) > result_length:
            result_length = len(substring)
            longest_string = substring
    return longest_string

