// first n prime numbers 
void printFirstNPrimes(int n) 
{ 
    vector<int> primes; 
    int number = 2; 
    while (primes.size() < n) { 
        if (isPrime(number)) { 
            primes.push_back(number); 
        } 
        number++; 
    } 

    for (int i = 0; i < primes.size(); i++) 
        cout << primes[i] << " "; 
} 

