  SecureRandom secureRandom = new SecureRandom();
  byte[] symmetricKey = new byte[32];
  secureRandom.nextBytes(symmetricKey);
  return symmetricKey;
 }

 // Encrypts the plaintext message with the AES key
 public static byte[] encryptMessage (String message, byte[] symmetricKey) throws Exception {
  SecretKeySpec secretKey = new SecretKeySpec(symmetricKey, "AES");
  Cipher cipher = Cipher.getInstance("AES");
  cipher.init(Cipher.ENCRYPT_MODE, secretKey);
  return cipher.doFinal(message.getBytes());
 }

 public static void main(String args[]) throws Exception {

  String plainTextMessage = "Lorem ipsum dolor sit amet consectetur adipisicing elit";

  // Generates the AES key
  byte[] symmetricKey = generateAESKey();
  System.out.println("Symmetric key: " + DatatypeConverter.printHexBinary(symmetricKey));

  // Encrypts the plaintext message with the AES key
  byte[] cipherText = encryptMessage(plainTextMessage, symmetricKey); 
  System.out.println("Ciphertext: " + DatatypeConverter.printHexBinary(cipherText));
 }
}

