fn is_palindrome(s: &str) -> bool {
 // Check if the string is empty or consists of one character
 if s.len() == 0 || s.len() == 1 {
  return true;
 }

 // Compare the first and last character
 if s.chars().nth(0).unwrap() == s.chars().rev().nth(0).unwrap() {
 // Slice the string to ignore the first and last characters and check again
 return is_palindrome(&s[1..s.len()-1]);
 }

 // Not a palindrome
 return false;
}

