def find_index(array, element):
    """Function to find the index of a given element in a given sorted array"""
    low_index = 0
    high_index = len(array) - 1
    found = False
    while low_index <= high_index and not found:
        mid_index = int((low_index + high_index) / 2)
        if array[mid_index] == element:
            found = True
            return mid_index
        elif array[mid_index] > element:
            high_index = mid_index - 1
        else:
            low_index = mid_index + 1
    return -1

