struct Node* arrangeInTree(int arr[], int start, int end) 
{ 
    if (start > end) 
        return NULL; 

    int mid = (start + end) / 2; 
    struct Node* root = new Node; 

    root->data = arr[mid]; 
    root->left = arrangeInTree(arr, start, mid - 1); 
    root->right = arrangeInTree(arr, mid + 1, end); 

    return root; 
}

