def add_matrices(A, B):
    # check if matrix A and B is compatible
    if len(A) != len(B):
        return None
    # initialize a empty result matrix
    matrix_sum = [[0 for _ in range(len(A[0]))] for _ in range(len(A))]
    # iterate through matrix A and B
    for i in range(len(A)):
        for j in range(len(A[0])):
            matrix_sum[i][j] = A[i][j] + B[i][j]
    return matrix_sum

