        }
    }

@IBAction func saveButtonTapped(_ sender: UIButton) {
        let firstName = firstNameField.text?.trimmingCharacters(in: .whitespacesAndNewlines)
        let lastName = lastNameField.text?.trimmingCharacters(in: .whitespacesAndNewlines)
        let age = Int(ageField.text!)
        //validating that values are not empty
        if(firstName?.isEmpty)! || (lastName?.isEmpty)! || (age == nil) {
            return
        }
        //creating a statement
        var stmt: OpaquePointer?
        //the insert query
        let queryString = "INSERT INTO UserData (firstName, lastName, age) VALUES (?,?,?)"
        if sqlite3_prepare(db, queryString, -1, &stmt, nil) != SQLITE_OK{
            let errmsg = String(cString: sqlite3_errmsg(db)!)
            print("error preparing insert: \(errmsg)")
            return
        }
        //binding the parameters
        if sqlite3_bind_text(stmt, 1, firstName, -1, nil) != SQLITE_OK{
            let errmsg = String(cString: sqlite3_errmsg(db)!)
            print("failure binding firstName: \(errmsg)")
            return
        }

        if sqlite3_bind_text(stmt, 2, lastName, -1, nil) != SQLITE_OK{
            let errmsg = String(cString: sqlite3_errmsg(db)!)
            print("failure binding lastName: \(errmsg)")
            return
        }

        if sqlite3_bind_int(stmt, 3, Int32(age!), -1, nil) != SQLITE_OK{
            let errmsg = String(cString: sqlite3_errmsg(db)!)
            print("failure binding age: \(errmsg)")
            return
        }

        //executing the query to insert values
        if sqlite3_step(stmt) != SQLITE_DONE {
            let errmsg = String(cString: sqlite3_errmsg(db)!)
            print("failure inserting user: \(errmsg)")
            return
        }
        print("User saved successfully")
    }

