            pswd += random.choice(string.ascii_lowercase)
        elif not any(c.isdigit() for c in pswd):
            pswd += random.choice(string.digits)
        elif not any(c in string.punctuation for c in pswd):
            pswd += random.choice(string.punctuation)
        else:
