def quickSort(arr): 
	# Pick a pivot element by dividing the list in two halves
	pivot = arr[len(arr) // 2]

	# Keep track of elements that have been sorted
	lesser_elements = []
	equal_elements = []
	greater_elements = []

	# Put elements of list into different respective lists
	for i in arr:
		if i < pivot:
			lesser_elements.append(i)
		elif i == pivot:
			equal_elements.append(i)
		else:
			greater_elements.append(i)

	# Sort greater elements by recursively calling QuickSort and lesser elements
	return quickSort(lesser_elements) + equal_elements + quickSort(greater_elements)

def subsets_with_target_sum(prices, target):
    solutions = []
    for i in range(1 << len(prices)):
        subset, price_sum = [], 0
        for j in range(len(prices)):
            if (i & (1 << j)) > 0:
                subset.append(prices[j])
                price_sum += prices[j]
        if price_sum == target:
            solutions.append(subset)
