 if (lines.length < 2) return null;

 // Get field names (first line)
 String[] fields = lines[0].split(",");

 // Create array for objects
 Object[] objects = new Object[lines.length - 1];

 // Iterate over lines
 for (int i = 1; i < lines.length; i++) {
  // Create empty object
  Object obj = new Object();

  // Get values
  String[] values = lines[i].split(",");

  // Iterate over values
  for (int j = 0; j < values.length; j++) {
   // Make sure field and value are in correct order
   if (fields.length <= j) return null;

   // Set field with value
   obj.setField(fields[j], values[j]);
  }

  // Add object to array
  objects[i - 1] = obj;
 }

 return objects;
 }
}

