    public static boolean compare(String str1, String str2) 
    { 

        // If the strings have unequal length 
        if (str1.length() != str2.length()) { 
            return false; 
        } 

        int n = str1.length(); 

        // Compare each characters 
        for (int i = 0; i < n; i++) { 
            if (str1.charAt(i) != str2.charAt(i)) 
                return false; 
        } 
        return true; 
    } 

