// Function to check if a number is prime or not 
bool isPrime(int n) 
{ 
    // Corner case 
    if (n <= 1) 
        return false; 
    // Check from 2 to n-1 
    for (int i = 2; i < n; i++) 
        if (n % i == 0) 
            return false; 

    return true; 
} 

// Function to find the prime number 
int findPrime(int num) 
{ 
    // Iterate two loop till  
    // num is reached 
    for (int i = num - 1; i >= 2; i--) { 

        if (isPrime(i))  
            return i; 
    } 
} 

// Driver Code 
int main() 
{ 
