def generate_recommendations(user, connections):
 """Generate recommendations for a user based on a user's connections.

 Args:
 user (str): The user for whom recommendations are generated
 connections (dict): A dictionary of user connections in the form of {user: [connected_users]}

 Returns:
 recommendations (list): A list of recommended users
 """

 # Check if any friends of user's friends are not already connected to user
 recommendations = []
 for friend in connections[user]:
 if friend in connections:
 for potential_recommendation in connections[friend]:
 if potential_recommendation not in connections[user]:
 recommendations.append(potential_recommendation)

 # Remove duplicates and user's existing connections
 recommendations = set(recommendations) - set(connections[user])

 return list(recommendations)

