def separate_zeros_and_ones(arr):
    '''This function will separate an array of 0s and 1s.'''
    left = 0
    right = len(arr) - 1
    while left < right:
        while arr[left] == 0:
            left += 1
        while arr[right] == 1:
            right -= 1
        if left < right:
            arr[left], arr[right] = arr[right], arr[left] 
            left += 1
            right -= 1
    return arr

