def find_shortest_path(cells, start, end):
    # initialize the distance
    distances = [[float('inf') for _ in range(len(cells[0]))] for _ in range(len(cells))]
    distances[start[0]][start[1]] = 0

    # use a queue to keep track of cells to search
    queue = [start]

    while len(queue) > 0:
        row, col = queue.pop(0)
        distance = distances[row][col] + 1

        if (row, col) == end:
            return distance

        # explore next cells
        if row + 1 < len(cells) and cells[row+1][col] and distance < distances[row+1][col]:
            distances[row+1][col] = distance
            queue.append((row + 1, col))

        if col + 1 < len(cells[0]) and cells[row][col+1] and distance < distances[row][col+1]:
            distances[row][col+1] = distance
            queue.append((row, col + 1))

        if row - 1 >= 0 and cells[row-1][col] and distance < distances[row-1][col]:
            distances[row-1][col] = distance
            queue.append((row - 1, col))

        if col - 1 >= 0 and cells[row][col-1] and distance < distances[row][col-1]:
            distances[row][col-1] = distance
            queue.append((row, col - 1))

    return float('inf')

