def knapsack(items, capacity):
    """Implement a knapsack problem using dynamic programming."""
    n = len(items)  # number of items
    dp = [[0 for x in range(capacity + 1)] for y in range(n + 1)] 

    # fill the knapsack table in bottom-up manner 
    for i in range(n + 1): 
        for w in range(capacity + 1): 

            # if no item or capacity is 0 then knapsack will be empty
            if i == 0 or w == 0: 
                dp[i][w] = 0
            elif items[i - 1][1] <= w:
                dp[i][w] = max(items[i - 1][0] + dp[i - 1][w - items[i - 1][1]], dp[i - 1][w]) 
            else: 
                dp[i][w] = dp[i - 1][w]

    return dp[n][capacity]

if __name__ == '__main__':
    print(knapsack(items, capacity))

