public class WordCombinations { 
  static void findCombinations(String input) 
  { 
    // The result set containing all the possible words 
    // formed from the given input string 
    Set<String> result = new LinkedHashSet<>(); 

    // Loop through every character of given string 
    // and recursively form all possible words 
    for (int i = 0; i < input.length(); i++) 
      findCombinationsUtil(input, result, 0,  
                          Character.toString(input.charAt(i))); 
    // Print result 
    System.out.println(result); 
  } 

  // Util function to recursively find all 
  // possible words in given string 
  static void findCombinationsUtil(String input, Set<String> result,  
                                  int start, String buff) 
  { 
    // If buffer is formed 
    result.add(buff); 

    for (int i = start; i < input.length(); i++) 

        // Append current character to buffer and recur for 
        // remaining characters 
        findCombinationsUtil(input, result, i + 1, 
                            buff + input.charAt(i)); 
  } 

  public static void main(String[] args) 
  { 
    String input = "friendship"; 
    findCombinations(input); 
  } 
}

