// A function to search the given string in 
// the given text array. 
// Using a Trie data structure 
// The algorithm has a time complexity of O(M + N)

import java.util.*;

class Trie {
    // Alphabet size (# of symbols) 
    static final int ALPHABET_SIZE = 26;

    // A Trie Node 
    static class TrieNode {
        TrieNode[] children = new TrieNode[ALPHABET_SIZE];

        // isEndOfWord is true if node is leaf 
        boolean isEndOfWord;

        public TrieNode() {
            isEndOfWord = false;
            for (int i = 0; i < ALPHABET_SIZE; i++) {
                children[i] = null;
            }
        }
    };

    // create root of Trie 
    TrieNode root = new TrieNode();

    // Insert word in Trie 
    void insert(String key) {
        int length = key.length();
        int index;

        TrieNode current = root;

        for (int level = 0; level < length; level++) {
            index = key.charAt(level) - 'a';
            if (current.children[index] == null) {
                current.children[index] = new TrieNode();
            }

            current = current.children[index];
        }

        // mark the current node as a leaf 
        current.isEndOfWord = true;
    }

    // A function to search a given key in the Trie 
    boolean search(String key) {
        int length = key.length();
        int index;
        TrieNode current = root;

        for (int level = 0; level < length; level++) {
            index = key.charAt(level) - 'a';

            if (current.children[index] == null) {
                return false;
            }

            current = current.children[index];
        }

        return (current != null && current.isEndOfWord);
    }
}

class Main {

    public static void main(String args[]) {
        Trie trie = new Trie();

        // Insert all words into Trie 
        String[] text = { "hello", "world", "geek", "guru",
                      "geeks", "for", "geeek" };
        int n = text.length;
        for (int i = 0; i < n; i++) {
            trie.insert(text[i]);
        }

        // Search for different keys 
        String[] search = { "hello", "geeks", "guru", "geeky" };
        int m = search.length;
        for (int j = 0; j < m; j++) {
            if (trie.search(search[j])) {
                System.out.println(search[j] + " found!");
            } else {
                System.out.println(search[j] + " not found!");
            }
        }
    }

}

