            h = 60 * (((b - r)/delta) + 2)
        elif c_max == b:
            h = 60 * (((r - g)/delta) + 4)

        l = (c_max + c_min)/2

        s = 0
        if delta == 0:
            s = 0
        else:
            s = delta/(1 - abs((2 * l) - 1))

