def divide_list_into_equal_groups(arr):
  # Find the sum of all elements
  sum_elements = 0
  for i in arr:
    sum_elements += i

  # divide the sum by 3 to get the desired result
  avg = int(sum_elements / 3)

  # create a set to store all the possible sums
  result = set()
  for i in range(len(arr)):
    for j in range(i, len(arr)):
      temp_sum = 0
      for k in range(i, j + 1):
        temp_sum += arr[k]
      result.add(temp_sum)

  # check if the desired sum is present in the set or not
  if avg in result:
    # Divide list into 3 groups
    group1 = []
    group2 = []
    group3 = []
    curr_g1_sum = 0
    curr_g2_sum = 0
    curr_g3_sum = 0
    flag = 0

    for i in range(len(arr)):
      # Check for current sum of each group
      if flag == 0:
        curr_g1_sum += arr[i]
        if curr_g1_sum > avg:
            flag = 1
            curr_g2_sum += arr[i]

      elif flag == 1:
        curr_g2_sum += arr[i]
        if curr_g2_sum > avg:
          flag = 2
          curr_g3_sum += arr[i]
        else:
          group1.append(arr[i])

      elif flag == 2:
        curr_g3_sum += arr[i]
        if curr_g3_sum > avg:
            return -1
        else:
            group2.append(arr[i])    

    group3.append(arr[-1])
    return group1, group2, group3
  else:
    return -1

