bool isPrimeNumber(int num)
{
    // Corner case
    if (num <= 1) 
    return false;

    // Check from 2 to n-1
    for (long long i = 2; i <= sqrt(num); i++) 
    {
        if (num % i == 0) 
            return false;
    }
    return true;
}

