using System;

public class AvlTree 
{  
    Node root; 

    public void Add(int value) {
        root = AddRecursive(root, value); 
    }

    private Node AddRecursive(Node current, int value) {
        if (current == null) {
            return new Node(value);
        }

        if (value < current.value) {
            current.left = AddRecursive(current.left, value); 
        } else if (value > current.value) {
            current.right = AddRecursive(current.right, value); 
        } else {
            return current;
        }

        current.height = 1 + Math.max(
            GetHeight(current.left),
            GetHeight(current.right)
        );

        int balance = GetBalance(current);

        // LL case
        if (balance > 1 && value < current.left.value) {
            return RightRotate(current);
        }

        // RR case
        else if (balance < -1 && value > current.right.value) {
            return LeftRotate(current);
        }
        // LR case
        else if (balance > 1 && value > current.left.value) {
            current.left = LeftRotate(current.left);
            return RightRotate(current);
        }

        // RL case
        else if (balance < -1 && value < current.right.value) {
            current.right = RightRotate(current.right);
            return LeftRotate(current);
        }

        return current;
    }

    // Get the height of node
    public int GetHeight(Node node) {
        if (node == null) {
            return 0;
        }

        return node.height;
    }

    // Get balance of node
    public int GetBalance(Node node) {
        if (node == null) {
            return 0;
        }

        return GetHeight(node.left) - GetHeight(node.right);
    }

    // Right rotate the tree
    public Node RightRotate(Node parent) {

        Node pivot = parent.left;
        Node pivotR = pivot.right;

        pivot.right = parent;
        parent.left = pivotR;

        // Calculate height and balance of each node
        parent.height = Math.max(
            GetHeight(parent.left),
            GetHeight(parent.right)) + 1;
        pivot.height = Math.max(
            GetHeight(pivot.left),
            GetHeight(pivot.right)) + 1;

        return pivot;
    }

    // Left rotate the tree
    public Node LeftRotate(Node parent) {
        Node pivot = parent.right;
        Node pivotL = pivot.left;

        pivot.left = parent;
        parent.right = pivotL;

        // Calculate height and balance of each node
        parent.height = Math.max(
            GetHeight(parent.left),
            GetHeight(parent.right)) + 1;
        pivot.height = Math.max(
            GetHeight(pivot.left),
            GetHeight(pivot.right)) + 1;

        return pivot;
    }
}

