def find_all_paths(matrix):
    paths = []
    def traverse(matrix, x, y, path):
        if x > len(matrix)-1 or y > len(matrix[0])-1:
            return
        else:
            path.append(matrix[x][y])
            if x == (len(matrix)-1) and y == (len(matrix[0])-1):
                paths.append(path[:])
            else:
                traverse(matrix, x+1, y, path[:])
                traverse(matrix, x, y+1, path[:])
    traverse(matrix, 0, 0, [])
    return paths

