int knapsack(int weights[], int values[], int n, int weight_limit)  
{  
    int maxValue = 0; 

    // pick items one by one from array 
    for (int i = 0; i < n; i++) 
    { 
        // if adding current weight does not  
        // exceed the weight limit, sum the value.
        if (weights[i] <= weight_limit) 
        { 
            maxValue += values[i]; 
            // the weight limit decreases by the  
            // weight of item picked
            weight_limit -= weights[i]; 
        } 
    } 
    return maxValue; 
}

