public class Solution {
    public int maxConsecutiveSameCharacters(String S, int K) {
        int max = 0;
        int count = 1;
        char prev = S.charAt(0);

        for (int i=1; i<K; i++) {
            char c = S.charAt(i);
            if (c == prev) {
                count ++;
            } else {
                max = Math.max(max, count);
                count = 1;
                prev = c;
            }
        }

        max = Math.max(max, count);
        return max;
    }
}

