def solve(word_pairs, target_word):
  graph = buildGraph(word_pairs)
  node = findWordNode(graph, target_word)
  return dfs(graph, node)

def buildGraph(word_pairs):
  graph = {}
  for word1, word2 in word_pairs:
    if word1 not in graph:
      graph[word1] = [word2]
    else:
      graph[word1].append(word2)
    if word2 not in graph:
      graph[word2] = [word1]
    else:
      graph[word2].append(word1)
  return graph

def findWordNode(graph, target_word):
  if target_word in graph:
    return target_word
  else:
    return None

def dfs(graph, node):
  if node is None:
    return False

  visited = set()

  stack = [node]
  while stack:
    node = stack.pop()
    if node in visited:
      continue
    visited.add(node)
    for w in graph[node]:
      stack.append(w)
      if w == node:
        return True

  return False

