def selection_sort_desc(arr): 
    n = len(arr) 

    # Iterate through list
    for i in range(n-1): 

        # Find the maximum element in the unsorted list 
        max_index = 0
        for j in range(1, n-i): 
            if arr[max_index] < arr[j]: 
                max_index = j 

        # Swap the maximum element with the last element in the unsorted list 
        arr[n-i-1], arr[max_index] = arr[max_index], arr[n-i-1] 

    return arr

def min_subset_sum(arr, k):
    # Initialize best sum and best subset
    best_sum = 0
    best_subsets = []

    # Store the previous computed differences
    prev_diff = {0: []}

    # Iterate over all elements in the array
    for num in arr:
        cur_diff = {}

        # Try adding the current number to all previous differences
        for prev_dt in prev_diff:
            cur_dt = prev_dt + num
            cur_subsets = prev_diff[prev_dt][:]

            # If there are more elements than required partitions then update the best sum and best subset
            if len(cur_subsets) < k-1:
                cur_subsets.append(num)
                cur_diff[cur_dt] = cur_subsets
                if cur_dt > best_sum:
                    best_sum = cur_dt
                    best_subsets = cur_subsets

        # Store the differences computed in this iteration
        prev_diff = cur_diff

    return best_subsets

