double perceptron(vector<double> weights, vector<double> inputs) {
    double result = 0;
    for (int i = 0; i < weights.size(); i++) {
        result += weights[i] * inputs[i];
    }
    return result;
}

// Hebbian learning rule implementation
void hebbianRule(vector<double> &weights, vector<double> inputs, double output, double rate) {
    for (int i = 0; i < weights.size(); i++) {
        weights[i] += rate * inputs[i] * output;
    }
}

