function evaluatePostfix(expr) {
 // Initialize an empty stack
 let stack = [];

 // Iterate over the expression
 for (let i = 0; i < expr.length; i++) {
 let char = expr[i];

 // If the character is a number, push it onto the stack 
 if (!isNaN(parseInt(char))) {
 stack.push(parseInt(char));
 } else {
 // Otherwise, pop two items off the stack and perform the operation indicated by the character 
 let a = stack.pop();
 let b = stack.pop();
 switch(char) {
 case '+':
 stack.push(a + b);
 break;
 case '-':
 stack.push(b - a);
 break;
 case '*':
 stack.push(a * b);
 break;
 case '/':
 stack.push(b / a);
 break;
 }
 }
 }
 // Return the result 
 return stack.pop(); 
}

