// Function for replace an array 
void replace(int arr[], int n) 
{ 
    // To Store the product 
    int product = 1; 

    // Calculate the products of all 
    // the number so far 
    for (int i = 0; i < n; i++) 
        product *= arr[i]; 

    // Replace each element with product 
    for (int i = 0; i < n; i++) 
        arr[i] = product / arr[i]; 
} 

// Print the array 
void printArray(int arr[], int n) 
{ 
    for (int i = 0; i < n; i++) 
        cout << arr[i] << " "; 
} 

// Driver Code 
int main() 
{ 
    int arr[] = { 2, 3, 5, 7 }; 
    int n = sizeof(arr) / sizeof(arr[0]); 

    replace(arr, n); 

    cout << "Modified Array: "; 
    printArray(arr, n); 

    return 0; 
}

