# Example of transforming a set of numbers into increasing order 

# define a function for transforming numbers
def transform(arr):
    n = len(arr) 

    # Transforming the given array 
    for i in range(n - 1): 
        if arr[i] > arr[i + 1]: 
            arr[i], arr[i + 1] = arr[i + 1], arr[i] 

    # Sorting the array in increasing order 
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]: 
                arr[j], arr[j + 1] = arr[j + 1], arr[j] 

