   {
       int[] array = {2, 5, 4, 7, 8, 1};
       int n = array.length;

       // Reverse the array
       for (int i = 0; i < n / 2; i++) 
       {
           int temp = array[i];
           array[i] = array[n - i - 1];
           array[n - i - 1] = temp;
       }

