#include <iostream>
#include <string>

char encrypt_char(char c)
{
    int ascii = (int) c;
    ascii = ascii + 2;
    c = (char) ascii;
    return c;
}

char decrypt_char(char c)
{
    int ascii = (int) c;
    ascii = ascii - 2;
    c = (char) ascii;
    return c;
}

std::string encrypt(std::string s)
{
    std::string encrypted_str;
    for (int i = 0; i < s.length(); i++)
    {
       encrypted_str += encrypt_char(s[i]); 
    }
    return encrypted_str;
}

std::string decrypt(std::string s)
{
    std::string decrypted_str;
    for (int i = 0; i < s.length(); i++)
    {
       decrypted_str += decrypt_char(s[i]); 
    }
    return decrypted_str;
}

int main()
{
    std::string s = "Hello World";
    std::cout << "String to be encrypted: " << s << std::endl;
    std::string encrypted_str = encrypt(s);
    std::cout << "Encrypted String: " << encrypted_str << std::endl;
    std::string decrypted_str = decrypt(encrypted_str);
    std::cout << "Decrypted String: " << decrypted_str << std::endl;
    return 0;
}

