// Struct for defining a point
struct Point{
  double x;
  double y;
};

// Function for calculating the area of a triangle given 3 points
double triangleArea(Point a, Point b, Point c){
  double area = 0.0;

  // Calculate the distances of the 3 sides
  double a_dist = sqrt(pow((b.x - a.x), 2) + pow((b.y - a.y), 2));
  double b_dist = sqrt(pow((c.x - b.x), 2) + pow((c.y - b.y), 2));
  double c_dist = sqrt(pow((a.x - c.x), 2) + pow((a.y - c.y), 2));

  // Calculate the perimeter of the triangle
  double p = (a_dist + b_dist + c_dist) / 2.0;

  // Apply Heron's formula
  area = sqrt(p * (p - a_dist) * (p - b_dist) * (p - c_dist));

  return area;
}

