public static BTreeNode arrayToTree(int[] arr) 
{ 
    if (arr == null || arr.length == 0) { 
        return null; 
    } 

    BTreeNode root = new BTreeNode(arr[0]); 
    Queue<BTreeNode> queue = new LinkedList<BTreeNode>(); 
    queue.add(root); 

    int i = 1; 
    while (!queue.isEmpty() && i < arr.length) { 

        BTreeNode currentNode = queue.poll(); 
        if (arr[i] != null) { 
            currentNode.left = new BTreeNode(arr[i]); 
            queue.add(currentNode.left); 
        } 

        if (i + 1 < arr.length && arr[i + 1] != null) { 
            currentNode.right = new BTreeNode(arr[i + 1]); 
            queue.add(currentNode.right); 
        } 
        i += 2; 
    } 

    return root; 
}

