import numpy as np

class NeuralNetworkClassifier:
    # Initialize the model
    def __init__(self, n_inputs, n_outputs, n_hidden_layers, n_neurons_per_layer):
        self.n_inputs = n_inputs
        self.n_outputs = n_outputs
        self.n_hidden_layers = n_hidden_layers
        self.n_neurons_per_layer = n_neurons_per_layer
        self.weights = self.init_weights()

    # Initialize the weights
    def init_weights(self):
        weights = []
        layer_sizes = [self.n_inputs] + [self.n_neurons_per_layer] * self.n_hidden_layers + [self.n_outputs]
        for i in range(len(layer_sizes) - 1):
            weights.append(np.random.randn(layer_sizes[i], layer_sizes[i+1]))
        return weights

    # Forward propagate input through the neural network
    def forward_propagate(self, x):
        activations = np.array([x])
        for weight in self.weights:
            activations = self.sigmoid(np.matmul(activations[-1], weight))
            activations = np.vstack((activations, activations[-1]))
        return activations[-1]

    # Apply sigmoid function
    def sigmoid(self, x):
        return 1 / (1 + np.exp(-x))

