def is_ascii_decodable(string):
    # Check for empty string
    if len(string) == 0:
        return True

    # Split the string into a list of integers
    string_list = [int(val) for val in string.split(' ')]

    # Check that each integer falls within the valid range of ASCII values
    for val in string_list:
        if val < 0 or val > 127:
            return False

    # Check that the integers correspond to valid ASCII characters
    for val in string_list:
        if chr(val) is None:
            return False

    return True

