//Max Profit Algorithm
//Function takes in an array of stock prices
//Returns the maximum profit

func maxProfit (prices: [Int]) -> Int {
    //Validate stock price array
    guard prices.count > 0 else { return 0 }

    //Start maxProfit at zero
    var maxProfit = 0

    //Iterate through prices array
    for i in 0..<prices.count-1 {

        //Looping over remaining days
        for j in i+1..<prices.count {

            //Calculate profit from buying before and selling later
            let profit = prices[j] - prices[i]

            //Compare maxProfit to potential profit
            maxProfit = max(maxProfit, profit)

        }
    }

    return maxProfit
}

