def bubble_sort(arr):
  # loop through the array
  for i in range(len(arr)-1):
    # loop through each element in the array
    for j in range(len(arr)-i-1):
      # if element is greater than next element
      if arr[j] > arr[j+1]:
        # swap positions
        arr[j], arr[j+1] = arr[j+1], arr[j]
  # return sorted array
  return arr

