def most_frequent(sentence):
    """Find the most frequent words in a given sentence."""
    words = sentence.lower().split()
    word_count = {}

    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    sorted_words = sorted(word_count.items(), key=lambda kv: kv[1], reverse=True)
    return [word for word, _ in sorted_words]

