def minCoinChange(value, coins): 

    # Initialize results array 
    results = [float('inf') for _ in range(value + 1)] 
    results[0] = 0

    # Compute coins required to reach value v 
    for v in range(1, value + 1): 
        for c in coins: 
            if c <= v: 
                res = results[v - c] 
                if res != float('inf') and (1 + res) < results[v]: 
                    results[v] = 1 + res
    return results[value]

