def solve(grid):
    empty_cells = find_empty_cells(grid)
    if not empty_cells:
        return True # Solution was found

    row, col = empty_cells[0]

    for num in range(1, 10):
        if valid_move(grid, row, col, num):
            grid[row][col] = num
            if solve(grid):
                return True

            grid[row][col] = 0
    return False

def find_empty_cells(grid):
    empty_cells = []
    for row in range(9):
        for col in range(9):
            if grid[row][col] == 0:
                empty_cells.append((row, col))
    return empty_cells

def valid_move(grid, row, col, num):
    # Check row.
    if num in grid[row]:
        return False

    # Check column.
    for curr_row in range(9):
        if grid[curr_row][col] == num:
            return False

    # Check 3x3 box.
    box_x = row // 3
    box_y = col // 3

    for i in range(box_x*3, box_x*3 + 3):
        for j in range(box_y*3, box_y*3 + 3):
            if grid[i][j] == num:
                return False

    # No conflicts, thus valid move.
    return True

