public static int sumOfFactors(int num) { 
    int result = 0; 

    for (int i = 1; i <= Math.sqrt(num); i++) { 
        if (num % i == 0) { 
            // If the factors are the same, 
            // add only one of them 
            if (num / i == i) 
                result += i; 

            // Otherwise add both 
            else
                result += (i + num / i); 
        } 
    } 
    return result; 
}

