def check_prime_eratosthenes(num):
    # Create a boolean array with all elements set to True
    primes = [True] * (num + 1)

    # Set 0 and 1 to False as they aren't prime
    primes[0] = primes[1] = False

    # Loop through the array, setting all non-prime numbers to False
    for i in range(2, int(sqrt(num)) + 1):
        if primes[i]:
            for j in range(i ** 2, num + 1, i):
                primes[j] = False

    return primes[num]

