import java.io.BufferedReader;
import java.io.FileReader;
import java.util.StringTokenizer;
import java.util.HashMap;

public class MostProductWords {

    public static void main(String[] args) throws Exception {
        // Hashmap to store words and their products that appear in the text file
        HashMap<String, Integer> wordProduct = new HashMap<>();

        // Read in the text file
        BufferedReader reader = new BufferedReader(new FileReader("Test.txt"));

        // Read in the first line of the file
        String line = reader.readLine();

        // Split the line and store each word in the hashtable
        StringTokenizer tokens = new StringTokenizer(line);
        while (tokens.hasMoreTokens()) {
            String word = tokens.nextToken();
            int product = 1;

            // Calculate the product
            for (int i = 0; i < word.length(); i++) {
                product *= (int)word.charAt(i);
            }

            // Store the word and its product in the Hashmap
            wordProduct.put(word, product);
        }

        // Calculate the maximum product
        int maxProduct = 0;
        String maxWord = "";

        for (String word : wordProduct.keySet()) {
            int product = wordProduct.get(word);
            if (product > maxProduct) {
                maxProduct = product;
                maxWord = word;
            }
        }

        System.out.println("The word with the most product words is: " + maxWord);
    }
}

