    public static void groupAnagrams(String[] words) { 
        HashMap<String, List<String>> hm = new HashMap<String, List<String>>(); 
        for (int i = 0; i < words.length; i++) { 
            char[] word = words[i].toCharArray(); 
            Arrays.sort(word); 
            String stringWord = new String(word); 
            if (hm.containsKey(stringWord)) { 
                hm.get(stringWord).add(words[i]); 
            } else { 
                List<String> anagrams = new ArrayList<String>(); 
                anagrams.add(words[i]); 
                hm.put(stringWord, anagrams); 
            } 
        } 

        for (List<String> anagrams : hm.values()) { 
            for (int i = 0; i < anagrams.size() - 1; i++) { 
                System.out.print(anagrams.get(i) + " "); 
            } 
            System.out.println(anagrams.get(anagrams.size() - 1)); 
        } 
    } 

