function encrypt_caesar_cipher($str, $shift){

    $str_len = strlen($str); 

    // Iterate over the given string 
    for($i = 0; $i < $str_len; $i++){ 
        //for upper and lower case  
        if(ctype_alpha($str[$i])){ 
            // ASCII value 
            $ascii_val = ord($str[$i]); 

            // Gives the CC value for small letters  
            if($ascii_val >= 97 && $ascii_val <= 122){   
                $ascii_val += $shift; 
                if($ascii_val > 122){ 
                    $ascii_val -= 26; 
                } 
                else if($ascii_val < 97){ 
                    $ascii_val += 26; 
                }  
                // Gives the CC values for capital letters  
            } else if($ascii_val >= 65 && $ascii_val <= 90){   
                $ascii_val += $shift; 
                if($ascii_val > 90){ 
                    $ascii_val -= 26; 
                } 
                else if($ascii_val < 65){ 
                    $ascii_val += 26; 
                } 
            } 
            // Replace the character with its CC  
            $str[$i] = chr($ascii_val); 
        } 
    } 
    return $str; 
}

