using namespace std;

// Maze size
int size;

// Maze matrix
int maze[50][50];

// Function to Print Maze
void printMaze() {
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      cout << maze[i][j] << " ";
    }
    cout << endl;
  }
}

void generateMaze(int x, int y) {
  // Array to store the valid neighbors indicating
  // if a wall can be broken down for the generation
  // of a random maze
  int next[4][2] = { {0, 1}, {1, 0}, {0, -1}, {-1, 0} };

  // Randomly select neighbors
  int random_index = rand() % 4;
  int next_x = x + next[random_index][0];
  int next_y = y + next[random_index][1];

  // If the random neighbor is valid and empty
  if (next_x >= 0 && next_x < size && next_y >= 0 && next_y < size && maze[next_x][next_y] == 0) {

    // Break the wall
    maze[x][y] = 0;
    maze[next_x][next_y] = 0;

    // Generate Maze for the next cell
    generateMaze(next_x, next_y);
  }
}

// Function to generate random maze
void mazeGenerator(int n) {
  // Initializing the algorithm
  size = n;
  // Filling the matrix with 1's
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      maze[i][j] = 1;
    }
  }

  // Generate Maze from (0, 0)
  generateMaze(0, 0);

  // Generating the exit
  maze[n - 1][n - 1] = 0;

  // Prints the Maze
  printMaze();
}

int main() {
  int n;
  cin >> n;
  srand (time(NULL));

  // Initializing the matrix
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      maze[i][j] = 1;
    }
  }
  // Generates Maze
  mazeGenerator(n);
  return 0;
}

