public static bool BalancedString(string str) {
 Stack stack = new Stack();

 foreach (char c in str.ToCharArray()) {
  if (c == '{' || c == '[' || c == '(') {
   stack.Push(c);
  } else if (c == '}' && stack.Peek() == '{' 
          || c == ']' && stack.Peek() == '[' 
          || c == ')' && stack.Peek() == '(') {
   stack.Pop();
  } else {
   return false;
  }
 }

 return stack.Count == 0;
}

