class MaxSquareSubMatrix { 
    public static int maxOneSubMatrix(int[][] mat, int m, int n) { 
        int[][] dp = new int[m][n]; 
        int maxVal = 0; 
        for (int i = 0; i < m; i++) { 
            for (int j = 0; j < n; j++) { 
                if (i == 0 || j == 0) 
                    dp[i][j] = mat[i][j]; 
                else if (mat[i][j] == 1) 
                    dp[i][j] = Math.min(dp[i][j - 1], 
                                        Math.min(dp[i - 1][j], dp[i - 1][j - 1])) + 1; 
                maxVal = Math.max(maxVal, dp[i][j]); 
            } 
        } 
        return maxVal; 
    } 

