def maxSubarrayDivisibleK(arr, k): 
    prefixSum = [0] * len(arr)  
    prefixSum[0] = arr[0] 
    for i in range(1, len(arr)): 
        prefixSum[i] = prefixSum[i-1] + arr[i] 

    mapping = {}  

    maxSum = 0
    remainder = 0
    for i in range(len(arr)): 
        remainder = prefixSum[i] % k  
        if remainder == 0:  
            maxSum = max(maxSum, prefixSum[i]);  
        else:  
            num = mapping.get(remainder, 0)  
            maxSum = max(maxSum,  
                         prefixSum[i] - prefixSum[num]); 
        mapping[remainder] = i;  

    return maxSum

