public class Main { 
    public static void main(String[] args) { 
        LinkedList list = new LinkedList(); 

        list.insertAtStart(5); 
        list.insertAtStart(3); 
        list.insertAtStart(2); 
        list.insertAtEnd(7); 
        list.insertAtEnd(8); 

        list.delete(2); 
        list.delete(7); 

        list.display(); 
