import android.app.Activity;  
import android.os.Bundle;  
import android.os.Debug;  
import android.widget.TextView;  

public class MemoryUsage extends Activity {  

    TextView textStatus;  

    @Override  
    public void onCreate(Bundle savedInstanceState) {  
        super.onCreate(savedInstanceState);  
        setContentView(R.layout.main);  

        textStatus = (TextView) findViewById(R.id.textStatus);  
        Runtime runtime = Runtime.getRuntime();  

        // totalMemory() returns the total memory allocated to the app.  
        Long total = runtime.totalMemory() / 1024;  

        // freeMemory() return the memory still available for the app.  
        Long free = runtime.freeMemory() / 1024;  

        // usedMemory() returns the total memory currently used by the app.  
        long used = total - free;  

        // Native heap size.  
        long nativeUsage = Debug.getNativeHeapSize() / 1024;  

        // Native allocated memory.  
        long nativeAllocated = Debug.getNativeHeapAllocatedSize() / 1024;  

        // Native free memory  
        long nativeFree = Debug.getNativeHeapFreeSize() / 1024;  

        textStatus.append("Total: " + total + "kb\n");  
        textStatus.append("Used: " + used + "kb\n");  
        textStatus.append("Free:" + free + "kb\n");  
        textStatus.append("Native Heap Size: " + 
                          nativeUsage + "kb\n");  
        textStatus.append("Native Allocated: " + 
                          nativeAllocated + "kb\n");  
        textStatus.append("Native Free: " + nativeFree + "kb");  
    }  
}

