function sortThree(nums) {
	// First step: find the median of the three numbers
    let median;
    if (nums[0] <= nums[1] && nums[1] <= nums[2] ||
        nums[2] <= nums[1] && nums[1] <= nums[0]) {
        median = nums[1];
    } 
    else if (nums[2] <= nums[0] && nums[0] <= nums[1] ||
        nums[1] <= nums[0] && nums[0] <= nums[2]) {
        median = nums[0];
    }
    else {
        median = nums[2];
    }

    // Second step: sort the numbers
    let sorted = [nums[0], nums[1], nums[2]];
    for (let i = 0; i < 3; i++) {
        let minElem = sorted[i];
        let minIndex = i;
        for (let j = i + 1; j < 3; j++) {
            // Find the smallest element to the right of the current element 
            if (sorted[j] < minElem) {
                minElem = sorted[j];
                minIndex = j;
            }
			// Swap the smallest element with the current one 
            let temp = sorted[i];
            sorted[i] = sorted[minIndex];
            sorted[minIndex] = temp;
        }
    }
    // Output the median of three
    console.log(median);
    // Output the sorted list
    console.log(sorted);
}

