public class JSONParser {
    public static HashMap<String, Object> parseJSON(String jsonString) {
        JSONObject obj = new JSONObject(jsonString);
        HashMap<String, Object> map = new HashMap<>();
        for (String key : obj.keySet()) {
            map.put(key, obj.get(key));
        }
        return map;

    }

    public static void main(String[] args) {
        String jsonString = "{\"name\": \"John Doe\", \"age\": 21, \"isEmployed\": true}";
        HashMap<String, Object> map = parseJSON(jsonString);

        System.out.println(map.get("name"));
        System.out.println(map.get("age"));
        System.out.println(map.get("isEmployed"));
    }
}

