const Random = {
 gaussian: function(mean, stdev) {
    let y2;
    let use_last = false;
    return function() {
        let y1;
        if(use_last) {
           y1 = y2;
           use_last = false;
        }
        else {
            let x1, x2, w;
            do {
                 x1 = 2.0 * Math.random() - 1.0;
                 x2 = 2.0 * Math.random() - 1.0;
                 w  = x1 * x1 + x2 * x2;               
            } while( w >= 1.0);
            w = Math.sqrt((-2.0 * Math.log(w))/w);
            y1 = x1 * w;
            y2 = x2 * w;
            use_last = true;
       }

       let retval = mean + stdev * y1;
       if(retval > 0) 
            return retval;
       return -retval;
   }
 },
 uniform: function (min, max) {
    return Math.random() * (max - min) + min;
 },
 poisson: function (mean) {
  let L = Math.exp(-mean);
  let p = 1.0;
  let k = 0;

  do {
   k++;
   p *= Math.random();
  } while (p > L);

  return k - 1;
 }
};

