public static List<int> IncrementListItems(List<int> list)
{
    // Create a new list with all elements incremented by 1
    List<int> incrementedList = new List<int>();

    // Iterate over the given list
    foreach (int item in list)
    {
        // Increment each element by 1
        int incremented = item + 1;
        // Append the new value to the new list
        incrementedList.Add(incremented);
    }

    // Return the new list with incremented elements
    return incrementedList;
}

