int FindMaxProduct(int[] arr) 
{
    // Store the maximum product
    int maxProduct = 1; 

    // Store the first, second and third largest number 
    int first = int.MinValue, 
        second = int.MinValue, 
        third = int.MinValue; 

    // Traverse array elements to find the 
    // maximum product 
    for (int i = 0; i < arr.Length; i++) 
    { 
         // Update Maximum, second and third
         // if needed 
         if (arr[i] > first) 
         { 
              third = second; 
              second = first; 
              first = arr[i]; 
         } 

        else if (arr[i] > second) 
        { 
             third = second; 
             second = arr[i]; 
        } 

        else if (arr[i] > third) 
            third = arr[i]; 
    } 

    // Return the maximum product of 
    // three numbers 
    return maxProduct = first * 
                        second * third; 
}

