def min_coins(n):
    coins = [1, 3, 5]
    min_coins = [float("inf")] * (n + 1)
    min_coins[0] = 0

    for i in range (1, n + 1):
        for coin in coins:
            if (i - coin) >= 0:
                min_coins[i] = min(min_coins[i], min_coins[i - coin] + 1)

