def delete_node_with_value(node_head, target_value):
    # To delete all nodes with the value of target_value, we traverse all nodes in the linked list and remove all nodes that have target_value.
    current_node = node_head
    prev = None
    while current_node is not None:
        if current_node.val == target_value:
            # If the head of the linked list has a target_value, then we just update the head with its next node
            if prev is None:
                node_head = current_node.next
            else:
                prev.next = current_node.next
        else:
            prev = current_node
        current_node = current_node.next

    return node_head

