public class UniqueChar { 

    static final int NO_OF_CHARS = 256; 

    static int maxUniqueChar(String str) 
    { 
        int n = str.length(); 

        int max_unique = 0; 

        int curr_unique = 0; 

        int visited[] = new int[NO_OF_CHARS]; 

        for (int i = 0; i < n; i++) { 
            if (visited[str.charAt(i)] == 0) { 
                visited[str.charAt(i)] = 1; 
                curr_unique++; 
            } 

            else { 
                visited[str.charAt(i)]++; 
            } 
            if (curr_unique > max_unique) 
                max_unique = curr_unique; 
        } 
        return max_unique; 
    } 

    public static void main(String args[]) 
    { 
        String str = "ABCDBCA"; 
        int len = maxUniqueChar(str); 
        System.out.println(len); 
    } 
}

