def find_most_frequent(array):
    """Returns the most frequent element in the given array"""
    frequencies = {}
    for num in array:
        if num in frequencies:
            frequencies[num] += 1
        else:
            frequencies[num] = 1
    max_count = max(frequencies.values())
    for key, value in frequencies.items():
        if value == max_count:
            most_frequent = key
    return most_frequent

// Brute-force solution
public List<List<Integer>> solveTSP(int[][] distances) {
    List<List<Integer>> result = new ArrayList<>();
    int numCities = distances.length;
    int start = 0;
    List<Integer> path = new ArrayList<>(); 
    path.add(start);

    solveTSPUtil(result, distances, numCities, start, path);
    return result;
}

public void solveTSPUtil(List<List<Integer>> result, int[][] distances, int numCities, int start, List<Integer> path) {
    if (path.size() == numCities && distances[start][0] > 0) {
        // We have reach the end, just add the start city for a complete cycle.
        path.add(start);
        result.add(new ArrayList<>(path));
    }

    for (int i = 0; i < numCities; i++) {
        // Current city is "i".
        if (!path.contains(i) && distances[start][i] > 0) {
            // We can move to city "i".
            path.add(i);
            // Move to next city.
            solveTSPUtil(result, distances, numCities, i, path);
            // Backtrack.
            path.remove(path.size() - 1);
        }
    }
}

