function longestSubstring(str) {
    let len = str.length;
    let maxLength = 0;
    let currentSubstring = 0;
    let start = 0;

    for (let i = 0; i < len; i++) {
        let currentSubstring = 0;

        while (str[i] === str[i + 1]) {
            currentSubstring = currentSubstring + 1;
            i = i + 1;
        }

        if (maxLength < currentSubstring) {
            maxLength = currentSubstring;
            start = i - maxLength;
        }
    }
    let longestSubstring = str.substring(start, start + maxLength + 1);
    return longestSubstring;
}

