def concatenate_in_order(string1, string2):
    result = ""
    s1 = 0 # Position in string1
    s2 = 0 # Position in string2

    while s1 < len(string1) and s2 < len(string2):
        if string1[s1] < string2[s2]:
            result += string1[s1]
            s1 += 1
        else:
            result += string2[s2]
            s2 += 1

    # Append the remainder of the longer string
    if s1 < len(string1):
        result += string1[s1:]
    else:
        result += string2[s2:]

