def calculateLevenshteinDistance(str1, str2): 
    n = len(str1)
    m = len(str2)

    # Create a matrix to store results 
    dp = [[0 for x in range(m + 1)] for x in range(n + 1)] 

    # Initialize the first row and column with the difference of lengths
    for i in range(n + 1): 
        for j in range(m + 1): 

            if i == 0: 
                dp[i][j] = j
            elif j == 0: 
                dp[i][j] = i

    # Iterate through the matrix and replace the 
    # cells with the required edit distance
    for i in range(1, n + 1): 
        for j in range(1, m + 1): 
            if str1[i-1] == str2[j-1]: 
                dp[i][j] = dp[i-1][j-1]
            else: 
                dp[i][j] = 1 + min(dp[i][j-1],        # Insert 
                                   dp[i-1][j],        # Remove 
                                   dp[i-1][j-1])    # Replace 

    return dp[n][m]

public class BubbleSort {

 public static void sort(int[] input) {
  int n = input.length;
  int temp = 0;

  for(int i=0; i < n; i++){
   for(int j=1; j < (n-i); j++){
    if(input[j-1] > input[j]){
     temp = input[j-1];
     input[j-1] = input[j];
     input[j] = temp;
    }
