#include <iostream> 
#include <string> 
#include <stack> 

using namespace std; 

// Function to evaluate an expression 
int evaluate (string expression); 

int main() 
{ 
 string expression = "(2 * 5) - 3"; 

 cout << evaluate(expression) << endl; 

 return 0; 
} 

// Function to evaluate an expression 
int evaluate(string expression) 
{ 
 stack <int> values; 
 stack <char> ops; 

 for (int i = 0; i < expression.length(); i++) { 

 // Current token is a whitespace, 
 // skip it. 
 if (expression[i] == ' ') 
 continue; 

 // Current token is an opening 
 // brace, push it to 'ops' 
 else if (expression[i] == '(') 
 ops.push(expression[i]); 

 // Current token is a number, push 
 // it to stack for numbers. 
 else if (isdigit(expression[i])) { 
 int val = 0; 

 // There may be more than one 
 // digits in number. 
 while (i < expression.length() && 
 isdigit(expression[i])) 
 { 
 val = (val*10) + (expression[i]-'0'); 
 i++; 
 } 

 i--; 

 values.push(val); 
} 

// Closing brace encountered, 
// solve entire brace. 
else if (expression[i] == ')') 
{ 
 while (!ops.empty() && ops.top() != '(') 
 { 
 int val2 = values.top(); 
 values.pop(); 
 int val1 = values.top(); 
 values.pop(); 
 char op = ops.top(); 
 ops.pop(); 
 values.push(operate(val1, val2, op)); 
 } 

// pop opening brace. 
ops.pop(); 
} 

// Current token is an operator. 
else
{ 
 // While top of 'ops' has same or 
 // greater precedence to current 
 // token, which is an operator. 
 // Apply operator on top of 'ops' 
 // to top two elements in values stack. 
 while (!ops.empty() && Prec(ops.top()) 
 >= Prec(expression[i])) 
 { 
 int val2 = values.top(); 
 values.pop(); 

 int val1 = values.top(); 
 values.pop(); 

 char op = ops.top(); 
 ops.pop(); 

 values.push(operate(val1, val2, op)); 
 } 

 // Push current token to 'ops'. 
 ops.push(expression[i]); 
} 
} 

// Entire expression has been parsed at this 
// point, apply remaining ops to remaining 
// values. 
while (!ops.empty()) 
{ 
 int val2 = values.top(); 
 values.pop(); 

 int val1 = values.top(); 
 values.pop(); 

 char op = ops.top(); 
 ops.pop(); 

 values.push(operate(val1, val2, op)); 
} 

// Top of 'values' contains result, 
// return it. 
return values.top(); 
} 

// Returns true if 'op2' has higher or same 
// precedence as 'op1', 
// otherwise returns false. 
int Prec(char op) 
{ 
 if(op == '+'||op == '-') 
 return 1; 
 if(op == '*'||op == '/') 
 return 2; 
 return 0; 
} 

// A utility function to apply 
// an operator 'op' on operands 'a' 
// and 'b'. Return the result. 
int operate(int a, int b, char op) 
{ 
 switch (op) 
 { 
 case '+': return a + b; 
 case '-': return a - b; 
 case '*': return a * b; 
 case '/': return a / b; 
 } 
}

