const hexToInt = (hexString) => {
    let parts = hexString.split("x");
    if(parts.length < 2){
        return -1;
    }
    let hex = parts[1];
    let result = 0;
    for(let i=0; i< hex.length; i++){
        let currentChar = hex.charAt(i).toUpperCase();
        let currentCharValue = 0;
        if(currentChar >= 'A' && currentChar <= 'F'){
            currentCharValue = (currentChar.charCodeAt(0) - 'A'.charCodeAt(0)) + 10;
        } else {
            currentCharValue = currentChar.charCodeAt(0) - '0'.charCodeAt(0);
        }
        let powerInt = (hex.length - i - 1);
        result += currentCharValue * (16 ** powerInt);
    }
    return result;
};

