import numpy as np

def find_shortest_path(board, goal_position, start_position):
  board = np.array(board)
  frontier = [[start_position]] 
  visited = set()
  while frontier:
    path = frontier.pop(0)
    pos = path[-1]
    if pos == goal_position: 
      return path
    if pos not in visited:
      visited.add(pos)
      for neighbor in get_neighbors(board, pos):
        new_path = list(path)
        new_path.append(neighbor)
        frontier.append(new_path)

def get_neighbors(board, position):
    x, y = position
    neighbors = []
    if x - 1 >= 0:
        neighbors.append((x - 1, y))
    if x + 1 <= len(board[0]) - 1:
        neighbors.append((x + 1, y))
    if y - 1 >= 0:
        neighbors.append((x, y - 1))
    if y + 1 <= len(board) - 1:
        neighbors.append((x, y + 1))
    return neighbors

