def longest_common_substring(str1, str2):
    result = ""
    longest_length = 0

    str1_length = len(str1)
    str2_length = len(str2)

    for i in range(str1_length):
        for j in range(str2_length):
            l = 0
            if str1[i] == str2[j]:
                # find length of common substring
                while (i + l < str1_length and j + l < str2_length and str1[i + l] == str2[j + l]):
                    l += 1

                # update result and longest length if we find a longer substring
                if l > longest_length:
                    result = str1[i:i+l]
                    longest_length = l
    return result

public class QuickSort {

   public static void sort(int[] arr, int low, int high) {
      int partitionIndex;
      if (low < high) {
         // Select the pivot element
         partitionIndex = partition(arr, low, high);

         // Sort elements before partition and after partition
         sort(arr, low, partitionIndex-1);
         sort(arr, partitionIndex+1, high);
      }
   }

   private static int partition(int[] arr, int low, int high) {
      int pivot = arr[high];
      int i = low-1;
      for (int j = low; j < high; j++) {
         if (arr[j] <= pivot) {
            i++;
            //swap arr[i] and arr[j]
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
         }
      }

      //swap arr[i+1] and arr[high] (or pivot)
      int temp = arr[i+1];
      arr[i+1] = arr[high];
      arr[high] = temp;

      return i+1;
   }
   public static void main(String[] args) {

      int[] arr = {8, 4, 6, 1, 3, 5, 2, 7};
      int n = arr.length;
      sort(arr, 0, n-1);

      System.out.println("Sorted array");
      printArray(arr);
   }
   public static void printArray(int[] arr) {
      for (int i=0; i<arr.length; i++) {
         System.out.print(arr[i]+" ");
      }
      System.out.println();
   }
}

