pair<int, int> twoSum(vector<int>& arr, int target) {
 unordered_map<int, int> map;
 for (int i = 0; i < arr.size(); i++) {
  int diff = target - arr[i];
  if (map.find(diff) != map.end())
   return make_pair(map[diff], i);

  map[arr[i]] = i;
 }

 return make_pair(-1, -1);
}

