def detect_cycle(linked_list):
    # Initialize the slow and fast pointer
    slow = linked_list.head
    fast = linked_list.head
    # Iterate through the linked list
    while slow and fast and fast.next:
        iterate_slow_pointer(slow)
        iterate_fast_pointer(fast)

        # If the slow and fast pointer meet,
        # There must be a cycle
        if same_node(slow, fast):
            return true

    return false


def iterate_slow_pointer(slow_pointer):
    slow_pointer = slow_pointer.next


def iterate_fast_pointer(fast_pointer):
    fast_pointer = fast_pointer.next
    if fast_pointer.next:
        fast_pointer = fast_pointer.next


def same_node(slow_pointer, fast_pointer):
    return slow_pointer == fast_pointer

