using namespace std;

void quick_sort(int arr[], int low, int high)
{
    int pivot, i, j;
    if (low < high) {
        pivot = low;
        i = low;
        j = high;
        while (i < j) {
            while (arr[i] <= arr[pivot] && i <= high) i++;

            while (arr[j] > arr[pivot] && j >= low) j--;

            if (i < j) {
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }

        int temp = arr[j];
        arr[j] = arr[pivot];
        arr[pivot] = temp;

        quick_sort(arr, low, j - 1);
        quick_sort(arr, j + 1, high);
    }
}

