def longest_common_subarray(arr1, arr2):
    max_len = 0
    subarray = []

    for i in range(len(arr1)):
        for j in range(len(arr2)):
            match_len = 0

            while arr1[i+match_len] == arr2[j+match_len] and i+match_len < len(arr1) and j+match_len < len(arr2):
                match_len += 1

            if match_len > max_len:
                max_len = match_len
                subarray = arr1[i:i+match_len]

    if len(subarray) == 0:
