def binarySearch(list: Array[Int], key: Int): Int =  
{ 
   var lowerBound = 0
   var upperBound = list.length - 1
   var mid = 0
   while (lowerBound <= upperBound) { 
    mid = lowerBound + (upperBound - lowerBound) / 2
    if (list(mid) == key) 
    return mid
    else if (list(mid) < key) 
     lowerBound = mid + 1
    else 
     upperBound = mid - 1
   } 
  return -1
}

