std::vector<int> compute_union(std::vector<int> A, std::vector<int> B) {
    std::vector<int> result;
    int i = 0;
    int j = 0;
    while (i < A.size() && j < B.size()) {
        int x = A[i];
        int y = B[j];
        if (x == y) {
            result.push_back(x);
            i++;
            j++;
        } else if (x < y) {
            result.push_back(x);
            i++;
        } else {
            result.push_back(y);
            j++;
        }
    }

    while (i < A.size()) {
        result.push_back(A[i]);
        i++;
    }
    while (j < B.size()) {
        result.push_back(B[j]);
        j++;
    }
    return result;
}

