Create a binary search tree from the array
"""

# Define a node
class Node: 
    def __init__(self, key): 
        self.left = None
        self.right = None
        self.val = key 

# Insert node into a tree
def insert(root, node): 
    if root is None: 
        root = node 
    else: 
        if root.val < node.val: 
            if root.right is None: 
                root.right = node 
            else: 
                insert(root.right, node) 
        else: 
            if root.left is None: 
                root.left = node 
            else: 
                insert(root.left, node) 

# Function to build a binary search tree
def build_tree(input_list):
    root = Node(input_list[0])
    for key in input_list[1:]:
        insert(root, Node(key))
    return root

