public class QuickSort {

 public static void main(String[] args) {
 int[] array = {9, 5, 3, 6, 2, 8};

 quickSort(array, 0, array.length - 1);

 System.out.println("Sorted array:");
 for (int i : array) {
 System.out.print(i + " ");
 }
 }

 public static void quickSort(int[] array, int low, int high) 
 {
 // If the array contains one element or none, it is sorted
 if (array.length <= 1) {
 return;
 }

 int mid = (low + high) / 2;
 int pivot = array[mid];

 int i = low;
 int j = high;

 // Partition the array
 while (i < j) {
 while (array[i] < pivot) {
 i++;
 }

 while (array[j] > pivot) {
 j--;
 }

 if (i <= j) {
 int temp = array[i];
 array[i] = array[j];
 array[j] = temp;

 i++;
 j--;
 }
 }

 // Recursively call quickSort
 if (low < j) {
 quickSort(array, low, j);
 }

 if (i < high) {
 quickSort(array, i, high);
 }
 }
}

