Node* concatLinkedLists(Node *head1, Node *head2) {
    if(head1 == NULL) 
        return head2; 
    if(head2 == NULL) 
        return head1; 

    Node *last1 = head1->next; 
    Node *last2 = head2->next; 

    while (last1->next != NULL) 
        last1 = last1->next; 

    while (last2->next != NULL) 
        last2 = last2->next; 

    // Connecting two linked lists 
    last1->next = head2; 
    last2->next = NULL; 

    return head1; 
}

