def solve_8_puzzle(start):
    moves = {"R":(0, 1), "L":(0, -1), "U":(-1, 0), "D":(1, 0)}
    edges = deque([start])
    explored = set()

    while edges:
        edge = edges.popleft()
        explored.add(edge)
        row, col = [int(x) for x in edge.index(0)]

        for move, (drow, dcol) in moves.items():
            new_row = row + drow
            new_col = col + dcol
            new_edge = list(edge)
            if 0 <= new_row < 3 and 0 <= new_col < 3:
                new_edge[row * 3 + col], new_edge[new_row * 3 + new_col] = \
                    new_edge[new_row * 3 + new_col], new_edge[row * 3 + col]
                if tuple(new_edge) not in explored:
                    explored.add(tuple(edge))
                    edges.append(tuple(new_edge))

                    if new_edge == [1, 2, 3, 4, 5, 6, 7, 8, 0]:
                        return edges
    return edges

