def most_common_word(sentence):
    words = sentence.split(" ")
    freq = {}
    for word in words:
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1

    max_word, max_freq = None, 0
    for word, count in freq.items():
        if count > max_freq:
            max_word, max_freq = word, count

    return max_word

