def primeCount(n): 
    count = 0
    # 2 is the only even prime
    if n > 2:
        count += 1
    # Count all the other odd primes
    for i in range(3, n + 1, 2):
        prime = True
        for j in range(2, i):
            if i % j == 0:
                prime = False
                break
        if prime:
            count += 1
    return count

