function modifiedQuicksort(arr) {
 let low = 0;
 let high = arr.length - 1;

 quickSortHelper(arr, low, high);

 return arr;
}

function quickSortHelper(arr, low, high) {
 if (low < high) {
   let counter = low;
   let sameValueCounter = 0;
   let pivot = arr[high];

   for (let i = low; i < high; i++) {
     if (arr[i] < pivot) {
       swap(arr, counter, i);
       counter++;
     } else if (arr[i] === pivot) {
       sameValueCounter++;
     }
   }

   let pivotIndex;
   if (sameValueCounter > 1) {
     pivotIndex = counter + ((sameValueCounter - 1) / 2);
   } else {
     pivotIndex = counter;
   }

   swap(arr, pivotIndex, high);

   quickSortHelper(arr, low, pivotIndex - 1);
   quickSortHelper(arr, pivotIndex + 1, high);
 }
}

function swap(arr, i, j) {
 let temp = arr[i];
 arr[i] = arr[j];
 arr[j] = temp;
}

