def find_missing_positive_number(arr):
  n = len(arr)
  for i in range(n):
    if (arr[i] <= 0 or arr[i] > n):
      continue
    val = arr[i]
    while (arr[val - 1] != val):
      next_val = arr[val - 1]
      arr[val - 1] = val
      val = next_val
      if (val <= 0 or val > n):
        break
  for i in range(n):
    if (arr[i] != i+1):
      return i+1
  return n+1

