void reverse(list_node* head) 
{ 
    if(head == NULL) 
        return; 

    list_node *prev = NULL; 
    list_node *current = head; 
    list_node *next; 
    while (current != NULL) 
    { 
        next = current->next;   
        current->next = prev;    
        prev = current; 
        current = next; 
    } 
    root = prev; 
}

