function generateMaze(rows, cols) {
 // Create a two-dimensional array for the maze
 let maze = new Array(rows);
 for (let i = 0; i < rows; i++) {
 maze[i] = new Array(cols);
 }

 // randomly select starting cell
 const randomRow = Math.floor(Math.random() * rows);
 const randomCol = Math.floor(Math.random() * cols);
 let currentCell = [randomRow, randomCol];
 maze[currentCell[0]][currentCell[1]] = 0;

 // Initialize a variable to hold the visited cells
 let visitedCells = 1;
 let totalCells = rows * cols;

 // Create a loop to iterate through each cell
 while (visitedCells < totalCells) {
 // Identify all possible directions from the current cell
 let direction = [];
 if (currentCell[0] + 2 < rows && maze[currentCell[0] + 2][currentCell[1]] == undefined) {
 direction.push('down') # East
 }
 if (currentCell[1] + 2 < cols && maze[currentCell[0]][currentCell[1] + 2] == undefined) {
 direction.push('right') # South
 }
 if (currentCell[0] - 2 >= 0 && maze[currentCell[0] - 2][currentCell[1]] == undefined) {
 direction.push('up') # West
 }
 if (currentCell[1] - 2 >= 0 && maze[currentCell[0]][currentCell[1] - 2] == undefined) {
 direction.push('left') # North
 }

 // If there are possible directions available, select one randomly
 if (direction.length > 0) {
 let dir = direction[Math.floor(Math.random() * direction.length)];
 // Move in this direction and create a wall between the current element and its neighbor
 switch (dir) {
 case 'down':
 maze[currentCell[0] + 2][currentCell[1]] = 0;
 maze[currentCell[0] + 1][currentCell[1]] = 1;
 currentCell = [currentCell[0] + 2, currentCell[1]];
 break;
 case 'right':
 maze[currentCell[0]][currentCell[1] + 2] = 0;
 maze[currentCell[0]][currentCell[1] + 1] = 1;
 currentCell = [currentCell[0], currentCell[1] + 2];
 break;
 case 'up':
 maze[currentCell[0] - 2][currentCell[1]] = 0;
 maze[currentCell[0] - 1][currentCell[1]] = 1;
 currentCell = [currentCell[0] - 2, currentCell[1]];
 break;
 case 'left':
 maze[currentCell[0]][currentCell[1] - 2] = 0;
 maze[currentCell[0]][currentCell[1] - 1] = 1;
 currentCell = [currentCell[0], currentCell[1] - 2];
 break;
 }
 visitedCells++;
 }
 // otherwise go back to the previous cell and try again
 else {
 currentCell = prevCell;
 }
 // save current cell for future reference
 prevCell = currentCell;
 }

 return maze;
}

