class Scheduler
{
 public:
 Scheduler() {};

 void add_task(int id, void (*task)(), int interval);
 void remove_task(int id);

 private:
 void scheduler_loop();

 mutex tasks_mutex_;
 map<int, pair<function<void()>, int>> tasks_;
};

void Scheduler::add_task(int id, void (*task)(), int interval) {
 lock_guard<mutex> lock(tasks_mutex_);
 tasks_[id] = make_pair(function<void()>(task), interval);
}

void Scheduler::remove_task(int id) {
 lock_guard<mutex> lock(tasks_mutex_);
 tasks_.erase(id);
}

void Scheduler::scheduler_loop() {
 while (true) {
  // lock the task list
  unique_lock<mutex> task_lock(tasks_mutex_);

  for (auto& task : tasks_) {
   task_lock.unlock();

   task.second.first();

   this_thread::sleep_for(chrono::milliseconds(task.second.second));

   // lock the task list again
   task_lock.lock();
  }
 }
}

