function generateAnagrams(word) {
 let results = [];

 if (word.length === 1) {
 results.push(word);
 return results;
 }

 // For each letter in the word
 for (let i = 0; i < word.length; i++) {
 let currentChar = word[i];

 // Keep the other letters in the word
 let otherChars = word.substring(0, i) + word.substring(i + 1);

 // Generate the anagrams of the other letters
 let otherCharsAnagrams = generateAnagrams(otherChars);

 for (let j = 0; j < otherCharsAnagrams.length; j++) {
 let word = currentChar + otherCharsAnagrams[j];
 results.push(word);
 }
 }

 return results;
}

