void sortedInsert(int arr[], int n, int num) 
{ 
    // Find the index of the first element that is larger than the new number
    int index = -1;
    for (int i=0; i<n; i++) { 
        if (num < arr[i]) {
            index = i;
            break;
        }
    } 

    // shift all elements from index one step to the right
    for (int i=n-1; i>=index; i--) 
        arr[i + 1] = arr[i]; 

    // insert the new number in correct position
    arr[index] = num; 
}

