def find_num_islands(grid):
    if not grid:
        return 0

    rowSize = len(grid)
    colSize = len(grid[0])
    numIslands = 0

    for row in range(rowSize):
        for col in range(colSize):
            if grid[row][col] == 1:
                numIslands += dfs(grid, row, col)

    return numIslands

def dfs(grid, row, col):
    if row<0 or row>=len(grid) or col<0 or col>=len(grid[0]) or grid[row][col]==0:
        return 0

    grid[row][col]==0
    dfs(grid, row+1, col)
    dfs(grid, row-1, col)
    dfs(grid, row, col+1)
    dfs(grid, row, col-1)

    return 1

