    public static int countPalindromes(String input) {
        int count = 0;
        char[] arr = input.toCharArray();

        for (int start = 0; start < arr.length; start++) {
            for (int end = start + 2; end <= arr.length; end++) {
                String str = input.substring(start, end);
                char[] strArr = str.toCharArray();
                boolean isPalin = true;
                for (int i = 0; i < strArr.length / 2; i++) {
                    if (strArr[i] != strArr[strArr.length - i - 1]) {
                        isPalin = false;
                        break;
                    };
                }
                if (isPalin) count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        String input = "madamracecaracemadamsalamasasdfe";
        System.out.println("The number of palindromes in the given string is: " + countPalindromes(input));
    }
}

