  for (let player in scores) {
    let i = sortedScores.length;
    while (i > 0 && sortedScores[i - 1].score < scores[player]) {
      sortedScores[i] = sortedScores[i - 1];
      i--;
    }
    sortedScores[i] = {
      player: player,
      score: scores[player],
    };
  }
  return sortedScores;
}

