public static int[] insertElement(int[] arr, int element) {
    // Create new array with one additional spot
    int[] newArr = new int[arr.length+1];

    // Counter for new array
    int j = 0;

    // Insert elements from original until element needs to be inserted
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < element) {
            newArr[j] = arr[i];
            j++;
        } else {
            break;
        }
    }

    // Insert new element
    newArr[j] = element;
    j++;

    // Add the rest of the elements from original array
    for (int i = j - 1; i < arr.length; i++) {
        newArr[j] = arr[i];
        j++;
    }

    return newArr;
}

