public class TicTacToe {

 public static final int X = 1, O = -1;
 public static final int EMPTY = 0;

 private int board[][] = new int[3][3];
 private int player;

 //constructor 
 public TicTacToe() {
  clearBoard();
 }

 public void clearBoard() {
  for (int i = 0; i < 3; i++)
   for (int j = 0; j < 3; j++)
    board[i][j] = EMPTY; //every cell should be empty
  player = X;
 }

 public void putSign(int row, int col) {
  if ((row >= 0) && (row < 3)) {
   if ((col >= 0) && (col < 3)) {
    if (board[row][col] == EMPTY) {
     board[row][col] = player;  //place the sign for the current player
     player = -player;
    }
   }
  }
 }

 public boolean isWin(int player) {
  return ((board[0][0] + board[0][1] + board[0][2] == player*3) 
     || (board[1][0] + board[1][1] + board[1][2] == player*3) 
     || (board[2][0] + board[2][1] + board[2][2] == player*3) 
     || (board[0][0] + board[1][0] + board[2][0] == player*3) 
     || (board[0][1] + board[1][1] + board[2][1] == player*3) 
     || (board[0][2] + board[1][2] + board[2][2] == player*3) 
     || (board[0][0] + board[1][1] + board[2][2] == player*3) 
     || (board[2][0] + board[1][1] + board[0][2] == player*3));
 }

 public int winner() {
  if (isWin(X)) {
   return X;
  } else if (isWin(O)) {
   return O;
  } else {
   return 0;
  }
 }

 public String toString() {
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < 3; i++) {
   for (int j = 0; j < 3; j++) {
    switch (board[i][j]) {
    case X: 
     sb.append("X"); break;
    case O: 
     sb.append("O"); break;
    case EMPTY: 
     sb.append(" "); break;
    }
    if (j < 2) {
     sb.append("|");
    }
   }
   if (i < 2) {
    sb.append("\n-----\n");
   }
  }
  return sb.toString();
 }

 public static void main(String[] args) {
  TicTacToe game = new TicTacToe();
  // X moves
  game.putSign(1,1);
  game.putSign(0,2);
  game.putSign(2,2);

  // O moves
  game.putSign(0,0);
  game.putSign(0,1);
  game.putSign(2,1);
  game.putSign(1,2);
  game.putSign(2,0);

  System.out.println(game);
  int winner = game.winner();
  String[] outcome = {"O wins", "Tie", "X wins"}; // rely on the ordering
  System.out.println(outcome[1 + winner]);
 }
}

