public class LinkedList { 

    // Node class    
    private class Node { 
        int data; 
        Node next; 

        Node(int data) {  
            this.data = data; 
        } 
    } 

    // Head Node 
    Node head; 

    // Insert at the end of the list
    public void insert(int data) { 
        // Creating a new node 
        Node newNode = new Node(data); 

        // If the Linked List is empty, 
        // then make the new node as head 
        if (head == null) { 
            head = newNode; 
            return; 
        } 

        // Else, traverse till the last node 
        // and insert the new Node there 
        Node lastNode = head;
        while (lastNode.next != null) {   
            lastNode = lastNode.next; 
        }

        // Inserts the newNode at lastNode 
        lastNode.next = newNode;
    } 

    // Delete Node with the given value 
    public void delete(int data) 
    {
        // Store head Node
        Node temp = head, prev = null; 

        // If head Node is the given Node
        if (temp != null && temp.data == data) 
        { 
            head = temp.next; // Changed head 
            return; 
        } 

        // Find the Node to be deleted from 
        // the List and set previous node
        while (temp != null && temp.data != data)
        { 
            prev = temp; 
            temp = temp.next; 
        }     

        // If the Node with given value was not present
        if (temp == null) 
            return; 

        // Remove the Node link
        prev.next = temp.next; 
    }
 }

def caesar_cipher(string, shift):
    result = ""
    for char in string:
        if char.isalpha():
            num = ord(char)
            num += shift
            if char.isupper():
                if num > ord('Z'):
                    num -= 26
                elif num < ord('A'):
                    num += 26
            elif char.islower():
                if num > ord('z'):
                    num -= 26
                elif num < ord('a'):
                    num += 26
            result += chr(num)
        else:
            result += char
    return result

