    for edge in edges:
      edge_cost = node[1] + edge[1]
      if edge[0] not in visited and (edge[0] not in cost or edge_cost < cost[edge[0]]):
        cost[edge[0]] = edge_cost
        fringe.append([edge[0], edge_cost])
    fringe.sort(key=lambda x:x[1])

