import scala.collection.mutable.ArrayBuffer

def findSecondLargest(inputStream: Seq[Int]): Int = {
  //Buffer to store numbers
  val buffer = ArrayBuffer[Int]()

  //Traverse the stream and update the buffer
  for (num <- inputStream) {
    if (buffer.size < 2) {
      buffer += num
    } else {
      //Sort the buffer and update as needed
      buffer.sortInPlace()
      if (buffer(0) < num) {
        buffer(0) = num
      }
    }
  }

  //Return the second largest number in the buffer
  if (buffer.size > 1) buffer(1) else -1
}

