import java.util.Map; 
import java.util.HashMap; 

public class WordCounter { 
    // Function to count the occurrences of words 
    public static Map<String, Integer> countWords(String str) 
    { 
        // Create an empty HashMap 
        Map<String, Integer> map = new HashMap<>(); 

        // Split the String into words 
        String[] words = str.split(" "); 

        // Iterate through each word 
        for (String word : words) { 
            // If word is already present in map 
            // Increase the count by 1 
            if (map.containsKey(word)) { 
                int count = map.get(word); 
                map.put(word, count + 1); 
            } 
            // otherwise put the word in map with count as 1 
            else { 
                map.put(word, 1); 
            } 
        } 

        // Return the constructed HashMap 
        return map; 
    } 

    public static void main(String[] args) 
    { 
        // Given string
        String str = "The quick brown fox jumps over the lazy dog"; 

        // Function call
        Map<String, Integer> map = countWords(str); 

        // Print the count of each word
        for (String word : map.keySet()) 
            System.out.println(word + ": " + map.get(word)); 
    } 
}

