import React, { Component } from 'react';
import axios from 'axios';
import Article from './Article';

interface Props {}
interface State {
  articles: { title: string, content: string }[];
  selectedArticle: string;
}

export default class ArticleList extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      articles: [],
      selectedArticle: ''
    };
  }

  componentDidMount() {
    this.fetchArticles();
  }

  async fetchArticles() {
    const response = await axios.get(`<your api endpoint>`);
    const articles = response.data as Array<{ title: string; content: string }>;
    this.setState({ articles });
  }

  handleArticleClick = (title: string) => {
    this.setState({ selectedArticle: title });
  };

  render() {
    const { articles, selectedArticle } = this.state;

    return (
      <div>
        {articles.map((article) => (
          <div
            key={article.title}
            className={article.title === selectedArticle ? 'selected' : ''}
            onClick={() => this.handleArticleClick(article.title)}
          >
            {article.title}
          </div>
        ))}
        {selectedArticle &&
          articles
            .filter((article) => article.title === selectedArticle)
            .map((article) => (
              <Article key={article.title} title={article.title} content={article.content} />
            ))}
      </div>
    );
  }
}

