    if(num < 0){
        return false;
    }

    if(num===0 || num===1){
        return true;
    }

    let x = 0; 
    let y = 1; 
    let fib = 0;

    while (fib < num){
        fib = x + y;
        x = y;
        y = fib;
    } 

    return (fib === num);
}

