int maxIntervalOverlap(vector<pair<int, int>> intervals) 
{ 
 int maxOverlaps = 0; 
 int overlapCount = 0; 

 sort(intervals.begin(), intervals.end()); 

 vector<int> overlaps(intervals.size(), 0); /* Initialize all values in overlaps as 0 */ 

 for (int i = 0; i < intervals.size(); i++) { 
 overlapCount = 0; 

 for (int j = 0; j < i; j++) { 
 /* If current interval overlaps with the interval j whose 
    end time is already processed, increment overlap count */ 
 if (intervals[i].first <= intervals[j].second) { 
   overlapCount += overlaps[j]; 
   /* Update the maximum overlap     */ 
   maxOverlaps = max(maxOverlaps, overlapCount); 
    } 
   } 

   /* update overlap count of current interval */ 
   overlaps[i] = overlapCount + 1; 
   /* Update the maximum overlap     */ 
   maxOverlaps = max(maxOverlaps, overlaps[i]); 
    } 

 return maxOverlaps; 
} 

