public class TextAmender {
    public static void main(String[] args) {
        String text = "This is an example sentence with some unwanted words"; 
        String[] wordsToRemove = {"unwanted", "words"};
        String amendedText = amendText(text, wordsToRemove);
        System.out.println("Amended Text: " + amendedText);
    }

    public static String amendText(String text, String[] wordsToRemove) {
        String[] words = text.split(" ");
        String amendedText = "";
        for (String word : words) {
            boolean shouldRemove = false;
            for (String removeWord : wordsToRemove) {
                if (word.equals(removeWord)) {
                    shouldRemove = true;
                    break;
                }
            }
            if (!shouldRemove) {
                amendedText += word + " ";
            }
        }
        return amendedText.trim();
    }
}

