vector< vector<int> > CombineMatrices(vector< vector<int> > matrix1, 
                                     vector< vector<int> > matrix2) 
{ 
    if (matrix1.size() != matrix2.size()) 
        return {};

    vector< vector<int> > combinedMatrix(matrix1.size() , vector<int> (matrix1[0].size() +   matrix2[0].size(), 0)); 

