def find_num_paths(N):
    # Base case
    if N == 0 or N == 1:
        return 1

    # Create a n x n grid
    dp = [[0 for i in range(N)] for j in range(N)]

    # Initialize columns
    for i in range(N):
        dp[0][i] = 1
        dp[i][0] = 1

    # Fill the grid row-wise  
    for i in range(1, N): 
        for j in range(1, N): 
            dp[i][j] = dp[i-1][j] + dp[i][j-1] 

    return dp[N-1][N-1]

def primeNumberGenerator(n):
    prime = [True for _ in range(n+1)]
    prime[0] = False
    prime[1] = False
    for p in range(2, n+1):
        if prime[p] == True:
            for i in range(2*p, n+1, p):
                prime[i] = False

    prime_nums = []
    for i in range(n+1):
        if prime[i] == True:
            prime_nums.append(i)

    return prime_nums

