const findMaxLeafInBTree = function(node) {
  //  if null was passed as a parameter, there is nothing to do
  if (!node) {
    return -Infinity;
  }

  const leftMaxLeaf = findMaxLeafInBTree(node.left);
  const rightMaxLeaf = findMaxLeafInBTree(node.right);  

  //  verify if the parameter has children and which one is the higher
  let childrenMax = Math.max(leftMaxLeaf, rightMaxLeaf);
  //  this is the highest value of the leaves
  return Math.max(childrenMax, node.value);
}

