// Function to find the largest element in given binary tree
const findLargestElement = (root) => {
  // if root node is null
  if (root == null) {
    return null;
  }

  // initialize the variable for max element  
  let max = root.value; 

  // traverse the left and right subtrees recursively
  max = Math.max(max, findLargestElement(root.left)); 
  max = Math.max(max, findLargestElement(root.right)); 

  // return max value from left, right and root
  return max; 
}

