def longest_increasing_subarray(arr):
    # Initialize result list
    subarray_lengths = []

    # Iterate over the array
    for i in range(len(arr)):
        count = 1
        # Iterate over the rest of the elements in the current array
        for j in range(i + 1, len(arr)):
            # Check is the current element is greater than the last element
            if (arr[j] > arr[j - 1]):
                count += 1
            else:
                # When no longer increasing, remember the count and break.
                subarray_lengths.append(count)
