int main()
{
    string str1 = "ABCDEFG";
    string str2 = "BCDFH";

    int len1 = str1.length(), len2 = str2.length();

    int dp[len1 + 1][len2 + 1];

    for (int i = 0; i <= len1; i++)
    {
        for (int j = 0; j <= len2; j++)
        {
            if (i == 0 || j == 0)
                dp[i][j] = 0;
            else if (str1[i - 1] == str2[j - 1])
                dp[i][j] = dp[i - 1][j - 1] + 1;
            else
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    cout << "Length of longest common subsequence : " << dp[len1][len2] << endl;

    return 0;
}

// Function to find whether a given set of numbers can be 
// partitioned into two sets such that the sum of elements 
// in both sets is equal 
bool isPartitionPossible(int arr[], int n) 
{ 
    int sum = 0; 
    int i, j; 

    // Calculate sum of all elements 
    for (i = 0; i < n; i++) 
        sum += arr[i]; 

    if (sum % 2 != 0) 
        return false; 

    bool part[sum / 2 + 1][n + 1]; 

    // initialize top row as true 
    for (i = 0; i <= n; i++) 
        part[0][i] = true; 

    // initialize leftmost column,  
    // except part[0][0], as 0 
    for (i = 1; i <= sum / 2; i++) 
        part[i][0] = false; 

    // Fill the partition matrix 
    for (i = 1; i <= sum / 2; i++)  
    { 
        for (j = 1; j <= n; j++)  
        { 
            part[i][j] = part[i][j - 1]; 
            if (i >= arr[j - 1]) 
                part[i][j] = part[i][j] ||  
                             part[i - arr[j - 1]][j - 1]; 
        }         
    } 

    return part[sum / 2][n]; 
}

