    def getDiscriminant(self):
        return (self.b**2) - 4*self.a*self.c

    def getRoot1(self):
        if self.getDiscriminant() >= 0:
            return ((-self.b + (self.getDiscriminant() ** 0.5))/(2*self.a))
        else:
            return 0

    def getRoot2(self):
        if self.getDiscriminant() >= 0:
            return ((-self.b - (self.getDiscriminant() ** 0.5))/(2*self.a))
        else:
            return 0

def palindromicSubsequence(arr):
    n = len(arr)
    palindrome = [[0 for x in range(n)] for x in range(n)] 

    # palindrome[i][j] = 1 if arr[i..j] is palindrome, 
    # else 0 
    for i in range(n): 
        palindrome[i][i] = 1

    # check for the sub-string of length 2 
    for i in range(n-1): 
        if arr[i] == arr[i+1]: 
            palindrome[i][i+1] = 1

    # check for length greater than 2. 
    # k is the length of substring 
    for k in range(3, n + 1): 
        for i in range(n - k + 1): 
            j = i + k - 1
            if (arr[i] == arr[j] and
                  palindrome[i + 1][j - 1]): 
                palindrome[i][j] = 1

    # return true if the given array has 
    # a palindromic subsequence 
    if any(palindrome[0]): 
        return True
    else: 
        return False

