// Function to find the longest common suffix of two strings
string longestCommonSuffix(string x, string y)
{   
    // To store the length of the two strings 
    int m = x.length(); 
    int n = y.length(); 

    // To store the longest common substring 
    string result = ""; 

    int len = 0;

    // Comparing the two strings from the end 
    for (int i = m - 1, j = n - 1; i >= 0 && j >= 0; i--, j--) 
    { 
        if (x[i] == y[j]) 
        { 
            len += 1; 

            // Prepending the found character to the result string 
            result = x[i] + result; 
        } 

        else
            break; 
    } 

    // Return the longest common substring 
    return result; 
} 

