public class Node
{
 public char Character { get; set; }
 public int Frequency { get; set; }
 public Node Left {get; set; }
 public Node Right { get; set; }

 public Node(char character, int frequency)
 {
  Character = character;
  Frequency = frequency;
  Left = null;
  Right = null;
 }
}

public class Huffman
{
 public static void Main()
 {
  Node root;
  // Count the frequency of each character
  Dictionary<char, int> frequencies = new Dictionary<char, int>();
  frequencies['A'] = 2;
  frequencies['B'] = 4;
  frequencies['C'] = 7;
  frequencies['D'] = 1;

  // Create the Huffman tree
  root = BuildHuffmanTree(frequencies);

  // Traverse the tree, printing the codes for each character
  TraverseHuffmanTree(root, "");
 }

 static Node BuildHuffmanTree(Dictionary<char, int> frequencies)
 {
  PriorityQueue<Node> queue = new PriorityQueue<Node>();

  // Create a leaf node for each character and add it to the priority queue
  foreach (var key in frequencies.Keys)
  {
   Node node = new Node(key, frequencies[key]);
   queue.Enqueue(node);
  }

  // Iteratively construct the tree
  while (queue.Count > 1)
  {
   // Remove the two nodes of highest priority (lowest frequency) from the queue
   Node left = queue.Dequeue();
   Node right = queue.Dequeue();

   // Create a new internal node with these two nodes as children and with
   // frequency equal to the sum of the two nodes' frequencies.
   Node node = new Node('\0', left.Frequency + right.Frequency);
   node.Left = left;
   node.Right = right;

   // Add the new node to the queue
   queue.Enqueue(node);
  }

  // The remaining node is the root node
  return queue.Dequeue();
 }

 static void TraverseHuffmanTree(Node node, string s)
 {
  // If we are at a leaf node, print the code s
  if (node.Left == null && node.Right == null)
  {
   Console.WriteLine("{0}: {1}", node.Character, s);
   return;
  }

  // Move left
  TraverseHuffmanTree(node.Left, s + "0");

  // Move right
  TraverseHuffmanTree(node.Right, s + "1");
 }
}

