const paginate = (items, pageSize) => {
  let paginatedItems = [];
  let counter = 0;

  // Iterate through the items
  for (let i = 0; i < items.length; i++) {
    paginatedItems[counter] = [];

    // Push each item to the paginatedItems
    paginatedItems[counter].push(items[i]);

    // If the paginatedItems array is full, move to the next page
    if (paginatedItems[counter].length === pageSize) {
      counter++;
    }
  }

  return paginatedItems;
};

