function lcsLength(X, Y) { 
    let m = X.length; 
    let n = Y.length; 

    let dp = []; 
    for (let i = 0; i <= m; i++) { 
        dp[i] = new Array(n+1).fill(0); 
    } 

    for (let i = 1; i <= m; i++) { 
        for (let j = 1; j <= n; j++) { 
            if (X[i - 1] === Y[j - 1]) 
                dp[i][j] = 1 + dp[i - 1][j - 1]; 
            else
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); 
        } 
    } 
    return dp[m][n]; 
} 

