static void shellSort(int[] arr) {
    // Set gap
    int gap = arr.length / 2;

    while (gap > 0) {
        for (int i = gap; i < arr.length; i++) {

            int temp = arr[i];
            int j = i;

            while (j >= gap && arr[j - gap] > temp) {
                arr[j] = arr[j - gap];
                j -= gap;
            }
            arr[j] = temp; 
        } 
        gap /= 2; 
    }
}

// Main Method
public static void main(String[] args) {
    int[] arr = {3, 2, 5, 1, 4};

    shellSort(arr);

    Console.WriteLine(Arrays.toString(arr));
}

