# Algorithm to compute edit distance

def edit_distance(str1, str2):
    m = len(str1)
    n = len(str2)

    # Create a 2D array to store the edit distances between pairs of substrings 
    distances = [[None]*(n+1) for i in range(m+1)]

    # Initialize the 2D array with 0 
    for i in range(m+1): 
        for j in range(n+1):
            if i == 0:
                distances[i][j] = j
            elif j == 0:
                distances[i][j] = i
            else:
                distances[i][j] = 0

    # Loop through the strings
    for i in range(1, m+1): 
        for j in range(1, n+1): 
            # If characters in the two strings are equal, set the edit distance to the value at the previous position
            if str1[i-1] == str2[j-1]:
                distances[i][j] = distances[i-1][j-1] 
            # If characters in the two strings are not equal, set the edit distance to the minimum of the three values at the left, top and diagonal
            else:
                distances[i][j] = 1 + min(distances[i][j-1], distances[i-1][j], distances[i-1][j-1])

    # The edit distance is the last element in the distances matrix
    return distances[m][n]

