// Algorithm to count the number of combinations of k items that can be chosen from a set of n items

// Input: n = number of items 
//        k = number of items to choose
// Output: num_combinations - int representing the number of combinations 

// Step 1: Initialize base cases
// If k is 0 or n is 0, there are 0 combinations 
if (k == 0 || n == 0) 
    return 0;

// If k is equal to n, there is 1 combination 
if (k == n) 
    return 1;

// Step 2: Initialize variables
int num_combinations = 0;

// Step 3: If n ≥ k
if (n >= k) { 
    // Count (k-1) combinations in the set of (n-1) elements 
    num_combinations += countCombinations(n - 1, k - 1); 

    // Count (k) combinations in the set of (n-1) elements 
    num_combinations += countCombinations(n - 1, k); 
} 

// Step 4: Return the number of combinations
return num_combinations;

