- (NSArray*)sortArray:(NSArray*)unsortedArray {

NSMutableArray *sortedArray = [unsortedArray mutableCopy];

for (NSUInteger i = 0; i < [sortedArray count] - 1; i++) {
 NSUInteger minIndex = i;

 for (NSUInteger j = i + 1; j < [sortedArray count]; j++) {
 if ([sortedArray objectAtIndex:j] < [sortedArray objectAtIndex:minIndex]) {
 minIndex = j;
 }
 }

 if (minIndex != i) {
 [sortedArray exchangeObjectAtIndex:i withObjectAtIndex:minIndex];
 }
}

return sortedArray;
}

