def find_max_islands(arr):
    max_count = 0
    for i in range(len(arr)):
        for j in range(len(arr[i])):
            if arr[i][j] == 1:
                count = count_islands(arr, i, j)
                max_count = max(max_count, count)
    return max_count

def count_islands(arr, row, col):
    if row < 0 or col < 0 or row >= len(arr) or col >= len(arr[row]) or arr[row][col] == 0:
        return 0
    arr[row][col] = 0
    count = 1
    for r in range(row-1, row+2):
        for c in range(col-1, col+2):
            if r != row or c != col:
                count += count_islands(arr, r, c)
    return count

