    # Create an empty string for the HTML
    html_string = ""

    # Add the headings and their corresponding subheadings
    for i, heading in enumerate(headings):
        html_string += f"<h1>{heading}</h1>\n"
        sub_headings = [ subheadings[j] for j in range(i, len(subheadings)) if subheadings[j].startswith(f"Subheading {i+1}") ]
        for subheading in sub_headings:
            html_string += f"<h2>{subheading}</h2>\n"

