class Vector3D
{
 public:
  float x, y, z;

  Vector3D() : x(0), y(0), z(0) {}

  Vector3D(float x, float y, float z) : x(x), y(y), z(z) {}

  void scale(float factor) {
    x *= factor;
    y *= factor;
    z *= factor;
  }

  void normalize() {
    float len = length();
    x /= len;
    y /= len;
    z /= len;
  }

  void add(Vector3D v) {
    x += v.x;
    y += v.y;
    z += v.z;
  }

 private:
  float length() {
    return sqrt(x*x + y*y + z*z);
  }

};

