from scipy.optimize import minimize

def find_max(function, vars_min, vars_max):
    constraints = [
        {
            'type': 'ineq',
            'fun': lambda x: x[i] - vars_min[i],
            'j': i
        } 
        for i in range(len(vars_min))
    ] + [
        {
            'type': 'ineq',
            'fun': lambda x: vars_max[i] - x[i],
            'j': i
        } 
        for i in range(len(vars_max))
    ]

    res = minimize(function, (vars_min + vars_max) / 2, constraints=constraints, options={'disp': False})
    return res.fun

