public class MeanNormalization
{
    public static List<double> NormalizeMean(List<double> list, double lowerRange, double upperRange)
    {
        int n = list.Count;
        double mean = list.Average();

        List<double> normalizedList = new List<double>();
        foreach (double num in list)
        {
            double normalized = ((num - mean) / (upperRange - lowerRange)) + (upperRange + lowerRange) / 2;
            normalizedList.Add(normalized);
        }
        return normalizedList;
    }
}

