int board[9][9];

// Checks if a number is valid to place in a given row
bool checkRow(int row, int num)
{
 for (int col = 0; col<9; col++)
 {
 if (board[row][col] == num)
 {
 return false;
 }
 }
 return true;
}

// Checks if a number is valid to place in a given column
bool checkCol(int col, int num)
{
 for (int row = 0; row<9; row++)
 {
 if (board[row][col] == num)
 {
 return false;
 }
 }
 return true;
}

// Checks if a number is valid to place in a given 3x3 box
bool checkBox(int startRow, int startCol, int num)
{
 for (int row = 0; row<3; row++)
 {
 for (int col = 0; col<3; col++)
 {
 if (board[row+startRow][col+startCol] == num)
 {
 return false;
 }
 }
 }
 return true;
}

// Checks if a number is valid to place in the given cell
bool checkValidity(int row, int col, int num)
{
 return checkRow(row, num) && checkCol(col, num) && checkBox(row-row%3, col-col%3, num) && board[row][col]==0;
}

// Sets the cell with a given number
void set(int row, int col, int num)
{
 board[row][col] = num;
}

// Removes a set number from the cell
void reset(int row, int col)
{
 board[row][col] = 0;
}

// Solves the Sudoku board and returns true if the solution exists, false otherwise
bool solveSudoku()
{
 for (int row=0; row<9; row++)
 {
 for (int col=0; col<9; col++)
 {
 // Unassigned location
 if (board[row][col] == 0)
 {
 // Check each possible number from 1 to 9
 // If a number is valid to set in this cell,
 // Set it in this cell and recursively solve the board
 for (int num=1; num<=9; num++)
 {
 if (checkValidity(row, col, num))
 {
 set(row, col, num);
 if (solveSudoku())
 {
 return true;
 }
 reset(row, col);
 }
 }

 return false;
 }
 }
 }
 // Sudoku is solved
 return true;
}

