    longest_substring = ''
    i, j = 0, 0
    while i < len(s1):
        j = 0
        while j < len(s2):
            k = 0
            while i + k < len(s1) and j + k < len(s2):
                if s1[i + k] == s2[j + k]:
                    k += 1
                else:
                    break
            if len(longest_substring) < k:
                longest_substring = s1[i:i+k]
            j += 1
        i += 1
    return longest_substring

