using namespace std;

vector<int> union_arrays(vector<int> arr1, vector<int> arr2)
{
    vector<int> result(arr1.size() + arr2.size());
    int m = arr1.size();
    int n = arr2.size();
    int i = 0;
    int j = 0;
    int k = 0;

    // iterate until the last element in both arrays
    while (i < m && j < n)
    {
        // check for equal elements in both arrays
        if (arr1[i] == arr2[j])
        {
            // store the element in the result array
            result[k] = arr1[i];
            i++; j++; k++;
        }
        // compare the elements of two arrays and store the element
        // with a smaller value in the result array
        else if (arr1[i] < arr2[j])
        {
            result[k] = arr1[i];
            i++; k++;
        }
        else
        {
            result[k] = arr2[j];
            j++; k++;
        }
    }
    // put the remaining elements of arr1 into the result array
    while (i < m)
    {
        result[k] = arr1[i];
        i++; k++;
    }
    // put the remaining elements of arr2 into the result array
    while (j < n)
    {
        result[k] = arr2[j];
        j++; k++;
    }
    return result;
}

int main()
{
    vector<int> arr1 = {1, 2, 3, 5, 6, 7};
    vector<int> arr2 = {3, 4, 5, 8};
    vector<int> union_arr = union_arrays(arr1, arr2);

    cout << "The union of the two arrays is: ";
    for (auto x: union_arr)
        cout << x << " ";
    cout << endl;

    return 0;
}

