public bool IsPathSummable(int[][] matrix, int target) 
{ 
    // Initialize the matrix rows and columns 
    int row = matrix.Length; 
    int col = matrix[0].Length; 

    // Create a matrix to store results of subproblems 
    int[,] dp = new int[row, col]; 

    // Initialize the dp[0][0] 
    dp[0,0] = matrix[0, 0]; 

    // Initialize first column from the matrix values 
    for (int i = 1; i < row; i++) 
        dp[i, 0] = dp[i-1, 0] + matrix[i, 0]; 

    // Initialize first row from the matrix values 
    for (int j = 1; j < col; j++) 
        dp[0, j] = dp[0, j-1] + matrix[0, j]; 

    // Computing the remaining cells 
    for (int i=1; i<row; i++) 
    { 
        for (int j=1; j<col; j++) 
        { 
            dp[i, j] = Max(dp[i-1, j-1], dp[i-1, j], dp[i, j-1]) +  
            matrix[i, j]; 
        } 
    } 

    // Returns whether the path has a sum equal to target or not 
    return (dp[row-1, col-1] == target); 
} 

