int findMostOccurringElement(int[] arr) {
    int max = 0;
    int element = 0;
    int count = 0;

    for (int i = 0; i < arr.Length; i++) {
        count = 1;
        for (int k = i + 1; k < arr.Length; k++) {
            if (arr[i] == arr[k])
                count++;
        }

        if (count > max) {
            max = count;
            element = arr[i];
        }
    }

    return element;
}

