int find_maximum_duplicate(int x, int a[], int N) {
  int max_duplicate = -1;
  for(int i=0; i<N; i++) {
    if(a[i] == x) {
      int num_duplicates = 0;
      for (int j=0; j<N; j++) {
        if (a[j] == x) {
          num_duplicates++;
        }
      }
      if (num_duplicates > max_duplicate) {
        max_duplicate = num_duplicates;
      }
    }
  }

  return max_duplicate;
}

