# Function to check whether the number 
# can be represented as the sum 
# of two numbers or not. 
def canRepresentedSumOfTwo(n):
    for i in range(1,int(n/2)+1): 
        if (n - i) > 0: 
            if canPartition(n - i,n) == True: 
                return True; 

    return False;

# Helper function to test 
# whether a number can be  
# expressed as sum of two 
# numbers.
def canPartition(n, original_n): 

    if n == 0 or n == 1: 
        return True

    # Check if k can be expressed  
    # as the sum of two numbers.  
    for i in range(1,int(n/2)+1): 
        if canPartition(n - i, original_n) == True : 
            return True

    return False;

