def is_anagram(str1, str2):
	# remove whitespaces and convert strings to lowercase
	str1 = str1.replace(" ", "").lower()
	str2 = str2.replace(" ", "").lower()

	# check if same number of letters
	if len(str1) != len(str2):
		return False

	# create dictionary to keep track of characters
	count = {}

	for letter in str1:
		if letter in count:
			count[letter] += 1
		else:
			count[letter] = 1

	for letter in str2:
		if letter in count:
			count[letter] -= 1
		else:
			count[letter] = 1

	for k in count:
		if count[k] != 0:
			return False

	return True

