def bubbleSort(A: List[Int]): List[Int] = {
    var swapped = true
    while(swapped) {
        swapped = false
        for(i <- 1 until A.length) {
            if(A(i-1) > A(i)) {
                val temp = A(i)
                A.update(i, A(i-1))
                A.update(i-1, temp)
                swapped  = true
            }
        }
    }
    A
}

