function isPrimeNumber(str) {
    const number = parseInt(str);

    if (number < 2 || isNaN(number)) {
        return false;
    }

    if (number === 2) {
        return true;
    }

    for (let i = 2; i < number; i++) {
        if (number % i === 0) {
            return false;
          }
    }

    return true;
}

