function permutations(arr){
 const results=[];

 function traverse(arr, start){
 if (start === arr.length) {
 results.push([...arr]);
 return;
 }

 for (let i = start; i < arr.length; i++){
 const item = arr[start];
 let unique = true;

 for (let j = start; j < i ; j++) {
 if (item === arr[j]) {
 unique = false;
 }
 }

 if (unique) {
 [arr[start], arr[i]] = [arr[i], arr[start]];
 traverse(arr, start+1);
 //[arr[start], arr[i]] = [arr[i], arr[start]];
 }
 }
 }

 traverse(arr, 0);
 return results;
}

