function twoSum(arr, sum) {
    const pairs = [];
    const map = new Map();
    arr.forEach(function(num, i) {
        const complement = sum - num;
        if (map.has(complement)) {
            pairs.push([num, complement]);
        }
        map.set(num, i);
    });
    return pairs;
}

