public class Power { 

 // Function to calculate the power 
 static long power(long x, long n) 
 { 
 if (n == 0) 
 return 1; 

 long temp = power(x, n / 2); 

 if (n % 2 == 0) 
 return temp * temp; 
 else
 { 
 if (n > 0) 
 return x * temp * temp; 
 else
 return (temp * temp) / x; 
 } 
 } 

 // Driver code 
 public static void main(String[] args) 
 { 
 long x = 2; 
 long n = 5; 

 System.out.println(power(2, 5)); 
 } 
}

