public static int[] sortAscending(int[] inputArray) {
    int n = inputArray.length;

    // Loop through the array and compare values
    for (int i = 0; i < n-1; i++) {
        int min_index = i;

        // Iterate over the loop to compare current
        // element with the next one 
        for (int j = i+1; j < n; j++)
            if (inputArray[j] < inputArray[min_index])
                min_index = j;

        // Swap the elements
        int temp = inputArray[min_index];
        inputArray[min_index] = inputArray[i];
        inputArray[i] = temp; 
    } 
    return inputArray;
}

