function encryptDataAes256(plainText, secretKey) {
 const iv = crypto.randomBytes(16); // Random initialization vector
 const salt = crypto.randomBytes(64); // Salt should be as large as possible
 const key = crypto.pbkdf2Sync(Buffer.from(secretKey), salt, 2145, 32, 'sha512'); // Key length should be 32 bytes
 const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
 let encrypted = cipher.update(Buffer.from(plainText));
 encrypted = Buffer.concat([encrypted, cipher.final()]);
 const aad = Buffer.from('123456'); // Additional authentication data
 const tag = cipher.getAuthTag();
 return Buffer.concat([salt, iv, tag, encrypted, aad]).toString('base64');
}

