def find_target_index(array, target): 
    # find the midpoint 
    midpoint = (len(array)-1)//2

    # if the midpoint is the target, return the index 
    if array[midpoint] == target:
        return midpoint

    # if the target is less than the midpoint value, search left
    if array[midpoint] > target:
        return find_target_index(array[:midpoint], target) 

    # if target is greater than the midpoint value, search right 
    if array[midpoint] < target:  
        return midpoint + 1 + find_target_index(array[midpoint+1:], target)

