struct node
{
    int data;
    struct node* next;
};

void deleteNode(struct node **head, struct node *ptr_del)
{
    // If linked list is empty
    if (*head == NULL)
        return;

    // Delete head node
    if (ptr_del == *head)
    {
        *head = ptr_del->next; //Head points to next node
        free(ptr_del); //free the deleted node
        return;
    }

    struct node *ptr_temp = *head;
    while (ptr_temp->next != ptr_del)
        ptr_temp = ptr_temp->next;

    //link node before deleted node to the one after it to delete the required node
    ptr_temp->next = ptr_del->next;
    free(ptr_del); //free the deleted node
}

