{
  # convert x to character vector
  x <- as.character(x)
  # convert x to uppercase
  x <- toupper(x)

  # define the alphabet
  alphabet <- c(LETTERS, 0:9)

  # define a vector to store decoded message
  decoded_message <- c()

  for(i in 1:length(x))
  {  
    # find position of character in alphabet
    character_position <- which(alphabet == x[i])

    # check if character exists in alphabet
    if(character_position %% 13 == 0)
    {
      decoded_message[i] <- alphabet[character_position - 13] 
    } else 
    {
      decoded_message[i] <- alphabet[character_position + 13] 
    } 
  }

  # convert vector to string
  decoded_message <- paste(decoded_message, collapse = "")

  # convert to lowercase if necessary
  decoded_message <- tolower(decoded_message)

  return(decoded_message)
}

