// Object class with integer field
class MyObject {
 int value;

 public MyObject(int value) {
 this.value = value;
 }
}

public class QuickSort {
 public static void sort(MyObject[] arr, int left, int right) {
 // Base case
 if (right <= left) return;

 // Partition
 int p = partition(arr, left, right);

 // Sort left
 sort(arr, left, p - 1);

 // Sort right
 sort(arr, p + 1, right);
 }

 public static int partition(MyObject[] arr, int left, int right) {
 // Choose pivot
 MyObject pivot = arr[right];

 // Set partition index
 int p = left;

 for (int i = left; i < right; i++) {
 // Compare current value with pivot
 if (arr[i].value > pivot.value) {
     swap(arr, i, p);
     p++;
 }
 }

 // Move pivot into position
 swap(arr, p, right);

 // Return partition index
 return p;
 }

 public static void swap(MyObject[] arr, int i, int j) {
 MyObject t = arr[i];
 arr[i] = arr[j];
 arr[j] = t;
 }

 public static void main(String[] args) {
 MyObject[] arr = {new MyObject(15), new MyObject(8), new MyObject(4), 
new MyObject(16), new MyObject(23), new MyObject(42)};
 sort(arr, 0, arr.length - 1);
 for (MyObject o: arr) {
 System.out.print(o.value + " ");
 }
 System.out.println();
 }
}

