def find_nearest_neighbors(dataset): 
    n_neighbors = len(dataset[0]) - 1
    neighbors = [[] for x in range(len(dataset))]
    for i in range(len(dataset)): 
        distances = [] 
        for j in range(len(dataset)): 
            dist = 0
            for k in range(n_neighbors): 
                dist += (dataset[i][k] - dataset[j][k])**2
            distances.append([dist, j]) 
        distances.sort(key = lambda x : x[0]) 
        for index in range(1, n_neighbors + 1): 
            neighbors[i].append(distances[index][1]) 
    return neighbors

