import java.util.Scanner;

public class TicTacToe {
 private static char[][] board = new char[3][3]; // game board
 private static char winner = ' '; // the winner

 public static void main(String[] args) {
  initializeBoard(); // initialize the board values
  printBoard(); // print the board
  playGame(); // play the game
 }

 //Initializes the board with blank values
 private static void initializeBoard() {
  for (int i = 0; i < board.length; i++) {
   for (int j = 0; j < board[i].length; j++){
    board[i][j] = ' ';
   }
  }
 }

 //Prints the board
 private static void printBoard() {
  System.out.println(" 0 | 1 | 2 ");
  System.out.println("-----------");
  for (int i = 0; i < board.length; i++) {
   System.out.print(i + " ");
   for (int j = 0; j < board[i].length; j++) {
    System.out.print("| " + board[i][j] + " ");
   }
   System.out.println("|");
  }
  System.out.println("-----------");
 }

 //Plays the game
 private static void playGame() {
  Scanner input = new Scanner(System.in);
  int row, col;
  char player = 'X'; // player X always starts

  while (checkWinner() == ' ') {
   // prompt user for input
   System.out.print("Enter row and column for " + player + ": ");
   row = input.nextInt();
   col = input.nextInt();

   // check if position is already taken
   if (board[row][col] != ' ') {
    System.out.println("Position taken! Try again.");
    continue;
   }

   // place marker for player
   board[row][col] = player;

   // print board after each move
   printBoard();

   // switch players
   if (player == 'X') player = 'O';
   else player = 'X';
  }

  // print the winner
  System.out.println("Congratulations " + winner + "! You won!");
 }

 //Checks for a winner
 private static char checkWinner(){
  char winner = ' ';

  // check horizontally
  for (int i = 0; i < board.length; i++) {
   if (board[i][0] == board[i][1] && board[i][1] == board[i][2] && board[i][0] != ' ') winner = board[i][0];
  }

  // check vertically
  for (int i = 0; i < board.length; i++) {
   if (board[0][i] == board[1][i] && board[1][i] == board[2][i] && board[0][i] != ' ') winner = board[0][i];
  }

  // check diagonally
  if (board[0][0] == board[1][1] && board[1][1] == board[2][2] && board[0][0] != ' ') winner = board[0][0];
  if (board[0][2] == board[1][1] && board[1][1] == board[2][0] && board[0][2] != ' ') winner = board[0][2];

  return winner;
 }
}

