public class AnagramCheck
{
    public static bool IsAnagram(string s1, string s2)
    {
        if (s1.Length != s2.Length)
            return false;

        int[] counts = new int[256];
        for (int i = 0; i < s1.Length; i++)
        {
            counts[s1[i]]++;
            counts[s2[i]]--;
        }

        foreach (int value in counts)
        {
            if (value != 0)
                return false;
        }

        return true;
    }

    public static void Main()
    {
