public class PhoneNumberCombinations {
    public static List<String> generatePhoneNumberCombinations(String numberInput) {
        List<String> phoneNumberCombinations = new ArrayList<>();
        generatePhoneNumberCombinations("", numberInput, phoneNumberCombinations);
        return phoneNumberCombinations;
    }

    private static void generatePhoneNumberCombinations(String prefix, String numberInput, List<String> combinations) {
        if (numberInput.length() == 0) {
            combinations.add(prefix);
            return;
        }

        for (int i = 0; i < numberInput.length(); i++) {
            char digit = numberInput.charAt(i);
            if (digit == '0' || digit == '1') {
                continue;
            }
            generatePhoneNumberCombinations(prefix + digit, numberInput.substring(0,i) + numberInput.substring(i+1), combinations);
        }
    }

    public static void main(String[] args) {
        List<String> phoneNumberCombinations = generatePhoneNumberCombinations("123456");
        System.out.println(phoneNumberCombinations);
    }
}

