public class UserAPIUtil {
    private static String generateSecureKey(String userId) {
        try {
            SecureRandom random = SecureRandom.getInstance("SHA1PRNG"); 
            byte bytes[] = new byte[20]; 
            random.nextBytes(bytes); 
            MessageDigest messageDigest = MessageDigest.getInstance("SHA-256"); 
            byte[] userKey = messageDigest.digest((userId).getBytes("UTF-8")); 
            byte[] key = new byte[userKey.length + bytes.length]; 
            System.arraycopy(userKey, 0, key, 0, userKey.length); 
            System.arraycopy(bytes, 0, key, userKey.length, bytes.length); 
            return String.format("%064x", new java.math.BigInteger(1, key));
