public class HTMLParser {
    private String text;

    public HTMLParser(String text) {
        this.text = text;
    }

    public void parse() {
        Map<String, String> tags = new HashMap<>();

        // Extract the tags from the text
        String pattern = "<(.*?)>";
        List<String> matches = getMatches(pattern);

        // Extract the tag names
        for (String match : matches) {
            String[] parts = match.split(" ");
            String tag = parts[0].replace("<", "");
            tags.put(tag, match);
        }

        // Process the tags
        for (String tag : tags.keySet()) {
            // do something here
            System.out.println("Tag name: " + tag + " | Tag content: " + tags.get(tag));
        }
    }

    private List<String> getMatches(String pattern) {
        List<String> matches = new ArrayList<>();
        List<String> lines = Arrays.asList(text.split("\n"));
        for (String line : lines) {
            if (line.matches(pattern)) {
                matches.add(line);
            }
        }
        return matches;
    }

}

def is_anagram(s1, s2):
  if len(s1) != len(s2):
    return False

  s1_map = {}
  s2_map = {}

  for char in s1:
    if char in s1_map:
      s1_map[char] += 1
    else:
      s1_map[char] = 1

  for char in s2:
    if char in s2_map:
      s2_map[char] += 1
    else:
      s2_map[char] = 1

  for k, v in s1_map.items():
    if k not in s2_map or s2_map[k] != v:
      return False

  return True

