Algorithm longestSubstring(str1, str2):

// Initialize a 2D array to store found common substrings
matrix[str1.length][str2.length]

// Initialize a string variable to store the longest common substring
longestSubstring = ""

// Loop through both strings to fill the matrix
for i = 0 to str1.length-1:
    for j = 0 to str2.length-1:
        if str1[i] == str2[j]:
            if i == 0 || j == 0:
                matrix[i][j] = 1
            else:
                matrix[i][j] = 1 + matrix[i-1][j-1]
            // Check if largest common substring is found
            if matrix[i][j] > longestSubstring.length:
                  longestSubstring = str1.substr(i-matrix[i][j]+1, matrix[i][j])

return longestSubstring

