public class FindPairs {

   public static int findPairs(int[] nums, int k) {
        int i = 0, j = 1;
        int count = 0;
        while (i < nums.length && j < nums.length) {
            if (nums[i] + nums[j] == k) {
                count++;
                i++;
                j++;
            }
            else if (nums[i] + nums[j] > k) {
                i++;
            }
            else {
                j++;
            }
        }
        return count;
    }

