public class LogGenerator {

	public static void main(String[] args) {
		File logFile = new File("input.log");

		Map<String, Integer> statusCount = new HashMap<>();
		int requestCount = 0;

		try (BufferedReader in = new BufferedReader(new FileReader(logFile))) {
			String line;

			while ((line = in.readLine()) != null) {
				int index = line.lastIndexOf(" ");
				String statusCode = line.substring(index + 1);

				requestCount++;
				if (statusCount.containsKey(statusCode)) {
					int count = statusCount.get(statusCode);
					statusCount.put(statusCode, count + 1);
				} else {
					statusCount.put(statusCode, 1);
				}
			}
		} catch (IOException e) {
			e.printStackTrace();
		}

		System.out.println("Total request = " + requestCount);

		for (String code : statusCount.keySet()) {
			System.out.println(code + ": " + statusCount.get(code));
		}
	}
}

