public class FindMedian {
   public static int findMedian (int[] array1, int[] array2) {
       int m = array1.length;
       int n = array2.length;

       if (m == 0 && n == 0)
           return 0;

       int median1, median2;
       /* Calculate medians of smaller arrays */
       if (m == 0)
           median1 = median2 = array2[n / 2];
       else if (n == 0)
           median1 = median2 = array1[m / 2];
       else {
           // Odd number of elements in both arrays
           if ( (m & 1) == 1 && (n & 1) == 1 )
           {
               median1 = array1[m / 2];
               median2 = array2[n / 2];
           }
           // Even number of elements in both arrays 
           else {
               int medianIndex1 = (m - 1) / 2;
               int medianIndex2 = (n - 1) / 2;
               median1 = (array1[medianIndex1] + array1[medianIndex1 + 1]) / 2;
               median2 = (array2[medianIndex2] + array2[medianIndex2 + 1]) / 2;
           }
       }
       return (median1 + median2) / 2;
   }

   // Driver code
   public static void main (String[] args) {
       int[] array1 = { 1, 2, 3, 4 };
       int[] array2 = { 5, 6, 7, 8 };
       System.out.println("The median is " + findMedian(array1, array2));
   }
}

