int countPairs(vector<int> numbers, int k)
{
    // Initialize the result
    int result = 0;

    // Store the count of all element in map
    unordered_map<int, int> m;
    for (int i = 0; i < numbers.size(); i++)
        m[numbers[i]]++;

    // Traverse the map and find Diff and
    // increment the count result
    for (int i = 0; i < numbers.size(); i++)
    {
        if (m[k - numbers[i]] > 0)
        {
            result++;

            // To handle the duplicate elements
            if (numbers[i] == k - numbers[i])
                m[numbers[i]]--;
        }
    }

    // Return result;
    return result;
}

