bool isBalanced(Node* root) 
{ 
    if (root == nullptr) 
        return true; 

    int lh = height(root->left); 
    int rh = height(root->right); 

    if (abs(lh - rh) <= 1 && 
        isBalanced(root->left) && 
        isBalanced(root->right)) 
        return true; 

    return false; 
} 

int height(Node* node) 
{ 
    if (node == nullptr) 
        return 0; 

    return 1 + max(height(node->left), 
                   height(node->right)); 
}

