function findGCD(nums: number[]) {
  let result: number[] = []; 

  // loop over the array
  for (let num of nums) {
    let gcd = 1;

    // Here we use the Euclidean algorithm to find the GCD
    for (let i = 1; i <= num; i++) {
      if (num % i == 0 && gcd % i == 0) {
        gcd = i;
      }
    }

    result.push(gcd);
  }

  return result;
}

