function optimizeArray(arr) {
 const sorted = arr.sort((a, b) => a.start - b.start);
 let optimized = [sorted[0]];
 sorted.slice(1).forEach(obj => {
 const prev = optimized[optimized.length-1];
 if (obj.start <= prev.end) {
 prev.end = Math.max(obj.end, prev.end);
 } else {
 optimized.push(obj);
 }
 });

 return optimized;
}

