int** transpose_array(int** arr, int rows, int cols) {
    int **res = new int*[cols];
    for (int i = 0; i < cols; i++) {
        res[i] = new int[rows];
    }

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            res[j][i] = arr[i][j];
        }
    }
    return res;
}

