bool isValid(string s) {
    int n = s.length();
    if (n&1) return false; // odd length

    char stack[n];
    int top=-1;

    for(int i=0;i<n; i++)
    {
        char ch = s[i];
        if (ch=='(' || ch=='[' || ch=='{')
        {
            stack[++top] = ch;
        }
        else if (ch == ')' || ch == ']' || ch == '}')
        {
            if (top == -1) return false;
            char temp = stack[top--];
            if (temp == '(' && ch != ')') return false;
            else if (temp == '[' && ch != ']') return false;
            else if (temp == '{' && ch != '}') return false;
        }
    }

    // check stack empty or not
    if (top == -1)
        return true;
    else
        return false;
}

