    if len(string1) != len(string2):
        return False

    s1_dict = {}
    s2_dict = {}

    for char in string1:
        if char in s1_dict:
            s1_dict[char] += 1
        else:
            s1_dict[char] = 1 
    for char in string2:
        if char in s2_dict:
