import Foundation

func encrypt(text: String, key: Int) -> String {
 var encryptedString = ""
 let alphabet = "abcdefghijklmnopqrstuvwxyz"

 // Iterate over each character of the text
 for character in text {
  // Get the index of the character in the alphabet
  if let index = alphabet.index(of: character) {
   // Calculate the new index using the key
   let newIndex = index + key
   // Check if the new index is in bounds
   if newIndex < alphabet.count {
    let newCharacter = alphabet[newIndex]
    encryptedString.append(newCharacter)
   } else {
    let wrappedIndex = newIndex % alphabet.count
    let newCharacter = alphabet[wrappedIndex]
    encryptedString.append(newCharacter)
   }
  }
 }

 return encryptedString
}

