@SpringBootApplication
@RestController
public class DemoApplication {

	private static List<Map<String, String>> users = new ArrayList<Map<String, String>>();

	@RequestMapping("/")
	public String home() {
		return "This is a users registration API";
	}

	@RequestMapping(value = "/users", method = RequestMethod.GET)
	public List<Map<String, String>> users() {
		return users;
	}

	@RequestMapping(value = "/users", method = RequestMethod.POST)
	public Map<String, String> createUser(@RequestBody Map<String, String> user) {
		users.add(user);
		return user;
	}

	@RequestMapping(value = "/users/{userId}", method = RequestMethod.PUT)
	public Map<String, String> updateUser(@PathVariable String userId, @RequestBody Map<String, String> user) {
		for (int i = 0; i < users.size(); i++) {
			if (users.get(i).get("id").equals(userId)) {
				users.remove(i);
				users.add(user);
				return user;
			}
		}
		return new HashMap<String, String>();
	}

	public static void main(String[] args) {
		SpringApplication.run(DemoApplication.class, args);
	}
}

