def caesar_cipher(s, key):
  result = ''
  for c in s:
    if c.isalpha():
      num = ord(c)
      num += key
      if c.isupper():
        if num > ord('Z'):
          num -= 26
        elif num < ord('A'):
          num += 26
      elif c.islower():
        if num > ord('z'):
          num -= 26
        elif num < ord('a'):
          num += 26
      result += chr(num)
    else:
      result += c
  return result

