function computeFibSum(n) {
    let sum = 0;
    let fib1 = 0, fib2 = 1;
    while (fib1 <= n) {
        if (fib1 % 2 !== 0) {
            sum += fib1;
        }
        fib1 += fib2;
        fib2 = fib1 - fib2;
    }
    return sum;
