def average_distance(root): 
    if root is None: 
        return 0
    # height of left subtree
    heightLeft = height(root.left)  

    # height of right subtree
    heightRight = height(root.right) 

    # calculate the distance
    dist = (heightLeft + heightRight) + average_distance(root.left) + average_distance(root.right) 

