def height(root): 
    if root is None: 
        return 0
    else: 
        # height of left subtree 
        leftHeight = height(root.left)  

        # height of right subtree         
        rightHeight = height(root.right)  
        if leftHeight > rightHeight: 
            return (leftHeight+1) 
        else: 
            return (rightHeight+1)

