void printPrimes(int n1, int n2) 
{ 
    // Flag variable to check whether 
    // the current number is prime or not. 
    int isPrime; 

    // Run loop from given range 
    // starting and ending number 
    for (int i=n1; i<=n2; i++) 
    { 
        // Assume that the current 
        // number is prime 
        isPrime = 1; 

        // Check if the current number 
        // is prime or not 
        for (int j=2; j<=i/2; j++) 
            if (i % j == 0) 
            { 
                isPrime = 0; 
                break; 
            } 

        // Print the number if it is prime 
        if (isPrime==1) 
            printf("%d ", i); 
    } 
} 

