def binary_search(arr, x): 
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            return mid 
        else:
            if x < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
    return -1

