def knapsack(items, capacity): 
    result_rec = knapsack_rec(items, capacity, len(items)-1)  
    result = knapsack_dp(items, capacity)  
    assert result_rec == result  
    return result 

def knapsack_rec(items, capacity, index): 
    if len(items) == 0 or capacity == 0 or index < 0: 
        return 0 

    if items[index].weight <= capacity: 
        return max(items[index].value + knapsack_rec(items, capacity - items[index].weight, index - 1), 
                  knapsack_rec(items, capacity, index - 1)) 
    else: 
        return knapsack_rec(items, capacity, index - 1) 

def knapsack_dp(items, capacity):  
    dp = [[0 for x in range(capacity + 1)] for x in range(len(items) + 1)] 

    for i in range(len(items) + 1): 
        for j in range(capacity + 1): 
            if i == 0 or j == 0: 
                dp[i][j] = 0
            elif items[i-1].weight <= j: 
                dp[i][j] = max(items[i-1].value + dp[i-1][j - items[i-1].weight],  dp[i-1][j]) 
            else: 
                dp[i][j] = dp[i-1][j] 

    return dp[len(items)][capacity]

