def merge(L1, L2):
    curr = dummyHead = Node(0)
    while L1 and L2:
        if L1.data < L2.data:
            curr.next = L1
            L1 = L1.next
        else:
            curr.next = L2
            L2 = L2.next
        curr = curr.next
    curr.next = L1 or L2
