def longestPalindrome(s): 
    n = len(s) 
    ans = ""

    # Table to store results of subproblems 
    dp = [[False for x in range(n)] for y in range(n)] 

    # Base Case
    for i in range(n): 
        dp[i][i] = True

    for cl in range(2, n+1): 
        for i in range(n - cl + 1): 
            j = i + cl - 1
            if s[i] == s[j] and cl == 2: 
                dp[i][j] = True
            if s[i] == s[j] and dp[i + 1][j - 1]: 
                dp[i][j] = True

            if dp[i][j] and cl > len(ans): 
                ans = s[i:j + 1] 

    return ans

