"""
Write a computer program that plays tic-tac-toe.
"""

class TicTacToe:
    def __init__(self):
        self.board = ["_"]*9
        self.x = "X"
        self.o = "O"
        self.turn = self.x

    def display_board(self):
        for i in range(3):
            print(self.board[i*3] + "|" + self.board[i*3+1] \
                  + "|" + self.board[i*3+2])
            if i < 2:
                print("-----")

    def is_valid_play(self, space):
        if space > 8 or space < 0 or self.board[space] != "_":
            return False
        else:
            return True

    def get_play(self):
        while True:
            space = int(input("{}'s turn: ".format(self.turn)))
            if self.is_valid_play(space):
                return space
            else:
                print("Invalid move. Try again.")

    def play(self):
        while True:
            self.display_board()
            space = self.get_play()
            self.board[space] = self.turn
            if self.is_winning_play(space):
                print("{} wins!".format(self.turn))
                return
            elif self.are_all_spaces_filled():
                print("Draw!")
                return
            else:
                if self.turn == self.x:
                    self.turn = self.o
                else:
                    self.turn = self.x

    def is_winning_play(self, space):
        row = space // 3
        col = space % 3

        # check row
        if self.board[row*3] == self.board[row*3+1] \
                == self.board[row*3+2]:
            return True
        # check column
        elif self.board[col] == self.board[col+3] \
                == self.board[col+6]:
            return True
        elif (row == col or row + col == 2) \
                and self.board[0] == self.board[4] \
                == self.board[8]:
            return True
        else:
            return False

    def are_all_spaces_filled(self):
        flag = True
        for space in self.board:
            if space == "_":
                flag = False
        return flag

