		return node.value
	else:
		m1 = evaluate(node.left)
		m2 = evaluate(node.right)

	if node.value == '+':
		return m1 + m2
	elif node.value == '-':
		return m1 - m2
	elif node.value == '*':
		return m1 * m2
	elif node.value == '/':
		return m1 / m2
	else:
