class BinaryTree { 

    // Root of Binary Tree 
    Node root; 

    // Maximum difference between any two nodes 
    int maxDiff = 0; 

    // Recursive function to calculate the maximum 
    // difference of any two nodes in the binary tree 
    int maxDiffUtil(Node node) 
    {  
        // Base case 
        if (node == null) 
            return maxDiff; 

        // Calculate the maximum difference between two 
        // nodes of the left subtree of the current node 
        int res = maxDiffUtil(node.left); 

        // Update the maximum difference 
        if (maxDiff < (node.data - res)) 
            maxDiff = node.data - res; 

        // Calculate the maximum difference between two 
        // nodes of the right subtree of the current node 
        res = maxDiffUtil(node.right); 

        // Update the maximum difference 
        if (maxDiff < (res - node.data)) 
            maxDiff = res - node.data; 

        // Return the maximum difference 
        return maxDiff; 
    } 
}

