public static int[] reverseArray(int[] arr) {
    Deque<Integer> stack = new ArrayDeque<>();
    int[] reversed = new int[arr.length];
    int j = 0;

    // Push elements of the array into a stack
    for (int num : arr) { 
        stack.push(num); 
    } 

    // Pop elements back into the array in reversed order
    while (!stack.isEmpty()) { 
        reversed[j++] = stack.pop(); 
    } 
    return reversed;
}

