    let maxCharCount = 0;
    let mostOccurChar = null;
    const charObj = {};

    for (let i = 0; i < str.length; i++) {
        const char = str[i];

        if (!charObj[char]) {
            charObj[char] = 1;
        } else {
            charObj[char] = charObj[char] + 1;
        }

        if (charObj[char] > maxCharCount) {
            maxCharCount = charObj[char];
            mostOccurChar = char;
        }
    }

    return mostOccurChar;
}

