bool isPermutation(string str1, string str2)
{
    int count[256] = {0};

    // If two strings are of different length, then they are not
    // permutations of each other
    if (str1.length() != str2.length())
        return false;

    // increment character count of the first string
    for (int i = 0; i < str1.length(); i++)
        count[str1[i]]++;

    // decrement character count of the second string
    for (int i = 0; i < str2.length(); i++)
        count[str2[i]]--;

    // If all characters are same, we will reach count[256] = 0
    for (int i = 0; i < 256; i++)
        if (count[i])
            return false;

    return true;
}

