import io.netty.handler.codec.http.HttpResponseStatus;
import io.netty.handler.codec.http.HttpUtil;
import io.netty.handler.codec.http.HttpVersion;

public class NettyRestAPIHandler extends SimpleChannelInboundHandler<FullHttpRequest> {

 @Override
 public void channelReadComplete(ChannelHandlerContext ctx) throws Exception {
  ctx.flush();
 }

 @Override
 protected void channelRead0(ChannelHandlerContext ctx, FullHttpRequest req) throws Exception {
  // Check whether a valid HTTP request
  if (!req.decoderResult().isSuccess()) {
   sendHttpResponse(ctx, req, new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.BAD_REQUEST));
   return;
  }

  // Check whether the request method is valid
  if (req.method() == HttpMethod.POST) {
   // Process post request logic
   // For example: create posts, read posts etc.
  } else if (req.method() == HttpMethod.GET) {
   // Process get request logic
   // For example: create posts, read posts etc.
  } else if (req.method() == HttpMethod.PUT) {
   // Process put request logic
   // For example: update posts etc.
  } else if (req.method() == HttpMethod.DELETE) {
   // Process delete request logic
   // For example: delete posts etc.
  } else {
   sendHttpResponse(ctx, req, new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.METHOD_NOT_ALLOWED));
  }

  sendHttpResponse(ctx, req, new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK));
 }

 private static void sendHttpResponse(ChannelHandlerContext ctx, FullHttpRequest req, FullHttpResponse res) {
  // Generate an error page if response status code is not OK (200).
  if (res.status().code() != 200) {
   ByteBuf buf = Unpooled.copiedBuffer(res.status().toString(), CharsetUtil.UTF_8);
   res.content().writeBytes(buf);
   buf.release();
   HttpUtil.setContentLength(res, res.content().readableBytes());
  }

  // Send the response and close the connection if necessary.
  ChannelFuture f = ctx.channel().writeAndFlush(res);
  if (!HttpUtil.isKeepAlive(req) || res.status().code() != 200) {
   f.addListener(ChannelFutureListener.CLOSE);
  }
 }

 @Override
 public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
  cause.printStackTrace();
  ctx.close();
 }
}

def LongestCommonSequence(string1, string2):

 n = len(string1)
 m = len(string2)

 LCS = [[0 for x in range(m+1)] for y in range(n+1)]

 for i in range(n):
 for j in range(m):
 if (string1[i] == string2[j]):
 LCS[i][j] = LCS[i-1][j-1] + 1
 else:
 LCS[i][j] = max(LCS[i-1][j], LCS[i][j-1])

#return the longest common sequence
 index = LCS[n][m]
 lcs = [""] * (index+1)
 lcs[index] = ""
 i = n
 j = m
 while i > 0 and j > 0:
 if (string1[i-1] == string2[j-1]):
 lcs[index-1] = string1[i-1]
 i -= 1
 j -= 1
 index -= 1

 elif (LCS[i-1][j] > LCS[i][j-1]):
 i -= 1
 else:
 j -= 1

 return "".join(lcs)

