def fibonacci(n):
    '''This function will generate a Fibonacci sequence up to given number 'n'.'''
    # Base case
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]
    elif n > 2:
        # Declare variables
        nums = [0, 1]
        # Start the loop 
        while len(nums) < n:
            # Generate the next term by addition
            next_num = nums[-1] + nums[-2]
            # Append the new term
            nums.append(next_num)
        return nums

