#include <iostream>
#include <string>
#include <algorithm>
#include <vector>

const int POPULATION_SIZE = 100;
const int GENE_LENGTH = 100;
const std::string TARGET = "00000000";

struct Gene {
 std::string data;
 double fitness;
};

std::vector<Gene> population;

// Generate a random population of size POPULATION_SIZE
void generatePopulation() {
 for (int i = 0; i < POPULATION_SIZE; i++) {
 Gene newGene;
 for (int j = 0; j < GENE_LENGTH; j++) {
 newGene.data += (rand() % 2 == 0) ? '0' : '1';
 }
 population.push_back(newGene);
 }
}

// Calculate the fitness for each gene in the population
void calculateFitnesses() {
 for (int i = 0; i < POPULATION_SIZE; i++) {
 int diff = 0;
 for (int j = 0; j < GENE_LENGTH; j++) {
 if (population[i].data[j] != TARGET[j])
 diff++;
 }
 population[i].fitness = (GENE_LENGTH - diff) / (double)GENE_LENGTH;
 }
}

// Perform selection operation to get the mating pool
std::vector<Gene> selection() {
 std::vector<Gene> matingPool;
 for (int i = 0; i < POPULATION_SIZE; i++) {
 // Calculate probability based on fitness
 double probability = population[i].fitness / (double)POPULATION_SIZE;
 // Generate random number between 0 to 1
 double random = (rand() % 1000) / 1000.0;
 // Select the gene with probability
 if (random <= probability)
 matingPool.push_back(population[i]);
 }
 return matingPool;
}

// Perform crossover to generate new population
void crossover(std::vector<Gene> matingPool) {
 for (int i = 0; i < POPULATION_SIZE; i++) {
 int parent1 = rand() % matingPool.size();
 int parent2 = rand() % matingPool.size();
 Gene newGene;
 // Generate random number between 0 and GENE_LENGTH
 int splitPoint = rand() % GENE_LENGTH;
 // Generate new gene by combining parts from two parents
 newGene.data = matingPool[parent1].data.substr(0, splitPoint) +
 matingPool[parent2].data.substr(splitPoint);
 population[i] = newGene;
 }
}

// Perform mutation to generate new population
void mutation() {
 for (int i = 0; i < POPULATION_SIZE; i++) {
 for (int j = 0; j < GENE_LENGTH; j++) {
 // Generate random number
 double random = (rand() % 1000) / 1000.0;
 // Perform mutation with probability 0.01
 if (random < 0.01)
 population[i].data[j] = (population[i].data[j] == '0') ? '1' : '0';
 }
 }
}

int main() {
 generatePopulation();

 while (true) {
 calculateFitnesses();
 // Check if any gene matches the target
 for (int i = 0; i < POPULATION_SIZE; i++) {
 if (population[i].fitness == 1) {
 std::cout << "Target Found!\n";
 std::cout << population[i].data << "\n";
 return 0;
 }
 }

 std::vector<Gene> matingPool = selection();
 crossover(matingPool);
 mutation();
 }

 return 0;
}

