function isUnique2D(arr) {
    for (let row = 0; row < arr.length; row++) {
        for (let col = 0; col < arr[row].length; col++) {
            let current = arr[row][col];
            for (let i = 0; i < arr.length; i++) {
                for (let j = 0; j < arr[i].length; j++) {
                    if (i != row && j != col && arr[i][j] == current) {
                       return false;
                    }
                }
            }
        }
    }

    return true;
}

