string addBinary(string s1, string s2)
{
   int n1 = s1.size();
   int n2 = s2.size();
   if (n1 == 0) return s2;
   if (n2 == 0) return s1;

   string result = ""; 
   int sum = 0; 

   int i = n1 - 1, j = n2 - 1; 
   while (i >= 0 || j >= 0 || sum == 1) { 

      sum += ((i >= 0)? s1[i] - '0': 0); 
      sum += ((j >= 0)? s2[j] - '0': 0); 
      result = char(sum % 2 + '0') + result; 

      sum /= 2; 
      i--; j--; 
   } 
   return result; 
}

