public class EvenFibonacciSum {
    public static int fibonacciSum(int number) {
        int sum = 0;
        int first = 0;
        int second = 1;
        while(second <= number) {
            int third = first + second;
            first = second;
            second = third;
            if(second % 2 == 0) {
                sum += second;
            }
        }
        return sum;
    }
    public static void main(String[] args) {
        int number = 10;
        System.out.println(fibonacciSum(number));
    }
}

