class MinHeap(object):
    def __init__(self, array):
        self.array = array
        self.size = len(array)

    def get_parent_index(self, index):
        return (index - 1) // 2

    def get_left_child_index(self, index):
        return 2 * index + 1

    def get_right_child_index(self, index):
        return 2 * index + 2

    def heapify_down(self, index):
        left_index = self.get_left_child_index(index)
        right_index = self.get_right_child_index(index)

        # Find the smallest item from the parent, left child and right child
        smallest_index = index
        if left_index < self.size and self.array[left_index] < self.array[smallest_index]:
            smallest_index = left_index
        if right_index < self.size and self.array[right_index] < self.array[smallest_index]:
            smallest_index = right_index

        if smallest_index != index:
            # Swap the values at current and smallest index
            self.array[index], self.array[smallest_index] = self.array[smallest_index], self.array[index]

            # Heapify down at the smallest index
            self.heapify_down(smallest_index)

    def heapify_up(self, index):
        parent_index = self.get_parent_index(index)

        # Swap the values at current and parent index if needed
        if parent_index >= 0 and self.array[index] < self.array[parent_index]:
            self.array[index], self.array[parent_index] = self.array[parent_index], self.array[index]
            self.heapify_up(parent_index)

    def insert(self, value):
        # Append the new value at the end of array
        self.array.append(value)
        self.size += 1

        # Heapify up at the last index
        self.heapify_up(self.size - 1)

    def extract_min(self):
        # Remove the element at the root
        min_value = self.array[0]
        self.array[0] = self.array[-1]
        self.array.pop()
        self.size -= 1

        if self.size:
            # Heapify down at the root
            self.heapify_down(0)

        return min_value

    def build_heap(self):
        for i in range(self.size // 2 - 1, -1, -1):
            self.heapify_down(i)

