function followPath(grid, start, end, path) {
   // If we've reached the end, return true
   if (start == end) {
      return true;
   }

   // Mark current node as visited
   grid[start[0]][start[1]] = "v";

   // Calculate the valid neighbors
   let neighbors = getValidNeighbors(grid, start);

   // Iterate through neighbors
   for (let i = 0; i < neighbors.length; i++) {
      let [row, col] = neighbors[i];

      // If this neighbor is the goal, add it to the path
      if (row == end[0] && col == end[1]) {
         path.push(neighbors[i]);
         return true;
      }

      // if this neighbor isn't visited, add it to the path 
      // and recursively call followPath
      if (grid[row][col] == "O") {
         path.push(neighbors[i])
         if (followPath(grid, neighbors[i], end, path)) {
            return true;
         }
      }
   }

   // No valid path
   return false;
}

