  a = a.lower()
  b = b.lower()
  if len(a) != len(b):
    return False
  frequency = {}
  for c in a:
    if c in frequency:
      frequency[c] += 1
    else:
      frequency[c] = 1
  for c in b:
    if c not in frequency or frequency[c] == 0:
      return False
    frequency[c] -= 1
  return True

