vector<int> merge_lists(vector<int> list1, vector<int> list2) {
    int size1 = list1.size();
    int size2 = list2.size();
    int i = 0, j = 0;
    vector<int> result;

    while(i < size1 && j < size2) {
        if(list1[i] < list2[j]) {
            result.push_back(list1[i]);
            i++;
        }
        else {
            result.push_back(list2[j]);
            j++;
        }
    }

    while(i < size1) {
        result.push_back(list1[i]);
        i++;
    }
    while(j < size2) {
        result.push_back(list2[j]);
        j++;
    }

    return result;
}

