import nltk

def generate_ngrams(text, n):
  lst = text.split()
  ngrams = []

  for i in range(len(lst)-n+1):
    ngrams.append(' '.join(lst[i:i+n]))

  return ngrams

def generate_summary(text, n):
  freq_table = {}

  for ngram in generate_ngrams(text, n):
    if ngram in freq_table:
      freq_table[ngram] += 1
    else:
      freq_table[ngram] = 1

  sorted_freq_table = sorted(freq_table.items(), key=lambda x: x[1], reverse=True)

  summary = ''
  for (ngram, count) in sorted_freq_table[:3]:
    summary += ngram + ' '

  return summary

