const elements = { 
 'o': { symbol: 'O', score: 1 },
 'x': { symbol: 'X', score: -1 }
}

// Determine the winning score
const winningScore = Math.abs(Object.values(elements).reduce((total, element) => total += element.score, 0))

// Start game loop
let currentElement = elements.o;

while (true) {
  // Print board
  for (let row = 0; row < boardSize; row++) {
   console.log(board[row].join('|'));
  }

  // Get and evaluate next move
  let row = prompt(`Player ${currentElement.symbol} - Pick row:`);
  let col = prompt(`Player ${currentElement.symbol} - Pick col:`);
  let position = board[row][col];

  if (position === ' ') {
   board[row][col] = currentElement.symbol;
  } else {
   console.log('Position already taken!');
   continue;
  }

  // Calculate scores
  let oScore = 0;
  let xScore = 0;
  for (let row = 0; row < boardSize; row++) {
   for (let col = 0; col < boardSize; col++) {
    const position = board[row][col];
    if (position === elements.x.symbol) {
     xScore += elements.x.score;
    } else if (position === elements.o.symbol) {
     oScore += elements.o.score;
    }
   }
  }

  // Determine winner
  if (oScore === winningScore) {
   console.log('Player O wins!');
   break;
  } else if (xScore === winningScore) {
   console.log('Player X wins!');
   break;
  }

  // Change current element
  currentElement = (currentElement === elements.o) ? elements.x : elements.o;
}

