};

const ListToDoIntentHandler = {
  canHandle(handlerInput) {
    const request = handlerInput.requestEnvelope.request;
    return request.type === 'IntentRequest'
      && request.intent.name === 'ListToDoIntent';
  },
  handle(handlerInput) {
    let speechText;

    if (toDoList.length > 0) {
      speechText = `Your To-Do list has ${toDoList.length} items. Your To-Do list includes ${toDoList.join(', ')}. What else can I help you with?`;
