}

addItem() {
 this.setState(prevState => {
  const newItems = [...prevState.items, this.state.text];
  return {
   items: newItems,
   text: ""
  };
 });
}

removeItem(index) {
 this.setState(prevState => {
  const items = [...prevState.items];
  items.splice(index, 1);
  return { items };
 });
}

editItem(index) {
 this.setState(prevState => {
  const items = [...prevState.items];
  items[index] = this.state.text;
  return { items, text: "" };
 });
}

render() {
