def find_longest_common_substring(string1, string2):
    # find the length of the two strings
    str1_len = len(string1) 
    str2_len = len(string2) 
    # initialize a 2-dimensional array
    LCS = [[0 for x in range(str2_len+1)] for y in range(str1_len+1)]
    # find the longest common substring
    for i in range(str1_len+1):
        for j in range(str2_len+1):
            if(i == 0 or j == 0):
                LCS[i][j] = 0
            elif(string1[i-1] == string2[j-1]):
                LCS[i][j] = LCS[i-1][j-1] + 1
            else:
                LCS[i][j] = 0
    # find the maximum element in the matrix
    max = 0
    for i in range(str1_len+1):
        for j in range(str2_len+1):
            if(max < LCS[i][j]):
                max = LCS[i][j]
    # return the longest common substring
    return max

class Matrix6x6:
    '''Represents a 6x6 matrix, using a list of lists.'''
    def __init__(self, values=None):
        '''
        Create a 6x6 matrix with specified values.
        If no value is provided, creates an empty matrix.
        '''
        self.values = values if values is not None else [[0]* 6 for _ in range(6)]

    def __str__(self):
        '''Return a string representation of the matrix'''
        return '\n'.join([' '.join([str(val) for val in row]) for row in self.values])

    def multiply(self, other):
        '''Return the product of this matrix and another matrix.'''
        if self.width != other.height:
            raise ValueError('Cannot multiply matrices of different sizes.')
        out = Matrix6x6()
        for i in range(self.height):
            for j in range(other.width):
                for k in range(self.width):
                    out.values[i][j] += self.values[i][k] * other.values[k][j]
        return out

    def transpose(self):
        '''Return a new matrix that is the transpose of this one.'''
        out = Matrix6x6()
        for i in range(self.height):
            for j in range(self.width):
                out.values[j][i] = self.values[i][j]
        return out

    @property
    def width(self):
        return len(self.values[0])

    @property
    def height(self):
        return len(self.values)

