// function to sort the linked list 
void sortedList(struct node **head_ref) 
{ 
    struct node *ptr1; 
    struct node *lptr = NULL; 

    /* check if list has only one node or empty*/
    if (*head_ref == NULL || (*head_ref)->next == NULL) 
        return; 

    /* Else take two pointers for two consecutive nodes */
    do
    { 
        ptr1 = *head_ref; 

        while (ptr1->next != lptr) 
        { 
            /* If adjacent nodes are in wrong order then swap them*/
            if (ptr1->data > ptr1->next->data) 
            { 
                int temp = ptr1->data; 
                ptr1->data = ptr1->next->data; 
                ptr1->next->data = temp; 
            } 
            ptr1 = ptr1->next; 
        } 
        lptr = ptr1; 
    } 
    while(ptr1 != *head_ref); 
}

