public class Elevator {

	// Instance variables
	private int numberOfFloors;
	private int currentFloor;
	private static int MAX_FLOORS = 10;

	// Constructor
	public Elevator() {
		numberOfFloors = MAX_FLOORS;
		currentFloor = 0;
	}

	// Getters
	public int getNumberOfFloors() {
		return numberOfFloors;
	}

	public int getCurrentFloor() {
		return currentFloor;
	}

	// Setters
	public void setNumberOfFloors(int numOfFloors) {
		if(numOfFloors <= MAX_FLOORS)
			numberOfFloors = numOfFloors;
	}

	public void setCurrentFloor(int currentFloor) {
		if(currentFloor <= numberOfFloors)
			this.currentFloor = currentFloor;
	}

	// Public methods
	public void goUp() {
		if(currentFloor < numberOfFloors) {
			currentFloor++;
			System.out.println("Elevator is now on the " + currentFloor + " floor.");
		}
	}

	public void goDown() {
		if(currentFloor > 0) {
			currentFloor--;
			System.out.println("Elevator is now on the " + currentFloor + " floor.");
		}
	}

}

// Function to remove all edge nodes in a binary tree 
void removeEdgeNodes(Node* root) 
{ 
    // Base case 
    if (root == NULL) 
        return; 

    // If left child is required to be deleted 
    if (root->left != NULL &&  
        (root->left->left == NULL &&  
         root->left->right == NULL)) 
    { 
        // Delete the left child 
        delete (root->left); 
        root->left = NULL; 
    } 

    // If right child is required to be deleted 
    if (root->right != NULL &&  
        root->right->left == NULL && 
        root->right->right == NULL) 
    { 
        delete (root->right); 
        root->right = NULL; 
    } 

    // Recur for the left and right child 
    removeEdgeNodes(root->left); 
    removeEdgeNodes(root->right); 
}

