  require(getBalance(msg.sender) >= _currencyAmount);
  uint256 senderBalance = getBalance(msg.sender);
  senderBalance -= _currencyAmount;
  uint256 receiverBalance = getBalance(_toAddress);
  receiverBalance += _currencyAmount;
  setBalance(msg.sender, senderBalance);
  setBalance(_toAddress, receiverBalance);
 }

