public static int findMaxRepeatingNumber(int[] arr)  
{ 
    int maxRepeating = 0; 

    // Iterate through array elements 
    // and update the count 
    int n = arr.length; 
    for (int i = 0; i < n; i++) 
    {     
        if (arr[i] <= n) 
        { 
            arr[arr[i] % n] += n; 

            // Update maxRepeating if  
            // required 
            if (maxRepeating < arr[i] % n) 
                maxRepeating = arr[i] % n; 
        } 
    } 

    // Return result 
    return maxRepeating / n; 
}

