 this.stack = new int[size];
 this.top = -1;
 }

 public void push(int item) {
 if (top == stack.length - 1)
 throw new StackOverflowError();

 stack[++top] = item;
 }

 public int pop() {
 if (top == - 1)
 throw new EmptyStackException();

 return stack[top--];
 }

 public int size() {
 return top + 1;
 }

 public boolean isEmpty() {
 return (top == -1);
 }
}

