class Stack: 

    def __init__(self): 
        self.stack = [] 

    def push(self, data): 
        self.stack.append(data) 

    def pop(self): 
        if len(self.stack) < 1:
            return None 
        else: 
            return self.stack.pop() 

    def top(self): 
        if len(self.stack) < 1:
            return None 
        else: 
            return self.stack[-1] 

    def is_empty(self): 
        return len(self.stack) == 0

