def find_all_substrings(s, k):
    substrings = []
    for start_idx in range(len(s)):
        if start_idx + k > len(s):
            break
        for end_idx in range(start_idx+k, len(s)+1):
            substrings.append(s[start_idx:end_idx])
    return substrings

