using System;
using System.Collections.Generic;

public class Calculator
{
 private Stack<string> operators;
 private Stack<double> operands;

 public Calculator()
 {
 operators = new Stack<string>();
 operands = new Stack<double>();
 }

 public double Calculate(string expression)
 {
 //Parse expression into list of tokens
 List<string> tokens = ParseExpression(expression);

//Calculate expression using two stacks
 foreach (string token in tokens)
 {
 if (token == "(")
 {
 //Do nothing
 }
 else if (token == "+" || token == "-" || token == "*" || token == "/")
 {
 //Operator, push onto operator's stack
 operators.Push(token);
 }
 else if (token == ")")
 {
 //Close parentheses, pop of operator's stack and operation
 string operator = operators.Pop();
 double rightOperand = operands.Pop();
 double leftOperand = operands.Pop();

if (operator == "+")
 {
 operands.Push(leftOperand + rightOperand);
 }
 else if (operator == "-")
 {
 operands.Push(leftOperand - rightOperand);
 }
 else if (operator == "*")
 {
 operands.Push(leftOperand * rightOperand);
 }
 else if (operator == "/")
 {
 operands.Push(leftOperand / rightOperand);
 }
 }
 else
 {
 //Number, push on operand stack
 operands.Push(double.Parse(token));
 }
 }

//Return the result of the expression
 return operands.Pop();
 }

//Method to parse expression into tokens
 private List<string> ParseExpression(string expression)
 {
 List<string> tokens = new List<string>();
 string token = "";

for (int i = 0; i < expression.Length; i++)
 {
 if (expression[i] == ' ')
 {
 //Skip whitespace
 continue;
 }
 else if (expression[i] == '(' || expression[i] == ')' || expression[i] == '+' || expression[i] == '-' || expression[i] == '*' || expression[i] == '/')
 {
 //Operator, add token to list
 if (token != "")
 {
 tokens.Add(token);
 }
 tokens.Add(expression[i].ToString());
 token = "";
 }
 else
 {
 //Number, build up token
 token += expression[i];
 }
 }

//Add last token
 if (token != "")
 {
 tokens.Add(token);
 }

return tokens;
 }
}

