public class Main {
    public static boolean isSubarraySum(int[] arr, int sum) {
        if (arr.length == 0) {
            return false;
        }

        int currSum = arr[0];
        int start = 0;
        for (int i = 1; i <= arr.length; i++) {
            // subtract the first element of the subarray 
            // if current sum is greater than the given sum
            while (currSum > sum && start < (i - 1)) {
                currSum = currSum - arr[start];
                start++;
            }

            if (currSum == sum) {
                return true;
            }

            // add the next element if not traversed the array
            if (i < arr.length) {
                currSum = currSum + arr[i];
            }
        }

        return false;
    }

    public static void main(String[] args) {
        int[] arr = { 8, 5, 6, 1 };
        int sum = 11;

        boolean isSum = isSubarraySum(arr, sum);
        if (isSum) {
            System.out.println("Array contains a contiguous subarray with given sum.");
        } else {
            System.out.println("Array does not contain a contiguous subarray with given sum.");
        }
    }
}

public class Queue 
{ 
    int front, rear, size; 
    int  capacity; 
    int array[]; 

    public Queue(int capacity) 
    { 
        this.capacity = capacity; 
        front = this.size = 0;  
        rear = capacity - 1; 
        array = new int[this.capacity]; 

    } 

    // Queue is full when size becomes equal to  
    // the capacity  
    boolean isFull(Queue queue) 
    {  return (queue.size == queue.capacity); 
    } 

    // Queue is empty when size is 0 
    boolean isEmpty(Queue queue) 
    {  return (queue.size == 0); } 

    // Method to add an item to the queue.  
    // It changes rear and size 
    void enqueue( int item) 
    { 
        if (isFull(this)) 
            return; 
        this.rear = (this.rear + 1)%this.capacity; 
        this.array[this.rear] = item; 
        this.size = this.size + 1; 
        System.out.println(item+ " enqueued to queue"); 
    } 

    // Method to remove an item from queue.   
    // It changes front and size 
    int dequeue() 
    { 
        if (isEmpty(this)) 
            return Integer.MIN_VALUE; 

        int item = this.array[this.front]; 
        this.front = (this.front + 1)%this.capacity; 
        this.size = this.size - 1; 
        return item; 
    } 

    // Method to get front of queue 
    int front() 
    { 
        if (isEmpty(this)) 
            return Integer.MIN_VALUE; 

        return this.array[this.front]; 
    } 

    // Method to get rear of queue 
    int rear() 
    { 
        if (isEmpty(this)) 
            return Integer.MIN_VALUE; 

        return this.array[this.rear]; 
    } 
}

