function optimizeArray(arr) {
 let min;

 // Loop through the array
 for (let i=0; i < arr.length; i++) {
  // Set the min to the first element of the array
  if (i === 0) {
   min = arr[i];
  }

  // Find the next smallest number in the array
  for (let j=i+1; j < arr.length; j++) {
   if (arr[j] < min) {
    min = arr[j];
   }
  }

  // Replace the current element with the smallest number
  arr[i] = min;
 }

 return arr;
}

