#version 450 core
layout (location=0) in vec3 aPos; //Position of the vertex
layout (location=1) in vec2 aTexCoord; //Texture coordinate for the vertex

layout (location=0) out vec4 FragColor; //Fragment color of the vertex
layout (location=1) out vec3 Normal; // Normal vector

// Shader Uniforms
uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

//Shaders for lighting 
uniform vec3 viewPos; // Camera position
uniform vec3 lightPos;  // Light Position
uniform vec3 ambientLight; // Light Color

// Main
void main()
{
    // Calculate the normal vector
    vec3 normal = normalize(mat3(model) * aPos);

    // Calculate the output fragment color
    FragColor = ambientLight * lowp vec4(1.0f, 1.0f, 1.0f, 1.0f); // Ambient light 

    // Calculate the output normal vector
    Normal = normalize(model * vec4(normal, 0.0f)).xyz;

    // Transform vertex position to world coordinates
    vec4 worldPos = model * vec4(aPos, 1.0f);

    // Calculate the lighting 
    vec3 lightDir = normalize(lightPos - worldPos.xyz);
    float diff = max(dot(normal, lightDir), 0.0f);
    vec4 diffuseLight = diff * vec4(1.0f, 1.0f, 1.0f, 1.0f);
    FragColor += diffuseLight;

    // Change coordinate space from world to camera space
    vec4 viewPos4 = view * vec4(worldPos.xyz, 1.0f);
    gl_Position = projection * viewPos4;
}

