class Game {
constructor() { 
 this.player1 = null;
 this.player2 = null;
 this.activePlayer = null;
 this.gameBoard = [
 ['', '', ''],
 ['', '', ''],
 ['', '', '']
 ];
 this.joinGame = this.joinGame.bind(this); 
 this.isGameFull = this.isGameFull.bind(this);
 this.switchActivePlayer = this.switchActivePlayer.bind(this); 
 this.makeMove = this.makeMove.bind(this);
 this.isGameOver = this.isGameOver.bind(this);
 }

 joinGame(player) {
 if (this.player1 === null) {
  this.player1 = player;
  this.activePlayer = player;
  return 'Player 1';
 } 
 if (this.player2 === null) {
  this.player2 = player;
  return 'Player 2';
 }
 return false;
 }

 isGameFull() {
 return (this.player1 && this.player2) ? true : false;
}

switchActivePlayer() {
 this.activePlayer = (this.activePlayer === this.player1) ? this.player2 : this.player1; 
}

makeMove(player, x, y) {
 if (player !== this.activePlayer) {
  return 'It is not your turn!';
 }
 if (this.gameBoard[x][y] !== '') {
  return 'Invalid Move!';
 }
 this.gameBoard[x][y] = player.symbol;
 this.switchActivePlayer();
 return this.gameBoard;
}

isGameOver() {
 let symbols = ["X", "O"];
 let isWin = false; 

 for (let i = 0; i < symbols.length; i++) {
  let symbol = symbols[i];
  if (
   this.gameBoard[0][0] == symbol && this.gameBoard[0][1] == symbol && this.gameBoard[0][2] == symbol ||
   this.gameBoard[1][0] == symbol && this.gameBoard[1][1] == symbol && this.gameBoard[1][2] == symbol ||
   this.gameBoard[2][0] == symbol && this.gameBoard[2][1] == symbol && this.gameBoard[2][2] == symbol ||
   this.gameBoard[0][0] == symbol && this.gameBoard[1][0] == symbol && this.gameBoard[2][0] == symbol ||
   this.gameBoard[0][1] == symbol && this.gameBoard[1][1] == symbol && this.gameBoard[2][1] == symbol ||
   this.gameBoard[0][2] == symbol && this.gameBoard[1][2] == symbol && this.gameBoard[2][2] == symbol ||
   this.gameBoard[0][0] == symbol && this.gameBoard[1][1] == symbol && this.gameBoard[2][2] == symbol ||
   this.gameBoard[2][0] == symbol && this.gameBoard[1][1] == symbol && this.gameBoard[0][2] == symbol 
   ) {
   isWin = true;
   break;
  }
 }

 let isDraw = this.gameBoard.every(row => row.every(cell => cell !== ''));  

 return isWin || isDraw;
}

}

