using namespace std; 

// m is size of coins array 
// (number of different coins) 
int minCoins(int coins[], int m, int amount) { 
    // table[i] will be storing 
    // the minimum number of coins 
    // required for i value. So 
    // table[amount] will have result 
    vector<int> table(amount + 1, INT_MAX); 

    // Base case (If given value is 0) 
    table[0] = 0; 

    // Pick all coins one by one and 
    // update the table[] values 
    // after the index greater than 
    // or equal to the value of the 
    // picked coin 
    for (int i = 0; i < m; i++) 
        for (int j = coins[i]; j <= amount; j++) 
            table[j] = min(table[j], table[j - coins[i]] + 1); 

    return table[amount]; 
} 

int main() { 
    int coins[] = {1, 5, 10, 25, 50}; 
    int m = 5; 
    int amount = 87; 
    cout <<"Minimum coins required is "
        << minCoins(coins, m, amount); 
    return 0; 
}

