int second_smallest(int arr[], int n) 
{ 
    int root = 0; 
    int l, r, min; 

    // loop through the array to get the root
    for(int i=1; i<n; i++) 
    { 
        if (arr[i] < arr[root]) 
            root = i; 
    } 


    min = INT_MAX; 

    // traverse left and right subtrees of root 
    // to find the second smallest elements 
    if (2*root+1 < n && arr[2*root+1] < arr[root]) 
    { 
        l = 2*root + 1; 
        if (arr[l] < min) 
            min = arr[l]; 
    } 

    if (2*root+2 < n &&  arr[2*root+2] < arr[root]) 
    { 
        r = 2*root + 2; 
        if (arr[r] < min) 
            min = arr[r]; 
    } 

    return min; 
}

