function Fibonacci(n) { 
    if (n <= 1) { 
        return n; 
    } 

    let last = 0;
    let current = 1;  
    let temp; 

    for (let i = 2; i <= n; i++) { 
        temp = current; 
        current += last; 
        last = temp; 
    } 
    return current; 
}

