        const sortedWord = word.split('').sort().join('');
        if (anagramsMap[sortedWord] !== undefined) {
            anagramsMap[sortedWord].push(word);
        } else {
            anagramsMap[sortedWord] = [word];
        }
	}

    //Iterating over the map and adding anagrams to the anagrams array.
    for (let anagram in anagramsMap) {
        const words = anagramsMap[anagram];
        if (words.length > 1) {
            anagrams.push(words);
