public static String longestPalindrome(String s) {
    int n = s.length();
    int palindromeBegin = 0;
    int maxLen = 0;
    boolean[][] table = new boolean[n][n]; // boolean 2D array to store state

    // all substrings of length 1 is palindrome
    for (int i = 0; i < n; i++) {
        table[i][i] = true;
    }

    // checking for substring of length 2
    for (int i = 0; i < n-1; i++) {
        if (s.charAt(i) == s.charAt(i+1)) {
            table[i][i+1] = true;
            palindromeBegin = i;
            maxLen = 2;
        }
    }

    // check for lengths 3 and more
    for (int k = 3; k <= n; k++) {
        // fix the starting index
        for (int i = 0; i < n - k + 1 ; i++) {
            //inspect the ending index
            int j = i + k - 1;

            if (table[i+1][j-1] && s.charAt(i) == s.charAt(j)) {
                table[i][j] = true;

                if (k > maxLen) {
                    palindromeBegin = i;
                    maxLen = k;
                }
            }
        }
    }

    return s.substring(palindromeBegin, maxLen + palindromeBegin);
}

