// Utility function to print the indices 
void printIndices(std::vector<int> arr) 
{ 
    for (int i = 0; i < arr.size(); i++) 
        std::cout << i << " "; 
    std::cout << std::endl; 
} 

// Function to find the indices of sorted elements 
void findIndices(std::vector<int> arr) 
{ 
    int n = arr.size(); 
    std::vector<int> index(n); 
    for (int i = 0; i < n; i++) 
        index[i] = i; 

    for (int i = 0; i < n - 1; i++) 
        for (int j = i + 1; j < n; j++) 
            if (arr[index[i]] > arr[index[j]]) 
                std::swap(index[i], index[j]); 

    printIndices(index); 
} 

// Driver Code 
int main() 
{ 
    std::vector<int> arr { 3, 6, 1, 7 };
    findIndices(arr); 
    return 0; 
}

