def group_anagrams(words):  
    # Create a dict to store the result 
    grouped_words = {}  

    # Loop through all the words 
    for word in words:  

        # Convert the word to a sorted array of characters 
        key = ''.join(sorted(word))  

        # If the key doesn't exist in 
        # the dict, create a new key 
        if key not in grouped_words:  
            grouped_words[key] = [word]  

        # Add the word to existing key
        else: 
            grouped_words[key].append(word)  

    # return the grouped words
    return grouped_words  

