def most_frequent_word(data):
    words = {}
    for word in data:
        if word in words:
            words[word] += 1
        else:
            words[word] = 1
    max_count = 0
    most_frequent_word = ""
    for word, count in words.items():
        if count > max_count:
            max_count = count
            most_frequent_word = word
    return most_frequent_word

