class Matrix: 
    def __init__(self, m, n, lst): 
        self.m = m             
        self.n = n             
        self.mat = [] 

        c = 0
        for i in range(self.m): 
            a =[] 
            for j in range(self.n): 
                    a.append(lst[c]) 
                    c += 1
            self.mat.append(a) 

    def __str__(self): 
        output = ""
        for i in self.mat: 
            for j in i: 
                output += str(j) + " "
            output += '\n'
        return output 

    def add(self, mat2): 
        for i in range(self.m): 
            for j in range(self.n): 
                self.mat[i][j] += mat2.mat[i][j] 

    def sub(self, mat2): 
        for i in range(self.m): 
            for j in range(self.n): 
                self.mat[i][j] -= mat2.mat[i][j]

    def mul(self, mat2): 
        result = [] 
        for i in range(self.m): 
            a =[] 
            for j in range(mat2.n): 
                s = 0
                for k in range(self.n): 
                    s += self.mat[i][k] * mat2.mat[k][j] 
                a.append(s) 
            result.append(a) 
        self.mat = result 
        self.m = len(result) 
        self.n = len(result[0]) 

    def transpose(self):
        result = [[self.mat[j][i] for j in range(len(self.mat))] for i in range(len(self.mat[0]))]
        self.mat = result 
        self.m = len(result) 
        self.n = len(result[0])

#include <iostream> 

int deleteElement(int arr[], int n, int elem) 
{ 
    int temp = 0; 
    for (int i = 0; i < n; i++) 
        if (arr[i] == elem) { 
            temp = arr[i]; 
            arr[i] = arr[n - 1]; 
            arr[n - 1] = temp; 
            n--;
        } 

    return n; 
} 

int main() 
{ 
    int arr[] = {2, 3, 4, 7, 8}; 
    int n = sizeof(arr) / sizeof(arr[0]);
    int element = 4;
    n = deleteElement(arr, n, element);

    // Printing the array 
    for (int i = 0; i < n; i++) 
        std::cout << arr[i] << " ";

    return 0; 
}

