fn histogram(line: &str) -> Vec<&str> {
  let mut chars : Vec<&str> = vec![];
  for c in line.chars() {
      chars.push(&c.to_string());
  }

  let mut counts : Vec<i32> = vec![0; chars.len()];
  for i in 0..chars.len() {
      for c in line.chars() {
          if chars[i] == &c.to_string() {
              counts[i] += 1;
          }
      }
  }

  let mut result : Vec<String> = vec![];
  for i in 0..chars.len() {
      let mut output = String::new();
      output.push_str(chars[i]);
      output.push_str(": ");
      for _ in 0..counts[i] {
          output.push('*');
      }
      result.push(output);
  }
  result
}

