def two_sum_indexes(arr, target):
    # create a hashtable to store number complements
    comp = {}
    # iterate through each element of the array
    for i, num in enumerate(arr):
        # look for complement
        if target - arr[i] in comp:
            return (i, comp[target - arr[i]])
        # store complement in the hashtable
        comp[num] = i
    # return (-1, -1) if no solution exists
    return (-1, -1)

