def evalPostfix(exp): 
    stack = [] 
    for char in exp: 
        # If the scanned character is  
        # an operand, push it to the stack  
        if char.isdigit():  
            stack.append(char) 
        else: 
            val1 = stack.pop()  
            val2 = stack.pop() 
