          left++;
        }
        // Decrement right
        while (arr[right] % 2 != 0 && left < right) {
          right--;
        }
        // Swap
        if (left < right) {
          int temp = arr[left];
          arr[left] = arr[right];
          arr[right] = temp;
        }
      }
    }

    static void print_array(int[] arr) {
      for (int i = 0; i < arr.length; i++) {
        System.out.print(arr[i] + " ");
      }
    }

    public static void main(String[] args) {
      int[] arr = {4, 6, 2, 7, 5, 8, 1};
      rearrange_array(arr);
      print_array(arr);
    }
  }

