def binarySearch(x, b):
    start = 0
    end = len(x)-1

    while start <= end: 
        mid = (start+end)//2
        if x[mid] == b: 
            return mid 
        elif x[mid] < b: 
            start = mid + 1
        else: 
            end = mid - 1
    return -1

