function binarySearch(array, item) {
    let low = 0;
    let high = array.length - 1;
    while (low <= high) {
        let mid = Math.floor((low + high) / 2);
        let searchValue = array[mid];
        if (item === searchValue) {
            return mid;
        } else if (item < searchValue) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return -1;
}

