def max_appearance(string):
    """Function to return the character which appears the most in a given string."""
    # Dictionary to count frequency of each character in the string
    char_dic = {}
    for char in string:
        char_dic[char] = char_dic.get(char,0) + 1

    # Find the character which has maximum frequency
    max_char = ""
    max_frequency = 0
    for char, frequency in char_dic.items():
        if frequency > max_frequency:
            max_char = char
            max_frequency = frequency
    return max_char

