class Stack(object):
    def __init__(self):
        self.items = []

    def is_empty(self):
        return self.items == []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def peek(self):
        return self.items[len(self.items)-1]

    def size(self):
        return len(self.items)

#include <iostream>

// Node structure for linked list
struct Node {
    int data;
    Node* next;
};

// function to reverse the linked list
Node* reverseList(Node* head) {
    Node* prev = NULL;
    Node* current = head;
    Node* next;
    while (current != NULL) {
        // save the next node
        next = current->next;
        // reverse pointer
        current->next = prev;
        // move pointers one position ahead
        prev = current;
        current = next;
    }
    return prev;
}

// function to insert a node at the beginning
void push(Node** head_ref, int new_data) 
{ 
    // allocating node 
    Node* new_node = new Node(); 

    // inserting data 
    new_node->data = new_data; 

    // make next of new node as head 
    new_node->next = (*head_ref); 

    // move the head to point to  the new node 
    (*head_ref) = new_node; 
}

// function to print nodes of a linked list
void printList(Node* node) 
{ 
    while (node != NULL) { 
        std::cout << node->data << " "; 
        node = node->next; 
    } 
} 

