int main() 
{ 
    Node* head = NULL; 
    push(&head, 20); 
    push(&head, 4); 
    push(&head, 15); 
    push(&head, 85); 

    std::cout << "Original linked list: "; 
    printList(head); 
    head = reverseList(head); 
    std::cout << "\nReversed linked list: "; 
