def fibonacci(n):
    # base case: the first two terms of the Fibonacci sequence are 0 and 1 respectively
    if n == 0 or n == 1:
        return n 

    # recurrence relation: the nth term is the sum of the previous two terms
    return fibonacci(n-1) + fibonacci(n-2)

