int longestIncreasingSubarray(std::vector<int> arr) {
    int max_length = 0;
    int current_length = 0;

    for (int i = 0; i < arr.size() - 1; i++) {
        if (arr[i] < arr[i + 1]) {
            current_length++;
            if (current_length > max_length) {
                max_length = current_length;
            }
        } else {
            current_length = 0;
        }
    }
    return max_length + 1;
}

