import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
import java.util.ArrayList;

public class Snake extends JPanel {
 // Size of the panel
 private final int X_DIMENSION = 500;
 private final int Y_DIMENSION = 500;

 // List of points representing the snake body
 private ArrayList<Point> snake = new ArrayList<Point>();

 // Size of each square representing 1 snake body part
 private final int SQUARE_SIZE = 10; 

 // Point representing the food
 private Point food;

 // Direction of the snake
 private int dirX, dirY;

 public Snake() {
  // Initialize 
  setSize(X_DIMENSION, Y_DIMENSION);

  // Create the initial snake
  snake.add(new Point(X_DIMENSION/2, Y_DIMENSION/2));

  // Create the initial food
  createFood();

  // Set direction of snake
  dirX = 0;
  dirY = 0;

  // Listener for the panel
  addKeyListener(new KeyListener() {

   public void keyPressed(KeyEvent e) {
    int keyCode = e.getKeyCode();

    // Determine the direction of the snake according to key pressed
    switch (keyCode) {
     case KeyEvent.VK_UP:
      dirY = -1;
      dirX = 0;
      break;
     case KeyEvent.VK_DOWN:
      dirY = 1;
      dirX = 0;
      break;
     case KeyEvent.VK_LEFT:
      dirX = -1;
      dirY = 0;
      break;
     case KeyEvent.VK_RIGHT:
      dirX = 1;
      dirY = 0;
      break;
    }
   }

   public void keyReleased(KeyEvent e) {}
   public void keyTyped(KeyEvent e) {}
  });

  // Start the game
  run();
 }

 // Main game loop
 private void run() {
  while (true) {
   // 300ms time delay for movement
   try {
    Thread.sleep(300);
   } catch (InterruptedException e) {}

   // Move snake either left, right, up, or down
   moveSnake();

   // Check collision
   if (checkCollision()) {
    endGame();
    break;
   }

   // Refresh panel
   repaint();
  }
 }

 // Helper method for moving snake
 private void moveSnake() {
  Point head = snake.get(0);
  head.x += dirX * SQUARE_SIZE;
  head.y += dirY * SQUARE_SIZE;

  // Check if the snake eats the food
  if (head.equals(food)) {
   // Increase size of snake
   snake.add(food);
   // Create a new food
   createFood();
  }

  // Shift elements of the array and set the head
  for (int i = snake.size() - 1; i > 0; i--) {
   snake.get(i).x = snake.get(i - 1).x;
   snake.get(i).y = snake.get(i - 1).y;
  }
  snake.set(0, head);
 }

 // Helper method for creating food
 private void createFood() {
  int randX = SQUARE_SIZE + (int) (Math.random() * X_DIMENSION);
  int randY = SQUARE_SIZE + (int) (Math.random() * Y_DIMENSION);
  food = new Point(randX, randY);
 }

 // Helper method for checking collision
 private boolean checkCollision() {
  Point head = snake.get(0);
  // Collision when the head touches the border
  if (head.x < 0 || head.x > X_DIMENSION || head.y < 0 || head.y > Y_DIMENSION)
   return true;

  // Collision when the head touches its own body
  for (int i = 1; i < snake.size(); i++) {
   if (head.equals(snake.get(i)))
    return true;
  }

  return false;
 }

 // Draw the snake onto the board
 public void paintComponent(Graphics g) {
  super.paintComponent(g);

  // Draw food
  g.setColor(Color.RED);
  g.fillRect(food.x, food.y, SQUARE_SIZE, SQUARE_SIZE);

  // Draw snake
  g.setColor(Color.GREEN);
  for (Point p : snake)
   g.fillRect(p.x, p.y, SQUARE_SIZE, SQUARE_SIZE);
 }

 // Initiates a pop-up window when game is lost
 private void endGame() {
  JOptionPane.showMessageDialog(this, "Game Over!");
 }

public static void main(String[] args) {
 JFrame window = new JFrame("Snake");
 window.add(new Snake());
 window.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
 window.setSize(500, 500);
 window.setVisible(true);
}

