fn length_of_longest_substring(s: String) -> usize {
    let mut longest = 0;
    let mut characters = std::collections::HashSet::new(); 

    for (index, character) in s.chars().enumerate() {
        if characters.contains(&character) {
            characters.clear();
        }
        characters.insert(character);
        longest = std::cmp::max(longest, index + 1 - characters.len());
    }

    return longest;
}

fn main() {
    let string = String::from("abcabcbb");

    let length = length_of_longest_substring(string.clone());

    println!("The longest substring in '{}' is '{}'", string, &string[0..length]);
