using namespace std;

// Check if a given cell is valid
bool is_valid_cell(vector<vector<int>>& sudoku, int row, int col, int num) {
    // Check the given row
    for (int i=0; i<9; i++) {
        if (sudoku[row][i] == num) 
            return false;
    }

    // Check the given column
    for (int i=0; i<9; i++) {
        if (sudoku[i][col] == num) 
            return false;
    }

    // Check the 3x3 box
    int box_row = ((row/3) * 3); 
    int box_col = ((col/3) * 3); 
    for (int i=box_row; i<box_row+3; i++) 
        for (int j=box_col; j<box_col+3; j++) 
            if (sudoku[i][j] == num) 
                return false; 

    // If there is no violation, the cell is valid
    return true; 
} 

// Solve the given sudoku puzzle using a backtracking algorithm
bool solve_sudoku(vector<vector<int>>& sudoku) { 
    int row, col; 
    // Find the empty cell
    bool found_empty_cell = false; 
    for (row = 0; row < 9; row++) 
        for (col = 0; col < 9; col++) 
            if (sudoku[row][col] == 0) { 
                found_empty_cell = true; 
                break; 
            } 

    // No empty cell found, return true
    if (!found_empty_cell) 
        return true; 

    // Try all numbers from 1 to 9
    for (int num = 1; num <= 9; num++)
    { 
        // Check if the number is valid
        if (is_valid_cell(sudoku, row, col, num))
        { 
            // Make changes 
            sudoku[row][col] = num; 

            // Recur for the remaining cells
            if (solve_sudoku(sudoku)) 
                return true; 

            // Backtrack
            sudoku[row][col] = 0; 
        } 
    } 
    return false; 
}

// Print the solved sudoku
void print_sudoku(vector<vector<int>>& sudoku) {
    for (int i = 0; i < 9; i++) { 
        for (int j = 0; j < 9; j++){ 
            cout << sudoku[i][j] << " "; 
        }
        cout << endl; 
    } 
	cout << endl;
}

