def square_root(number):
    low = 0
    high = number
    while low <= high:
        mid = (low + high) // 2
        mid_squared = mid * mid
        if mid_squared == number:
            return mid
        elif mid_squared < number:
            low = mid + 1
        else:
            high = mid - 1
    return False

