def solve_sudoku(grid):
    # As long as there is an unassigned cell
    for row in range(9):
        for col in range(9):
            if grid[row][col] == 0:
                for number in range(1,10):
                    # Check if it's safe to assign
                    if is_safe(grid, row, col, number):
                        grid[row][col] = number

                        # Recursively call solve_sudoku()
                        if solve_sudoku(grid):
