// function to find total number of rearrangements 
// such that no two adjacent are same 
int countPermutations(string str) 
{ 
    int n = str.length() ; 
    int F[n + 1]; 

    F[0] = F[1] = 1; 

    // Fill restricted applications in bottom up manner 
    for(int i = 2; i <= n; i++) 
    { 
        F[i] = 0; 

        // Count of permutations with first 
        // i-1 characters same as last i-1 
        // characters of permutations 
        // considering i'th character 
        if (str[i - 1] != str[i - 2]) 
            F[i] += F[i - 1]; 

        // Count of permutations with first 
        // i-2 charters same as last i-2 characters 
        // of permutations considering i'th character 
        if (i > 2 && str[i - 2] != str[i - 1]) 
            F[i] += F[i - 2]; 
    } 
    return F[n]; 
} 

