def newton_raphson(f, x0):
    tol = 0.0001
    max_iter = 100

    x_next = x0
    for i in range(max_iter):
        x_prev = x_next
        x_next = x_prev - (f(x_prev) / f'(x_prev))

        if abs(x_next - x_prev) < tol:
            break

    return x_next

