bool binary_search(int arr[], int n, int x) 
{ 
    int start = 0; 
    int end = n-1; 

    while (start <= end) 
    { 
        int mid = (start + end)/2; 

        if (x == arr[mid]) 
            return true; 

        else if (x < arr[mid]) 
            end = mid - 1; 

        else
            start = mid + 1; 
    } 

    return false; 
}

