    // Traverse through the array and segregate even and odd elements 
    for (int i = 0; i < n; i++) { 

        /* If a number is divisible by 2 then it is even */
        if (arr[i] % 2 == 0) { 
            even[e] = arr[i]; 
            e++; 
        } 

        else { 
            odd[o] = arr[i]; 
