def optimize_scheduling(tasks):
    n = len(tasks)
    dp = [[0 for x in range(n)] for x in range(n)] 

    for gap in range(n): 
        i = 0
        j = gap 
        while j < n: 
            if j == i + 1: 
                dp[i][j] = tasks[i]+tasks[j] 
            else: 
                dp[i][j] = min(dp[i+1][j] + tasks[i], 
                               dp[i][j-1] + tasks[j])
            i = i + 1
            j = j + 1
    return dp[0][n-1]

