public List<Integer> alternatingSort(List<Integer> list) {
    int start = 0;
    int end = list.size() - 1;
    boolean isAscending = true;
    while (start < end) {
        if (isAscending) {
            int max = Integer.MIN_VALUE;
            for (int i = start; i <= end; i += 1) {
                if (list.get(i) > max) {
                    max = list.get(i);
                    list.set(i, list.get(start));
                    list.set(start, max);
                }
            }
            start += 1;
            isAscending = !isAscending;
        } else {
            int min = Integer.MAX_VALUE;
            for (int i = end; i >= start; i -= 1) {
                if (list.get(i) < min) {
                    min = list.get(i);
                    list.set(i, list.get(end));
                    list.set(end, min);
                }
            }
            end -= 1;
            isAscending = !isAscending;
        }
    }
    return list;
}

