fun isArmstrong(number: Int): Boolean {
    var k = number
    var temp = 0
    while (k > 0) {
        temp += (k % 10).toDouble().pow(3).toInt()
        k /= 10
    }
    if (temp == number) {
        return true
    }
    return false
}

