public static String classifyDNA(String sequence) {
    float gcCount = 0;
    for (char c : sequence.toCharArray()) {
        if (c == 'G' || c == 'C') {
            gcCount++;
        }
    }
    float gcPercentage = gcCount / sequence.length() * 100;

    if (gcPercentage < 10) {
