// Returns maximum sum from two leaves in given binary tree
int maxSumLeaves(node *root)
{
    // Initialize result
    int sum = 0;

    // If root is NULL
    if (root == NULL)
       return 0;

    // Recursively find maximum sum in
    // left and right subtree
    int leftLeafSum  = maxSumLeaves(root->left);
    int rightLeafSum = maxSumLeaves(root->right);

    // If both left and right child  
    // are leaves
    if (root->left!=NULL && root->left->left==NULL &&
        root->left->right==NULL)
    {
       sum =  root->left->data;
    }

    if (root->right!=NULL && root->right->left==NULL &&
        root->right->right==NULL)
    {
       sum = root->right->data;
    }

    return sum + root->data + 
           max(leftLeafSum, rightLeafSum);
}

