const RockPaperScissors = () => {
 const choices = {
 ROCK: 'rock',
 PAPER: 'paper',
 SCISSORS: 'scissors'
 };

 // Initialize game state
 let userChoice;
 let computerChoice;
 let result;

 // Get user's choice
 const getUserChoice = () => {
 while (!userChoice) {
 const chosen = prompt('Rock, paper, or scissors?');

 if (chosen.toLowerCase() === choices.ROCK ||
 chosen.toLowerCase() === choices.PAPER ||
 chosen.toLowerCase() === choices.SCISSORS) {
 userChoice = chosen.toLowerCase();
 } else {
 alert('Please choose rock, paper, or scissors');
 }
 }
 };

 // Get computer's choice
 const getComputerChoice = () => {
 const randNum = Math.floor(Math.random() * 3);

 switch (randNum) {
 case 0:
 computerChoice = choices.ROCK;
 break;
 case 1:
 computerChoice = choices.PAPER;
 break;
 case 2:
 computerChoice = choices.SCISSORS;
 }
 };

 // Determine winner
 const determineWinner = () => {
 if (userChoice === computerChoice) {
 result = 'Tie!';
 } else if (
 (userChoice === choices.ROCK && computerChoice === choices.SCISSORS) ||
 (userChoice === choices.PAPER && computerChoice === choices.ROCK) ||
 (userChoice === choices.SCISSORS && computerChoice === choices.PAPER)
 ) { 
 result = 'You win!';
 } else { 
 result = 'Computer wins!';
 }
 };

 // Start the game
 const startGame = () => {
 getUserChoice();
 getComputerChoice();
 determineWinner();
