class LinkedList {
  constructor() {
    this.head = null
    this.size = 0
  }

  // add node to the List
  add(data) {
    // create a new node
    let node = new Node(data)
    let current

    // if list is empty assign node to head
    if (this.head == null) {
      this.head = node
    } else {
      current = this.head

      while (current.next) {
        current = current.next
      }

      current.next = node
    }
    this.size++;
  }
}

