#include <iostream>
#include <vector>
using namespace std;

int getSmallestPositiveInteger(vector<int> arr) 
{ 
    int n = arr.size(); 

    // Creates an array of size n + 1 
    // and initialize all element of it as false 
    vector<bool> temp(n + 1, false); 

    // Initialize result 
    int res = n + 1; 

    // Do following for each element of input array 
    for (int i = 0; i < n; i++) { 
        // If an element is seen before 
        if (arr[i] > 0 && arr[i] <= n) 
            temp[arr[i]] = true; 
    } 

    // Run through all positive elements 
    for (int i = 1; i <= n; i++) 
        if (temp[i] == false) { 
            res = i; 
            break; 
        } 

    return res; 
} 

int main() 
{ 
    vector<int> arr = { 1, 3, 6, 4, 1, 2 };   
    int result = getSmallestPositiveInteger(arr); 
    cout << "Smallest positive missing element is " << result; 
    return 0; 
}

