function validateBrackets(str) {
  // Variables to store values of open and close brackets
  let openBrackets = "{[(";
  let closeBrackets = "}])";

  // Create empty stack to store all open brackets
  let stack = [];

  // Loop through the string
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    // Check if the character is an open bracket
    if (openBrackets.indexOf(ch) !== -1) {
      // Push the open bracket to the stack
      stack.push(ch);
    }
    // Check if the character is a close bracket
    else if (closeBrackets.indexOf(ch) !== -1) {
      // Check if the current close bracket matches the last open bracket in the stack
      if (
        stack.length === 0 ||
        openBrackets.indexOf(stack[stack.length - 1]) !==
          closeBrackets.indexOf(ch)
      ) {
        // Returns false if the close bracket doesn't match the last open bracket
        return false;
      }
      // If the close bracket matches the corresponding open bracket, 
      // then remove the open bracket from the stack
      stack.pop();
    }
  }
  // Returns true if all brackets are properly closed
  return stack.length === 0;
}

