def min_hops(source, destination):
 visited = set()
 queue = [(source, 0)]

 while queue:
  node, hops = queue.pop(0)
  if node not in visited:
   visited.add(node)
   if node == destination:
    return hops
   neighbours = graph[node]
   for neighbour in neighbours:
    queue.append((neighbour, hops+1))

