public class Vehicle {

    // State
    private int currentSpeed;
    private int maxSpeed;
    private int fuelLevel;
    private int distanceTraveled;

    // Constructors
    public Vehicle() { 
        this.currentSpeed = 0;
        this.maxSpeed = 0;
        this.fuelLevel = 0;
        this.distanceTraveled = 0;
    }

    public Vehicle(int maxSpeed, int fuelLevel) {
        this.currentSpeed = 0;
        this.maxSpeed = maxSpeed;
        this.fuelLevel = fuelLevel;
        this.distanceTraveled = 0;
    }

    // Methods
    public void setCurrentSpeed(int speed) { 
        if (speed > this.maxSpeed || speed < 0) {
            System.out.println("Invalid Speed Value");
        } else { 
            this.currentSpeed = speed;
        }
    }

    public void setMaxSpeed(int maxSpeed) { 
        if (maxSpeed < this.currentSpeed) { 
            System.out.println("Invalid Max Speed Value");
        } else { 
            this.maxSpeed = maxSpeed;
        }
    }

    public void refuel(int fuelLevel) { 
        this.fuelLevel += fuelLevel;
    }

    public void drive(int distance) {
        if (this.currentSpeed == 0) {
            System.out.println("Can't Drive: Vehicle is not in motion");
        } else {
            this.distanceTraveled += distance;
            this.fuelLevel -= (distance / 2);
        }
    }

    public int getFuelLevel() { 
        return this.fuelLevel;
    }

    public int getDistanceTraveled() {
        return this.distanceTraveled;
    }
}

