public static List<String> getAnagrams(List<String> words) { 
    List<String> anagrams = new ArrayList<>();
    for (String word : words) {
        char[] wordChars = word.toCharArray(); 
        Arrays.sort(wordChars); 
        do { 
            anagrams.add(new String(wordChars)); 
        } while (getNextAnagramPermutation(wordChars));
    } 
    return anagrams; 
}

public static boolean getNextAnagramPermutation(char[] wordChars) { 
    int i = wordChars.length - 1; 
    while (i > 0 && wordChars[i] <= wordChars[i - 1]) {
        i--; 
    } 
    if (i <= 0) {
        return false; 
    }

    int j = wordChars.length - 1; 
    while (wordChars[j] <= wordChars[i-1]) {
        j--; 
    } 

    swap(wordChars, i - 1, j); 
    j=wordChars.length - 1; 
    while (i < j) {
        swap(wordChars, i, j); 
        i++;
        j--;
    } 

    return true; 
}

public static void swap(char[] wordChars, int i, int j) { 
    char temp = wordChars[i]; 
    wordChars[i] = wordChars[j]; 
    wordChars[j] = temp; 
}

