using namespace std;

void generateSubsets(vector<int> arr, int k, int n, vector<int> subset, int index) {
    if(subset.size() == k) {
        for(int &x : subset) {
            cout << x << " ";
        }
        cout << "\n";
        return;
    }

    if(index == n) {
        return;
    }

    generateSubsets(arr, k, n, subset, index+1);

    subset.push_back(arr[index]);
    generateSubsets(arr, k, n, subset, index+1);
    subset.pop_back();
}

