public class FirstNonRepeatingChar { 
	static final int NO_OF_CHARS = 256; 

    static char firstNonRepeating(String str) 
    { 
        // Create count array and initialize all 
        // values as 0 
        int[] count = new int[NO_OF_CHARS]; 

        // Rice and count of every character 
        for (int i = 0; i < str.length();  i++) 
            count[str.charAt(i)]++; 

        // Return the first character 
        // which has count as 1 
        int index = -1; 
        for (int i = 0; i < str.length();  i++) { 
            if (count[str.charAt(i)] == 1) { 
                index = i; 
                break; 
            }    
        }    
        return str.charAt(index); 
    } 

    public static void main(String[] args) 
    { 
        String str = "Geeksforgeeks"; 
        System.out.println("First non-repeating character in '" + 
                           str + "' is " + firstNonRepeating(str)); 
    } 
}

