public static void minHeapify(int[] arr) {
    for (int i = arr.length / 2 - 1; i >= 0; i--)
        minHeap(arr, arr.length, i);

    for (int i = arr.length - 1; i >= 0; i--){
        int temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;

        minHeap(arr, i, 0);
    }

}

public static void minHeap(int[] arr, int size, int index){
    int smallest = index;
    int left = 2 * index + 1;
    int right = 2 * index + 2;

    if (left < size && arr[left] < arr[smallest])
        smallest = left;

    if (right < size && arr[right] < arr[smallest])
        smallest = right;

    if (smallest != index) {
        int temp = arr[index];
        arr[index] = arr[smallest];
        arr[smallest] = temp;

        minHeap(arr, size, smallest);
    }
}

#include <iostream>
#include <vector>

template<typename K, typename V>
class HashTable {
private:
    std::vector<std::vector<std::pair<K, V>>> table;
    int size;

public:
    HashTable(int size=10) : size(size) {
        table.resize(size);
    }

    void put(K key, V value) {
        int hash = std::hash<K>()(key) % size;
        auto& bucket = table[hash];
        for (int i = 0; i < bucket.size(); i++) {
            if (bucket[i].first == key) {
                bucket[i].second = value;
                return;
            }
        }
        bucket.push_back({key, value});
    }

    V get(K key) {
        int hash = std::hash<K>()(key) % size;
        auto& bucket = table[hash];
        for (auto& kv : bucket) {
            if (kv.first == key) {
                return kv.second;
            }
        }
        // key not found
        return V();
    }
};

