public class DuplicateElements { 

  // Function to return the count of maximum 
  // repeating elements in an array 
  static int maxRepeating(int[] elements, int size, int k) 
  { 
    // Subtract 1 from all elements so that the elements 
    // become in range from 0 to k-1 
    for (int i=0; i<size; i++) 
      elements[i] = elements[i] - 1; 

    // Mark elements in the array as being visited by making 
    // elements’ value at its index negative. 
    // note that value become negative only once 
    for (int i=0; i<size; i++) 
    { 
      if (elements[elements[i] % k] >= 0) 
        elements[elements[i] % k] = -1 * elements[elements[i] % k] -1; 
    } 

    // Return maximum element 
    int max = 0; 
    for (int i=1; i<=k-1; i++) 
    { 
      if (elements[i]>0) 
        max = Math.max(max, elements[i]); 
    } 

    return max; 
  } 

  // Driver code 
  public static void main(String[] args) 
  { 
    int[] elements = {3, 5, 7, 3, 5, 8, 1}; 
    int size = elements.length; 
    int k=9; 

    System.out.print("The maximum count of duplicate elements is  "
                     + maxRepeating(elements, size, k)); 
  } 
}

