    public static String sanitize(String s) {
        String pattern = "<script>(.*?)</script>";
        String substring = "";
        Pattern p = Pattern.compile(pattern);
        Matcher m = p.matcher(s);
        if(m.find()) {
            substring=m.group(1);
            s= s.replace(substring, "");
        } 
        return s.replaceAll("<.+?>","");
    } 

