function findClassWithHighestGrade(students) {

    let maxGrade = 0;
    let maxGradeClass = 'N/A';

    const classHashtable = {};

    students.forEach(student => {
        const studentGrade = student.grade;
        const studentClass = student.class;

        if (!classHashtable[studentClass]) {
            classHashtable[studentClass] = [studentGrade];
        } else {
            classHashtable[studentClass].push(studentGrade);
        }
    });

    for (const className in classHashtable) {
        const grades = classHashtable[className];
        const classGradeAverage = grades.reduce((a, b) => a + b, 0) / grades.length;

        if (classGradeAverage > maxGrade) {
            maxGrade = classGradeAverage;
            maxGradeClass = className;
        }
    }

    console.log(`The class with highest grade is ${maxGradeClass} with an average grade of ${maxGrade}`);
 }

function rateLimiter(fn) {
 let lastCallTime = 0;
 let callCount = 0;

 return (...args) => {
 const now = Date.now();
 if (now - lastCallTime > 10000) {
 lastCallTime = now;
 callCount = 0;
 }

 callCount++;
 if (callCount > 3) {
 throw new Error('Rate limit exceeded');
 }

 return fn(...args);
 };
