public static String longestCommonSubsequence(String s1, String s2) {
  int m = s1.length();
  int n = s2.length();

  // Create a lookup table of size m+1, n+1
  int longestSequence[][] = new int[m+1][n+1];

  // Iterate over s1
  for (int i = 0; i < m; i++) {
    // Iterate over s2
    for (int j = 0; j < n; j++) {
      // If the strings are equal, the length of the longest common subsequence is one character longer than the previous character.
      if (s1.charAt(i) == s2.charAt(j)) {
        longestSequence[i+1][j+1] = longestSequence[i][j] + 1;
      }
      // Else the length of the longest common subsequence is the same as the longest common subsequence using the previous character of s1 or s2
      else {
        longestSequence[i+1][j+1] = Math.max(longestSequence[i+1][j], longestSequence[i][j+1]);
      }
    }
  }

  // Create a string to contain the longest common subsequence
  String result = "";
  // Iterate over s1 backwards
  for (int i = m; i >= 0; i--) {
    // Iterate over s2 backwards
    for (int j = n; j >= 0; j--) {
      // If the current characters do not match, the longest common character is non-existent
      if (s1.charAt(i) != s2.charAt(j)) {
        continue;
      }
      // Otherwise the current characters did match
      else {
        // Add the character to the longest common sequence
        result = s1.charAt(i) + result;
        // Move to the next characters in s1 and s2
        i--;
        j--;
      }
    }
  }
  // Return the string containing the longest common subsequence
  return result;
}

