def closest_prime(n, m):
    """
    Function to find the closest mth prime number to a given number n.
    """

    primes = []

    for i in range(n, n + m * 2):
        for j in range(2, i):
            if i % j == 0:
                break
        else:
            primes.append(i)

    if len(primes) >= m + 1:
        return primes[m]
    else:
        return -1

