def palindromic_substring(string):
    n = len(string)
    dp = [[False for _ in range(n)] for _ in range(n)]
    count = 0

    # one character is always palindromic
    for i in range(n):
        dp[i][i] = True
        count += 1

    for i in range(n-1):
        if string[i] == string[i+1]:
            dp[i][i+1] = True
            count += 1

    for k in range(3, n+1):
        for i in range(n-k+1):
            j = i+k-1
            if string[i] == string[j] and dp[i+1][j-1]:
                dp[i][j] = True
                count += 1

    return count

