void printPrime(int n) 
{ 
    // marked true if i is prime 
    bool prime[n+1]; 
    memset(prime, true, sizeof(prime)); 

    for (int p = 2; p*p <= n; p++) 
    { 
        // if prime[p] is not changed, then it is a prime 
        if (prime[p] == true) 
        { 
            // update all multiples of p 
            for (int i = p*2; i <= n; i += p) 
                prime[i] = false; 
        } 
    } 

    // Print all prime numbers 
    for (int p = 2; p <= n; p++) 
       if (prime[p]) 
          cout << p << " "; 
} 

