function encrypt($string, $key)
{
        $result = '';
        $key_len = strlen($key);
        for($i = 0; $i < strlen($string); $i++ ){
              $char = substr($string, $i, 1);
              $key_char = substr($key, ($i % $key_len) - 1,1);
