function topNWords(str, n) {
  const counts = {};

  // Create an array of words from the given string
  const words = str.split(' ');

  // Iterate through the array and store count
  for (let word of words) {
    if (counts[word]) {
      counts[word]++;
    } else {
      counts[word] = 1;
    }
  }

  // Use object.entries to traverse through the stored count
  const sortedEntries = Object.entries(counts).sort((a, b) => b[1] - a[1]);

  // Return the top n words
  return sortedEntries.slice(0, n).map((entry) => entry[0]);
}

