void breadthFirstSearch(vector<vector<int>> graph, int start) {
 int n = graph.size();
 vector<bool> visited(n, false);
 queue<int> q;
 q.push(start);

 while (!q.empty()) {
 int v = q.front();
 q.pop();
 visited[v] = true;

 for (int u : graph[v]) {
 if (!visited[u]) {
 q.push(u);
 }
 }
 }
}

