 if (str1.length !== str2.length) {
 return false;
 }
 let charCounter = {};
 for(let i = 0; i < str1.length; i++) {
 if (charCounter[str1[i]] === undefined) {
 charCounter[str1[i]] = 0;
 }
 charCounter[str1[i]]++;
 }
 for(let i = 0; i < str2.length; i++) {
 if (charCounter[str2[i]] === undefined) {
 return false;
 }
 charCounter[str2[i]]--;
 }
 for(let char in charCounter) {
 if (charCounter[char] !== 0) {
 return false;
 }
 }
