const toPigLatin = (sentence) => {
 let words = sentence.split(' ');
 let pigLatinWords = words.map(word => {
 let consonants = [];
 let firstVowelIndex = 0;

 while (firstVowelIndex < word.length && !/[aeiou]/.test(word[firstVowelIndex])) {
 consonants.push(word[firstVowelIndex]);
 firstVowelIndex++;
}

 let suffix = 'way';
 if (consonants.length > 0) {
 suffix = 'ay';
 consonants.push('a');
}

 const pigLatinWord = word.slice(firstVowelIndex) + consonants.join('') + suffix;
 return pigLatinWord;
 });

 return pigLatinWords.join(' ');
}

