void array_shuffle(int array1[], int array2[], int array_size)
{
    int temp, random;

    srand((unsigned int)time(NULL));

    for (int i = 0; i < array_size; i++)
    {
        // Generate a random number from 0 to array_size - 1
        random = rand() % array_size;

        // Swap elements at positions i and random
        temp = array1[i]; 
        array1[i] = array1[random];
        array1[random] = temp;

        // Swap elements in array2 as well 
        temp = array2[i];
        array2[i] = array2[random];
        array2[random] = temp;
    }
}

