Copy-on-write is an optimization strategy used in computer programming, where a copy of a data structure or object is made only if a write operation has been performed on the data. It is most commonly used in object-oriented programming, although it can also be used in procedural programming. The idea behind copy-on-write is that if the data structure or object has not been changed, therefore there is no need to make a copy.

A C++ example of copy-on-write is given below:

#include < potential.h>
#include < shared_ptr.h>

struct Potential {
    // data here...
};

template < typename T >
class CopyOnWrite {
private:
    // keep a shared pointer to the data
    // when the object is copied, only the reference is copied
    std::shared_ptr<T> data;

public:
    // constructor
    CopyOnWrite(std::shared_ptr<T> d) : data(d) {}

    // called when a write operation is performed
    // a new copy of the object is created
    void write() {
        data.reset(new T(*data)); 
    }

    // methods for reading data
    void read() {
        // .. read data here
    } 
};

int main(int argc, char* argv[]) {
    // create a shared pointer
    // this will be the data that is copied
    auto potential = std::make_shared<Potential>();

    // create a CopyOnWrite object
    // this will keep a reference to the shared pointer
    CopyOnWrite<Potential> cow(potential);

    // perform write on the copy-on-write object
    cow.write();

    // the potential object has been copied
    cow.read();

    return 0;
}

