def summarize_text(text):
    # Split the text into sentences
    sentences = text.split('.')

    # Get frequency of each word in the text
    word_count = {}
    for sentence in sentences:
        words = sentence.split(' ')
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1

    # Get the most frequent words
    frequent_words = sorted(word_count, key=word_count.get, reverse=True)[:5] 

    # Find the sentences that contain the most frequent words
    important_sentences = []
    for sentence in sentences:
        if any(word in sentence for word in frequent_words):
            important_sentences.append(sentence)

    # Create summary
    summary = ' '.join(important_sentences)
    return summary

