// Function to generate the nth Fibonacci number 
int fibonacci(int n) 
{ 
    // Initialise first two Fibonacci numbers 
    int f1 = 0, f2 = 1, next; 

    // Return 0 if value of n is 0 
    if (n == 0) 
        return 0; 

    for (int i = 2; i <= n; i++) { 
        next = f1 + f2; 
        f1 = f2; 
        f2 = next; 
    } 
    return f2; 
} 

