function checkCardNumber(number) {
  var sum = 0;
  var shouldDouble = false;
  for (var i = number.length - 1; i >= 0; i--) {
    var digit = parseInt(number.charAt(i));
    if (shouldDouble) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }
    sum += digit;
    shouldDouble = !shouldDouble;
  }
  return (sum % 10) == 0;
}

