vector<int> merge(vector<int> arr1, vector<int> arr2) 
{ 
    int m = arr1.size();
    int n = arr2.size();
    int i = 0, j = 0, k = 0;
    vector<int> mergedArr(m + n); 

    while (i < m && j < n) { 
        if (arr1[i] < arr2[j]) { 
            mergedArr[k] = arr1[i]; 
            i++; 
        } else { 
            mergedArr[k] = arr2[j];
            j++; 
        } 
        k++; 
    } 

    while (i < m) { 
        mergedArr[k] = arr1[i]; 
        i++; 
        k++; 
    } 

    while (j < n) { 
        mergedArr[k] = arr2[j]; 
        j++; 
        k++; 
    } 

    return mergedArr; 
} 

