public class Stack {

    private int top;
    private int[] stack; 
    private int size; 

    // constructor
    public Stack(int size) {
        this.size = size;
        this.stack = new int[size];
        this.top = -1;
    }

    public boolean isFull() {
        return (top == size - 1);
    }

    public boolean isEmpty() {
        return (top == -1);    
    }

    public void push(int x) {
        if (isFull()) {
            System.out.println("Stack is full!");
        } else {
            stack[++top] = x;
        }
    }

    public int pop() {
        if (isEmpty()) {
            return -1;
        } else {
            return stack[top--];
        }
    }
}

