function permutations(str) {
 let permutationsArray = [];
 // if the string is one character, it is already a permutation
 if (str.length === 1) {
 permutationsArray.push(str);
 return permutationsArray;
 }

 // loop through the string
 for (let i = 0; i < str.length; i++) {
 // get the current character
 let currentChar = str[i];
 // get all the characters except the current one
 let remainingChars = str.substring(0, i) + str.substring(i + 1);
 // get all the permutations of the remaining characters
 let remainingCharPermutations = permutations(remainingChars);

 // iterate through all the permutations and append the current
 // char to them
 for (let j = 0; j < remainingCharPermutations.length; j++) {
 permutationsArray.push(currentChar + remainingCharPermutations[j]);
 }
 }

 return permutationsArray;
}

