function AP_sum(start, end, n) { 
    // Sum of an arithmetic progression is: n/2* (2*a+(n-1)*d). 
    // Here a is the first element of the sequence, 
    // and d is the common difference between two consecutive elements 

    d = (end - start) / (n-1); 
    sum = (n / 2) * (2 * start + (n - 1) * d); 

    return sum; 
} 

