def merge(leftArray, rightArray):
    sortedArray = []

    while len(leftArray) > 0 and len(rightArray) > 0:
        if leftArray[0] < rightArray[0]:
            sortedArray.append(leftArray[0])
            leftArray.pop(0)
        else:
            sortedArray.append(rightArray[0])
            rightArray.pop(0)

    if len(leftArray) > 0:
        sortedArray += leftArray
    elif len(rightArray) > 0:
        sortedArray += rightArray

    return sortedArray


def merge_sort(array):
    if len(array) == 1:
        return array
    else:
        middle = int(len(array) / 2)
        leftArray = array[:middle]
        rightArray = array[middle:]

        leftArray = merge_sort(leftArray)
        rightArray = merge_sort(rightArray)

        return merge(leftArray, rightArray)

