class InvertedIndex { 

 constructor() {
  this.index = {};
 }

 // Add a document to be indexed 
 addDocument(document, index) 
 { 
  // Each document has a list of terms 
  let terms = document.split(" "); 

  // For each term in the document 
  for (let term of terms) { 
   // If the term doesn't exist in the index
   if (term in this.index == false) 
    this.index[term] = []; 

   // Add the document to the list of 
   // documents associated with the term
   this.index[term].push(document);
  }

  console.log(this.index);
 }

 // Return all documents that contains the term 
 search(term) 
 {
  // Return an empty list, if the term 
  // doesn't exist in the index
  if (term in this.index == false) 
   return []; 

  else
   // Otherwise, return the list of documents
   // associated with the term 
   return this.index[term];
 } 
} 

