sort <- function(arr){
  n <- length(arr) 
  # outer loop to control number of passes
  for (i in 1:(n-1)){ 
    # inner loop to control number of comparisons
    for (j in 1:(n-i)){ 
      # compare and swap if value is lesser
      if (arr[j] > arr[j+1]) {
        t <- arr[j] 
        arr[j] <- arr[j+1]
        arr[j+1] <- t 
      } 
    } 
  } 
  # return sorted array
  arr
}

