def median_of_two_sorted_arrays(arr1, arr2):
 n1 = len(arr1) 
 n2 = len(arr2) 

 if n1 < n2: 
  return median_of_two_sorted_arrays(arr2, arr1) 

 lo = 0
 hi = n2 * 2

 while lo <= hi: 
  mid2 = (lo + hi) // 2
  mid1 = n1 + n2 - mid2 

  L1 = arr1[(mid1 - 1)//2] if mid1 != 0 else float('-inf') 
