function convertBase($number, $base1, $base2) {
    $result = 0;
    $power = 1;

    // Convert given number to base 10 number
    $value = 0;
    for ($i = strlen($number) - 1; $i >= 0; $i--)
    {
        if (ctype_digit($number[$i]))
            $value += $number[$i] * pow($base1, $i);
        else
            $value += ord(strtoupper($number[$i])) - 55
                    * pow($base1, $i);
    }

    // Convert base 10 number to given base
    while ($value > 0)
    {
        $rem = $value % $base2;
        $value = (int)($value / $base2);
        $result += $rem * $power;
        $power = $power * 10;
    }

    return $result;
}

