def partition(head, x): 
    beforeStart = None
    beforeEnd = None
    afterStart = None
    afterEnd = None

    while head is not None: 
        next = head.next
        head.next = None
        if head.data < x: 
            if beforeStart is None: 
                beforeStart = head
                beforeEnd = beforeStart
            else: 
                beforeEnd.next = head 
                beforeEnd = head 
        else: 
            if afterStart is None: 
                afterStart = head
                afterEnd = afterStart
            else: 
                afterEnd.next = head
                afterEnd = head

        head = next

    if beforeStart is None: 
        return afterStart

    beforeEnd.next = afterStart
    return beforeStart

