public static string CapitalizeFirstLetters(string input)
{
    string output = "";
    bool wasPreviousLetterCapitalized = false;
    for (int i = 0; i < input.Length; i++)
    {
        if (!char.IsLetter(input[i]))
        {
            wasPreviousLetterCapitalized = true;
            output += input[i];
        }
        else if (i == 0 || wasPreviousLetterCapitalized)
        {
            output += char.ToUpper(input[i]);
            wasPreviousLetterCapitalized = false;
        }
        else
        {
            output += char.ToLower(input[i]);
        }
    }
    return output;
}

