def levenshtein_distance(str1, str2): 
    m = len(str1) 
    n = len(str2)

    dp = [[0 for x in range(n+1)] for x in range(m+1)]

    for i in range(m + 1): 
        for j in range(n + 1): 
            if i == 0: 
                dp[i][j] = j   
            elif j == 0: 
                dp[i][j] = i    
            elif str1[i-1] == str2[j-1]: 
                dp[i][j] = dp[i-1][j-1] 
            else: 
                dp[i][j] = 1 + min(dp[i][j-1],     
                                   dp[i-1][j],      
                                   dp[i-1][j-1])       
    return dp[m][n]

def sum2dArray(arr, n, m): 
    sum = 0
    # Iterating rows 
    for i in range(n): 
        # Iterating columns 
        for j in range(m): 
            sum += arr[i][j]  
    return sum

def longestCommonSubstring(str1, str2): 
    n = len(str1) 
    m = len(str2) 

    result = 0 # to store the length of LCS 
    dp = [[0] * (m + 1) for _ in range(n + 1)] 

    for i in range(1, n + 1): 
        for j in range(1, m + 1): 
            if str1[i-1] == str2[j-1]: 
                dp[i][j] = dp[i-1][j-1] + 1
                result = max(result, dp[i][j]) 
            else: 
                dp[i][j] = 0
    return result

