def num_subsets_with_k(S, k):
    """Calculates the number of subsets with exactly k elements in a given set"""
    # base case
    if k == 0:
        return 1

    # recursion
    n = len(S)
    if n < k:
        return 0
    elif n == k:
        return 1
    else:
        return num_subsets_with_k(S[:-1], k-1) + num_subsets_with_k(S[:-1], k)

