def anagrams(s1, s2):
    s1_chars = [char for char in s1]
    s2_chars = [char for char in s2]

    if len(s1_chars) != len(s2_chars):
        return False

    s1_char_counts = {}
    for char in s1_chars:
        if char in s1_char_counts:
            s1_char_counts[char] += 1
        else:
            s1_char_counts[char] = 1

    s2_char_counts = {}
    for char in s2_chars:
        if char in s2_char_counts:
            s2_char_counts[char] += 1
        else:
            s2_char_counts[char] = 1

    if s1_char_counts != s2_char_counts:
        return False

    return True

