def binary_search(array, target):
  low = 0
  high = len(array) - 1
  while low <= high:
    mid = (low + high) // 2
    middle_element = array[mid]
    if middle_element == target:
      return mid
    elif middle_element < target:
      low = mid + 1
    else:
      high = mid - 1
  return -1

function binaryToDecimal(binaryNum) {
    let decimalNum = 0;
    let multiplier = 1; 
    let binaryNumLength = binaryNum.length;

    // Iterate over the binary number 
    for (let i = binaryNumLength ; i >= 0; i--) 
    {
        // if the binary number is 1, add it to decimal
        if (binaryNum[i] == 1) {
            decimalNum += multiplier;
        }
        // Increase multiplier every loop 
        multiplier *= 2;
    }
    return decimalNum;
}

