import java.util.Map;
import java.util.HashMap;

public class GiniIndex {
 public static void main(String[] args) {

 // Example dataset of age and income
 Map<Integer, Integer> dataset = new HashMap<>();
 dataset.put(25, 20000);
 dataset.put(32, 10000);
 dataset.put(36, 80000);
 dataset.put(40, 60000);
 dataset.put(18, 70000);

 int n = dataset.size();
 double sum = 0;
 for (int age : dataset.keySet()) {
 sum += dataset.get(age);
 }
 double mean = sum / n;

 double numerator = 0;
 double denominator = 0;
 for (int age : dataset.keySet()) {
 numerator += Math.pow(dataset.get(age) - mean, 2);
 denominator += dataset.get(age);
 }
 double gini = numerator / (2 * Math.pow(denominator, 2));

 System.out.println("Gini Index: " + gini);
 }
}

