class TreeNode {
  int data; 
  TreeNode left, right; 

  TreeNode(int item) {
    data = item; 
    left = right = null; 
  } 
}

class MaxSum { 

  // Recursive function to get max sum 
  int maxSum(TreeNode node) { 
    if (node == null) 
      return 0; 

    // get max sum of left, right subtrees and node itself 
    int lMax = maxSum(node.left); 
    int rMax = maxSum(node.right); 
    int nodeMax = node.data; 

    // get the max of left and right subtree + node itself and 
    // compare it with left and right subtree and assign the 
    // appropriate value to lMax and rMax 
    if (lMax > 0) 
      nodeMax += lMax; 
    if (rMax > 0) 
      nodeMax += rMax; 
    if (lMax > rMax) 
      rMax = lMax; 
    if (rMax > lMax) 
      lMax = rMax; 

    // return the max of left, right and the final value 
    return Math.max(nodeMax, lMax); 
  } 

  public static void main(String[] args) {

    TreeNode root = new TreeNode(1); 
    root.left = new TreeNode(2); 
    root.right = new TreeNode(3); 
    root.left.left = new TreeNode(4); 
    root.left.right = new TreeNode(5);
    root.right.left = new TreeNode(6); 
    root.right.right = new TreeNode(7);

    MaxSum maxSum = new MaxSum(); 
    System.out.println(maxSum.maxSum(root)); 
  } 
}

