# list of all possible permutations of [1, 2, 3]
def get_permutations(nums):
    if len(nums) == 0:
        return []

    # base case 
    if len(nums) == 1:
        return [nums]

    permutation_list = []

    for i in range(len(nums)):
        curr_num = nums[i]
        # generate list of permutations of all other numbers
        rest_permutations = get_permutations(nums[0:i] + nums[i+1:])

        # attach current number to each permutation of other numbers
        for perm in rest_permutations:
            permutation_list.append([curr_num] + perm)

    return permutation_list

