def get_mode(numbers):
    counts = {} 
    for number in numbers: 
        if number in counts: 
            counts[number] += 1
        else:
            counts[number] = 1
    plist = list(counts.items())
    max_f = 0
    mode = 0
    for kv in plist:
        if max_f < kv[1]:
            max_f = kv[1]
            mode = kv[0]
    if max_f == 1:
        mode = None
    return mode

