def merge_lists(list1, list2): 
    # initialize the merged list with empty list 
    merged_list = [] 

    # consider each element in the list in a loop to compare 
    while len(list1) > 0 and len(list2) > 0: 
        if list1[0] > list2[0]: 
            merged_list.append(list2[0]) 
            list2.pop(0) 
        else: 
            merged_list.append(list1[0]) 
            list1.pop(0) 

    # loop through the remaining elements in list1 and append to merged_list 
    for i in list1: 
        merged_list.append(i) 

    # loop through the remaining elements in list2 and append to merged_list 
    for i in list2: 
        merged_list.append(i) 

    return merged_list

