#define N 4
#define INF INT_MAX 

int minDistance(int graph[][N]) 
{ 
	int dist[N];  

	for (int i = 0; i < N; i++) 
		dist[i] = INF; 
	dist[0] = 0; 

	for (int i = 0; i < N-1; i++) 
	{ 
		for (int j = 0; j < N; j++) 
		{ 
			for (int k = 0; k < N; k++) 
			{ 
				if (dist[k] > dist[j] + graph[j][k]) 
					dist[k] = dist[j] + graph[j][k]; 
			} 
		} 
	} 

	return dist[N-1]; 
} 

