function bottomUpMergeSort($items) {
    $length = count($items);
    $sizedBlock = 1;
    $temp = array();
    while ($sizedBlock < $length) {
        $left  = 0;
        while ($left + $sizedBlock < $length) {
            $right = $left + $sizedBlock * 2;
            $end = ($right > $length) ? $length : $right;
            bottomUpMerge($items, $left, $left + $sizedBlock, $end, $temp);
            $left = $right;
        }
        $sizedBlock *= 2;
    }
    return $items;
}

function bottomUpMerge($items, $startLeft, $startRight, $end, &$temp) {
    $leftEnd  = $startRight - 1;
    $tmpPos    = $startLeft;
    $dataSize  = $end - $startLeft + 1;

    while ($startLeft <= $leftEnd && $startRight <= $end) {
        if ($items[$startLeft] <= $items[$startRight]) {
            $temp[$tmpPos] = $items[$startLeft];
            $startLeft++;
        } else {
            $temp[$tmpPos] = $items[$startRight];
            $startRight++;
        }
        $tmpPos++;
    }
    while ($startLeft <= $leftEnd) {
        $temp[$tmpPos] = $items[$startLeft];
        $startLeft++;
        $tmpPos++;
    }

    while ($startRight <= $end) {
        $temp[$tmpPos] = $items[$startRight];
        $startRight++;
        $tmpPos++;
    }

    for ($i = 0; $i < $dataSize; $i++) {
        $items[$end] = $temp[$end];
        $end--;
    }
}

