def max_knapsack_value(weights, values, max_weight):
    dp = [[0 for x in range(max_weight + 1)] for x in range(len(weights) + 1)]

    # Calculate maximum knapsack value
    for i in range(1, len(weights) + 1):
        for w in range(1, max_weight + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(values[i-1] + dp[i-1][w-weights[i-1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i-1][w]

    return dp[-1][-1]

