function dataValidation(data) {
  // Check if data type is an array.
  if (!Array.isArray(data)) {
    return false;
  }

  // Check for empty array.
  if (data.length === 0) {
    return false;
  }

  // Check if array only has strings.
  if (!data.every(entry => typeof entry === "string")) {
