def findWays(matrix): 

    # If the starting point is blocked, return 0
    if (matrix[0][0] == -1): 
        return 0

    # Create an array to store results
    # of subproblems 
    dp = [[0 for i in range(3)]  
              for j in range(3)] 

    # Initialize starting point 
    dp[0][0] = 1

    # filling first row
    for i in range(1, 3): 
        dp[i][0] = dp[i - 1][0] if matrix[i][0] != -1 else 0; 

    # filling first column 
    for j in range(1, 3): 
        dp[0][j] = dp[0][j - 1] if matrix[0][j] != -1 else 0; 

    # filling up the rest according 
    # to the formula 
    for i in range(1, 3):  
        for j in range(1, 3):  
            if (matrix[i][j] != -1): 
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1] 
            else: 
                dp[i][j] = 0
    return dp[2][2]

