public void mergeKArrays(int[][] arrays) {
    PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);

    // put first elements of all the arrays in the queue
    for (int[] arr : arrays) {
        minHeap.add(arr);
    }

    while (!minHeap.isEmpty()) {
        int[] element = minHeap.poll();
        System.out.print(element[0] + " ");

        if (element[1] < arrays[element[2]].length - 1) {
            element[0] = arrays[element[2]][element[1] + 1];
            element[1] += 1;
            minHeap.add(element);
        }
    }
}

