    n2 = len(str2) 

    # If lengths are not same, then strings are not anagrams 
    if n1 != n2: 
        return False

    # Sort both strings 
    str1 = sorted(str1) 
    str2 = sorted(str2) 

    # Compare sorted strings 
    for i in range(0, n1): 
