import { Board, Piece } from './gameboard';

class GameDriver {
 constructor(board: Board) {
 this.board = board;
 }

 // Search for a piece on the board
 search(x: number, y: number): Piece {
 if (x < 0 || x > this.board.width || 
 y < 0 || y > this.board.height) {
 return null;
 }
 return this.board.grid[x][y];
 }

 // Select a piece
 select(piece: Piece): boolean {
 if (piece == null || piece.isSelected) {
 return false;
 }
 piece.isSelected = true;
 return true;
 }

 // Make a move
 move(piece: Piece, x: number, y: number): boolean {
 if (piece == null || piece.isSelected == false) {
 return false;
 }

 let fromX = piece.x;
 let fromY = piece.y;
 if (x < 0 || x > this.board.width || 
 y < 0 || y > this.board.height || 
 this.board.grid[x][y] != null) {
 return false;
 }

 this.board.grid[x][y] = piece;
 this.board.grid[fromX][fromY] = null;
 piece.x = x;
 piece.y = y;
 return true;
 }
}

