// Function to convert a given integer to its binary representation
string convertToBinary(int n) { 
    string binary = "";
    // Dividing repeatedly until the 
    // whole number becomes 0
    for (int i=31; i>=0; i--) { 
        // Checking remainder by AND bit operator
        int k = n >> i;
        if (k & 1) { 
            binary += "1"; 
        } else {
            binary += "0";
        }
    } 
    return binary; 
}

