def search(board, word): 
	# construct directions array (4 directions)
	directions = zip((0, 1, 0, -1), (1, 0, -1, 0))

	# loop over board to traverse every cell
	for row in range(len(board)):
		for col in range(len(board[0])):

			# find the starting cell
			if board[row][col] == word[0]:

				# check for all directions
				for (dr, dc) in directions:

					vs = 1 # number of matches

					r = row
					c = col
					while 0 <= r < len(board) and 0 <= c < len(board[0]):

						# if cell doesn't match
						if board[r][c] != word[vs]:
							break

						# if full word is matched
						if vs == len(word)-1:
							return True

						# keep moving and increase number of matches
						vs += 1
						r += dr
						c += dc

	# if no match is found
	return False

