public class SwapSort {

  public static int minimumSwap(int[] arr) {
    int swapCount = 0;

    if (arr == null || arr.length <= 1) {
      return swapCount;
    }

    Map<Integer, Integer> valueIndexMap = new HashMap<>();

    for (int i = 0; i < arr.length; i++) {
      valueIndexMap.put(arr[i], i);
    }

    for (int i = 0; i < arr.length; i++) {
      if (arr[i] != i + 1) {
        int valueAtTargetIndex = arr[i];
        int targetIndex = valueIndexMap.get(i + 1);
        arr[targetIndex] = valueAtTargetIndex;
        arr[i] = i + 1;
        valueIndexMap.put(valueAtTargetIndex, targetIndex);
        swapCount++;
      }
    }

    return swapCount;
  }

  public static void main(String[] args) {
    int[] arr = {2,1,3,4,7,6,5};
    System.out.println(minimumSwap(arr)); // Outputs 3
  } 

}

