 super(props);
 this.state = {
  items: [],
  total: 0
 };
 }

 addItem(item) {
  const { items } = this.state;
  const updatedItems = items.concat(item);
  this.setState({
   items: updatedItems
  });
 }

 removeItem(index) {
  const { items } = this.state;
  const updatedItems = items.filter((item, i) => i !== index);
  this.setState({
   items: updatedItems
  });
 }

 handleSubmit(e) {
  e.preventDefault();
  this.props.submitOrder(this.state.items);
  this.setState({
   items: [],
   total: 0
  });
