const mergeSortedArrays = (arr1, arr2) => {
  // Create an empty array to store sorted merged array
  const mergedArr = [];

  let index1 = 0;
  let index2 = 0;
  let current = 0;

  // While there are elements in both arrays 
  while (current < (arr1.length + arr2.length)) {
    // Compare elements at current indices in each array
    const isArr1Empty = index1 >= arr1.length;
    const isArr2Empty = index2 >= arr2.length;

    // If arr2 is empty or value at index1 is less than value at index2
    if (isArr1Empty || (arr1[index1] <= arr2[index2] && !isArr2Empty)) {
      mergedArr[current] = arr1[index1];
      index1++;
    } else {
      mergedArr[current] = arr2[index2];
      index2++;
    }

    current++;
  }

  return mergedArr;
}

