import random

class Store(object):
 def __init__(self, products):
  self.products = products
  self.locations = self.calculate_locations()

 # Calculate initial location placements
 def calculate_locations(self):
  locations = {}
  for product in self.products:
   loc = random.choice(range(0, len(self.products)))
   locations[product] = loc

  return locations

 # Calculate the optimal neighborhoods
 def calculate_neighborhoods(self):
  neighborhoods = {}
  for product in self.products:
   neighbors = []
   for compare in self.products:
    if compare != product and self.locations[compare] == self.locations[product]:
     neighbors.append(compare)
   neighborhoods[product] = neighbors

  return neighborhoods

 # Optimize product placement
 def optimize(self):
  for product in self.products:
   # Calculate penalty for current location
   current_penalty = self.calculate_penalty(product, self.locations[product])

   # Try to move the product to find an optimal location
   for loc in range(0, len(self.products)):
    move_penalty = self.calculate_penalty(product, loc)
    if move_penalty < current_penalty:
     self.locations[product] = loc
     current_penalty = move_penalty

# Calculate penalty for a particular product location
def calculate_penalty(self, product, loc):
 penalty = 0
 for neighbor in self.neighborhoods[product]:
  if self.locations[neighbor] == loc:
   penalty += 1
 return penalty

