public static int findSmallestDifference(int[] arr) {
	int minDiff = Integer.MAX_VALUE;

	for (int i=0; i<arr.length-1; i++) {
		for (int j=i+1; j<arr.length; j++) {
			int diff = Math.abs(arr[i] - arr[j]);
			if (diff < minDiff) {
				minDiff = diff;
			}
		}
	}

	return minDiff;
}

