def is_permutation(str1, str2):
  # Check if the length of both strings is equal
  if len(str1) != len(str2):
    return False

  # Initialize an empty dictionary
  chr_counts = {}

  # Iterate over both strings and populate the dictionary
  for c in str1:
    if c in chr_counts:
      chr_counts[c] += 1
    else:
      chr_counts[c] = 1

  for c in str2:
    if c in chr_counts:
      chr_counts[c] -= 1
    else:
      return False

  for key in chr_counts:
    if chr_counts[key] != 0:
      return False

  return True


