function searchElement(arr, num) {
  let startIndex = 0;
  let endIndex = arr.length - 1;
  while (startIndex <= endIndex) {
    let midIndex = Math.floor((startIndex + endIndex) / 2);
    if (arr[midIndex] === num) {
      return midIndex;
    } else if (arr[midIndex] < num) {
      startIndex = midIndex + 1;
    } else {
      endIndex = midIndex - 1;
    }
  }
  return -1;
}

