def most_frequent_char(string): 
    # Initialize a dictionary to store character counts 
    char_counts = {} 

    # Iterate through the characters in the string 
    for char in string:
        # Check if character is already in the dictionary 
        if char in char_counts: 
            # Increment the count 
            char_counts[char] += 1 
        else: 
            # Put the character in the dictionary and set the count to 1 
            char_counts[char] = 1 

    # Sort the dictionary by value 
    sorted_counts = sorted(char_counts.items(), key=lambda kv: kv[1], reverse=True)

    # return the result 
    return sorted_counts[0][0]

class HashTable:
    def __init__(self):
        self.table = {}

    def put(self, key, value):
        # Get the hash for the given key
        hash_value = self._hash(key)
        # If the hash value is not in the table, create an empty list
        if hash_value not in self.table:
            self.table[hash_value] = []
        # Append the value to the list
        self.table[hash_value].append((key, value))

    def get(self, key):
        # Get the hash for the given key
        hash_value = self._hash(key)
        # If the hash is not in the table, return None
        if hash_value not in self.table:
            return None
        # Search the list of (key, value) pairs for a matching key
        for k, v in self.table[hash_value]:
            if key == k:
                return v
        # If no matching key is found, return None
        return None

    def _hash(self, key):
        # Generate a simple hash of the given key
        return hash(key) % 1000

