def min_heapify(arr, n, i): 
 largest = i
 l = 2 * i + 1
 r = 2 * i + 2

 if l < n and arr[i] > arr[l]: 
    largest = l 

 if r < n and arr[largest] > arr[r]: 
    largest = r 

 if largest != i: 
    arr[i], arr[largest] = arr[largest], arr[i] 
    min_heapify(arr, n, largest) 


