def tile_room(room):
    block_types = [1, 2]
    solutions = 0
    def place(row, col):
        # Place a block
        nonlocal solutions
        if col == 3:
            solutions += 1
            return
        # Try the next block type
        for block_type in block_types:
            if block_type + col <= 3 and valid(row, col, block_type):
                board[row][col] = block_type
                # Move to the next column
                if col + block_type == 3:
                    place(row + 1, 0)
                else:
                    place(row, col + block_type)
                # Unplace the block
                board[row][col] = 0
    # Check if the solution is valid
    def valid(row, col, block_type):
        if board[row][col] != 0:
            return False
        if board[row][col + block_type - 1] != 0:
            return False
        if row + 1 != 3 and board[row + 1][col] != 0:
            return False
        if row + 1 != 3 and board[row + 1][col + block_type - 1] != 0:
            return False
        return True
    # Initialize board
    board = [[0, 0, 0], [0, 0, 0], [0, 0, 0]]
    place(0, 0)
    return solutions

