bool isPrime(int n) {
 // A number can only be prime if it is greater than 1
 if (n <= 1)
  return false;

 // Keep track of the sqrt of the number for performance
 int sqrtN = ceil(sqrt(n));

 // Test if the number is divisible by any number between 2 and sqrtN
 for (int i = 2; i <= sqrtN; i++) {
  if (n % i == 0)
   return false;
 }

 return true;
}

