char *replaceString(const char *s, const char *oldWord, 
                     const char *newWord) 
{ 
    char *result; 
    int i, cnt = 0; 
    int newWlen = strlen(newWord); 
    int oldWlen = strlen(oldWord); 

    for (i = 0; s[i] != '\0'; i++) { 
        if (strstr(&s[i], oldWord) == &s[i]) { 
            cnt++; 

            i += oldWlen - 1; 
        } 
    } 

    result = (char *)malloc(i + cnt * (newWlen - oldWlen) + 1); 
    i = 0; 
    while (*s) { 
        if (strstr(s, oldWord) == s) { 
            strcpy(&result[i], newWord); 
            i += newWlen; 
            s += oldWlen; 
        } else
            result[i++] = *s++; 
    } 

    result[i] = '\0'; 
    return result; 
} 

