function RequestHandler(sessionId) {
 this.sessionClient = new dialogflow.SessionsClient();
 this.sessionId = sessionId;
}

RequestHandler.prototype.handleDialogFlowRequest = function(queryInput) {
 return new Promise((resolve, reject) => {
  const sessionPath = this.sessionClient.sessionPath(
   process.env.GCLOUD_PROJECT,
   this.sessionId
  );

  // Send the query to the dialogflow session
  const request = {
   session: sessionPath,
   queryInput
  };
  this.sessionClient
   .detectIntent(request)
   .then(responses => {
    const result = responses[0].queryResult;
    resolve(result);
   })
   .catch(err => {
    reject();
   });
 });
};

