def is_one_edit_away(string1, string2):
    """
    This function determines if two strings are one edit away,
    where an edit is defined as the replacement, insertion, or deletion 
    of a single character.
    """

    # get the lengths of the strings
    len1 = len(string1)
    len2 = len(string2)

    # if the difference in lengths between the strings is greater than 1,
    # they cannot possible be one edit away
    if abs(len1 - len2) > 1:
        return False

    # check if the strings differ by one character
    if len1 == len2:
        edit_found = False
        for i in range(len1):
            if string1[i] != string2[i]:
                if edit_found:
                    return False
                edit_found = True
        return True
    # if the strings differ by one character    
    elif len1 - len2 == 1:
        # check if the shorter string is a substring of the longer string
        for i in range(len2):
            if string2[i] != string1[i+1]:
                return False
        return True
    elif len2 - len1 == 1:
        # check if the shorter string is a substring of the longer string
        for i in range(len1):
            if string1[i] != string2[i+1]:
                return False
        return True

