variance <- function(x) { 

    # calculate the mean of given vector 
    mean <- mean(x) 

    # calculate the sum of square of difference 
    # between each element of vector and mean. 
    sum <- 0  
    for (i in 1:length(x)) { 
        sum <- sum + (x[i] - mean)^2 
    } 

    # return the variance 
    return(sum / length(x)) 
}

