import java.util.HashMap;

public class FindSecondMostFreq { 

    // function to find the second most frequent item 
    public static int secondMostFreq(int[] arr) { 

        // Hashmap to store the count of each element 
        HashMap<Integer, Integer> hp = new HashMap<Integer, Integer>(); 

        // Traverse the array and update the count for each element 
        for (int i = 0; i < arr.length; i++) { 

            // If element is already present, 
            // increment its count 
            if (hp.containsKey(arr[i])) { 

                int c = hp.get(arr[i]); 
                hp.put(arr[i], c + 1); 
            } 

            // Else, insert the element with count 1 
            else { 
                hp.put(arr[i], 1); 
            } 
        } 

        // start with maximum frequency 
        int mostFreq = 0, secMostFreq = 0; 

        for (int i : hp.keySet()) { // traverse through all items 

            if (hp.get(i) > mostFreq) { // update mostFreq 

                secMostFreq = mostFreq; 
                mostFreq = hp.get(i); 
            } 
            else if (hp.get(i) > secMostFreq && 
                    hp.get(i) < mostFreq) { // update second  
                                            // mostFreq 
                secMostFreq = hp.get(i); 
            } 
        } 

        return secMostFreq; 
    } 

    public static void main(String[] args) { 
        int arr[] = { 1, 2, 2, 3, 3, 3 };     
        int c = secondMostFreq(arr); 
        if (c == 0) { 
            System.out.println("No Second Highest Frequency"); 
        } 
        else { 
            System.out.println("Second Highest Frequency = " + c); 
        } 
    } 
}

