def solvePuzzle(puzzle):
    visited = {}
    queue = deque([puzzle]) 
    while queue:
    current = queue.pop() 
    if current == '123456789ABCDEF': 
        return current 
    if current in visited: 
        continue 
    visited[current] = True
    for next in adjacent(puzzle): 
        queue.append(next)
    return None

