def check_sudoku(puzzle):
    # matrix should be 9x9
    N = len(puzzle)
    if N != 9:
        return False 

    # check rows and columns
    for i in range(0, N):
        row = [puzzle[i][j] for j in range(0,N)]
        col = [puzzle[j][i] for j in range(0,N)]
        # check to see if 1-9 occur exactly once in each row
        row_count = [0]*9
        col_count = [0]*9
        for x in row:
            if x == 0: 
                continue
            row_count[x-1] += 1
            if row_count[x-1] > 1:
                return False
        for y in col:
            if y == 0: 
                continue
            col_count[y-1] += 1
            if col_count[y-1] > 1:
                return False
    # check the 3x3 sub sections of the puzzle
    for x in range(0,N,3):
        for y in range(0, N, 3):
            sub = [puzzle[i][j] for i in range(x,x+3) for j in range(y,y+3)]
            # check to see if 1-9 occur exactly once
            sub_count = [0]*9
            for z in sub:
                if z == 0:
                    continue
                sub_count[z-1] += 1
                if sub_count[z-1] > 1:
                    return False
    return True

