func mergeSortedArray(arr1 []int, arr2 []int) []int {
   var result []int 

   // point to the beginning of both array
   i := 0
   j := 0

   for i < len(arr1) && j < len(arr2) {
      if arr1[i] < arr2[j] {
         result = append(result, arr1[i])
         i++
      } else {
         result = append(result, arr2[j])
         j++
      }
   }

   // insert remaining numbers
   for i < len(arr1) {
      result = append(result, arr1[i])
      i++
   }

   for j < len(arr2) {
      result = append(result, arr2[j])
      j++
   }

