fn replace_substring (s: &str, before: &str, after: &str) -> String {
    let mut new_string = String::new();
    let mut prev_idx = 0;

    // Get a list of index of substring "before" to find
    for (i, c) in s.match_indices(before) {
        // add substring before
        new_string.push_str(&s[prev_idx..i]);
        // add substring after
        new_string.push_str(after);
        prev_idx = i + before.len();
    }

    // Add the rest of the string
    new_string.push_str(&s[prev_idx..]);

    new_string
}

