def find_min_element(arr): 
    #base case - if array is empty return None
    if len(arr) == 0:
        return None

    #base case - if array has only one element, return the element
    if len(arr) == 1:
        return arr[0]

    # Find the middle element
    mid = len(arr)//2

    # Check if the middle element is the minimum
    if mid > 0 and arr[mid - 1] > arr[mid]:
        return arr[mid]
    elif arr[mid + 1] < arr[mid]:
        return arr[mid + 1]
    # Finding the minimum in the left portion of the array
    elif arr[mid] > arr[0]: 
        return find_min_element(arr[0:mid])
    else: 
        return find_min_element(arr[mid + 1:len(arr) - 1])

