function findMissingValue(arr) {
  let sum = 0;

  for(let i = 0; i < arr.length; i++) {
    sum += arr[i];
  }

  let expectedSum = (arr.length + 1) * (arr.length + 2) / 2;
  let missingValue = expectedSum - sum;

  return missingValue;
}

