def find_primes(num):
    # Check for negative numbers and zero 
    if num <= 0:
        return 0
    # Initialize result as an empty list
    result = []
    for n in range(2, num+1):
        is_prime = True
        for div in range(2, n):
            if div != 0 and n % div == 0:
                # Not prime
                is_prime = False
                break
        if is_prime:
            result.append(n)
    return result

