import java.util.Random;

public class PasswordGenerator {

 public static String generatePassword(){

  String capitalLetters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  String smallLetters = "abcdefghijklmnopqrstuvwxyz";
  String numbers = "0123456789";
  String symbols = "!@#$%^&*_=+-/.?<>)";

  String values = capitalLetters + smallLetters + numbers + symbols;

  Random random = new Random();

  char[] randomPassword = new char[8];

  // Flag for set uppercase, lowercase, numbers and symbols respectively
  boolean lowerCaseFlag = false;
  boolean upperCaseFlag = false;
  boolean numberFlag = false;
  boolean symbolFlag = false;

  for(int i=0; i<8; i++){
   // Pick random character from values
   char randomCharacter = values.charAt(random.nextInt(values.length()));

   // Set boolean flags for each kind of character
   if (Character.isUpperCase(randomCharacter)){
    upperCaseFlag = true;
   }
   else if (Character.isLowerCase(randomCharacter)){
    lowerCaseFlag = true;
   }
   else if (Character.isDigit(randomCharacter)){
    numberFlag = true;
   }
   else if (Character.isSymbol(randomCharacter)){
    symbolFlag = true;
   }

   // If all flags are set, break loop
   if (lowerCaseFlag && upperCaseFlag && numberFlag && symbolFlag){
    break;
   }

   // Add random character to randomPassword
   randomPassword[i] = randomCharacter;
  }

  // Return the password
  return new String(randomPassword);
 }

 public static void main(String[] args) {
 System.out.println(generatePassword());
 }
}

