import React, {useReducer, useState} from 'react';
import {View, Text, Button, TextInput} from 'react-native';

const ADD_REMINDER = 'ADD_REMINDER';
const DELETE_REMINDER = 'DELETE_REMINDER';
const UPDATE_REMINDER = 'UPDATE_REMINDER';

const initialState = {
 reminders: [],
};

const reducer = (state, action) => {
 switch (action.type) {
 case ADD_REMINDER:
  return {
   ...state,
   reminders: [...state.reminders, action.payload],
  };
 case UPDATE_REMINDER:
  const updatedReminders = state.reminders.map(reminder => {
   if (reminder.id === action.payload.id) {
    reminder.text = action.payload.text;
   }
   return reminder;
  });

return {
  ...state,
  reminders: updatedReminders,
};

case DELETE_REMINDER:
 return {
  ...state,
  reminders: state.reminders.filter(
   reminder => reminder.id !== action.payload,
  ),
 };
 default:
  return state;
 }
};

const App = () => {
 const [state, dispatch] = useReducer(reducer, initialState);
 const [text, setText] = useState('');

 const addReminder = () => {
  dispatch({type: ADD_REMINDER, payload: {text, id: Date.now()}});
  setText('');
 };

 const deleteReminder = id => {
  dispatch({type: DELETE_REMINDER, payload: id});
 };

 const updateReminder = (id, text) => {
 dispatch({type: UPDATE_REMINDER, payload: {id, text}});
 };

 return (
  <View>
   <TextInput
    value={text}
    onChangeText={setText}
   />
   <Button title='Add Reminder' onPress={addReminder} />
   {state.reminders.map(reminder => (
    <View key={reminder.id}>
     <Text>{reminder.text}</Text>
     <Button title='Edit' onPress={() => updateReminder(reminder.id, reminder.text)} />
     <Button title='Delete' onPress={() => deleteReminder(reminder.id)} />
    </View>
   ))}
  </View>
 );
};

export default App;

