def generate_sudoku(n):
    # Set up our board
    board = [[0 for i in range(n)]
             for j in range(n)]

    # Fill board with random valid entries
    for i in range(n):
        for j in range(n):
            rand = random.randint(1,n)
            board[i][j] = rand
            while not is_valid(board, i, j, rand):
                rand = random.randint(1,n)
                board[i][j] = rand

    return board

def is_valid(board, i, j, number):
    # Check row
    for k in range(len(board)):
        if board[i][k] == number:
            return False

    # Check column
    for k in range(len(board)):
        if board[k][j] == number:
            return False

    # Check soduku
    row_start = int(i - (i % 3))
    col_start = int(j - (j % 3))

    for k in range(3):
        for l in range(3):
            if board[row_start + k][col_start + l] == number:
                return False

    return True

