    private final Database database;

    public OrderSystem(Database database) {
        this.database = database;
    }

    public void placeOrder(List<String> items, String customerName) {
        int totalPrice = 0;
        Customer customer;
        List<Item> orderItems = new ArrayList<>();

        for (String item : items) {
            String[] itemDetails = item.split("-");
            Item itemToOrder = new Item(itemDetails[0], Integer.parseInt(itemDetails[1]));
            totalPrice += itemToOrder.getPrice();
            orderItems.add(itemToOrder);
        }

        customer = new Customer(customerName);
        Order order = new Order(customer, orderItems, totalPrice);
        database.addOrder(order);
    }

}

