    if first_tag in ['NN', 'NNS', 'NNP', 'NNPS']:
        # Sentence is of type Noun Phrase 
        return "Noun Phrase"
    elif first_tag in ['VB', 'VBD', 'VBG', 'VBN', 'VBP', 'VBZ']:
        # Sentence is of type Verb Phrase
