public class MergeSort {
    public static void main(String[] args) {
        int[] array1 = {3, 5, 7};
        int[] array2 = {1, 2, 9};

        // Merge and sort both arrays
        int[] mergeSortedArray = mergeArrays(array1, array2); 

        // Print the resulting array 
        System.out.println("Sorted merged array: "); 
        for (int i = 0; i < mergeSortedArray.length; i++) { 
            System.out.print(mergeSortedArray[i] + " "); 
        } 
    } 

    public static int[] mergeArrays(int[] arr1, int[] arr2)  { 
        int len1 = arr1.length;
        int len2 = arr2.length;
        int[] mergedArray = new int[len1+len2]; 

        int i = 0, j = 0, k = 0; 
        while (i < len1 && j < len2) { 
            if (arr1[i] < arr2[j]) 
                mergedArray[k++] = arr1[i++]; 
            else
                mergedArray[k++] = arr2[j++];
        } 

        // Store remaining values from 
        // both the arrays 
        while (i < len1) 
            mergedArray[k++] = arr1[i++]; 

        while (j < len2) 
            mergedArray[k++] = arr2[j++]; 

        return mergedArray; 
    }
}

