sub Dec2Hex {
  # assign the decimal number to a variable
  my $dec = $_[0];

  # define the hexadecimal alphabet
  my $hexalphabet = '0123456789ABCDEF';

  # declare a variable for hexadecimal conversion
  my $hex = '';

  # loop to convert given decimal number to hexadecimal
  while ($dec > 0) {
    my $temp = $dec % 16;
    $dec = int($dec / 16);
    $hex = substr($hexalphabet, $temp, 1) . $hex;
  }
  return $hex;
}

