void findSubsets(
    std::vector<int>& nums, std::vector<std::vector<int>>& subsets, 
    std::vector<int>& subset, int start)
{
    subsets.push_back(subset);

    for(int i = start; i < nums.size(); ++i)
    {
        subset.push_back(nums[i]);
        findSubsets(nums, subsets, subset, i + 1);
        subset.pop_back();
    }
}

std::vector<std::vector<int>> getAllSubsets(std::vector<int>& nums)
{
    std::vector<std::vector<int>> subsets;
    std::vector<int> subset;
    findSubsets(nums, subsets, subset, 0);
    return subsets;
}

