def sum_of_even_numbers(n):
  # Base case - when n is 0 or lower, 
  # there are no even numbers
  if n <= 0:
    return 0

  # If n is even, add it to the sum
  if n % 2 == 0:
    return n + sum_of_even_numbers(n-2)

  # If n is odd, don't add it. Instead, 
  # check the next even number
  return sum_of_even_numbers(n-1)

