int solveMaze(int x, int y) {
 if (x == m - 1 && y == n - 1) {
  a[x][y] = '$'; 
  return 1;
 }

 if (isValid(x, y)) {
  a[x][y] = '$';

  if (solveMaze(x + 1, y)) 
   return 1;

  if (solveMaze(x, y + 1)) 
   return 1;

  if (solveMaze(x - 1, y)) 
   return 1;

  if (solveMaze(x, y - 1)) 
   return 1;

  a[x][y] = ' ';
  return 0;
 } 
 return 0;
}

