function mySort(arr) {
 var lowIndex;
 var highIndex;
 var currentIndex = 0;

 for(var i = 0; i < arr.length; i++) {
 lowIndex = i;
 highIndex = arr.length - 1;

 while(lowIndex <= highIndex) {
 currentIndex = Math.floor((lowIndex + highIndex) / 2);

 if(arr[currentIndex] < arr[i]) {
 lowIndex = currentIndex + 1;
 } else {
 highIndex = currentIndex - 1;
 }
 }

 for(var j=i; j > lowIndex; j--) {
 arr[j] = arr[j-1];
 }

 arr[lowIndex] = arr[i];
 }

 return arr;
}

