def transpose(matrix):
    num_rows = len(matrix)
    num_cols = len(matrix[0])
    transposed = [ [0 for j in range(num_rows)] for i in range(num_cols) ]
    for i in range(num_rows):
        for j in range(num_cols):
            transposed[j][i] = matrix[i][j]
    return transposed

def search(array, target): 
  # Binary Search 
  start = 0
  end = len(array) - 1
  while start <= end: 
    mid = (start + end) // 2
    if array[mid] == target: 
      # Element found 
      return mid 
    if array[mid] < target: 
      start = mid + 1
    else: 
      end = mid - 1

  # Element not found
  return -1

