public int findMax(Node root) {
    int maxValue = Integer.MIN_VALUE;
    if (root != null) {
        int leftMax = findMax(root.left);
        int rightMax = findMax(root.right);
        if (leftMax > rightMax)
            maxValue = leftMax;
        else
            maxValue = rightMax;
        if (root.data > maxValue)
            maxValue = root.data;
    }
    return maxValue; 
}

