public class SearchArray {
    public static void main(String[] args) {
        int[] sortedArray = {0, 3, 5, 7, 9, 11, 13, 15, 17};
        int searchValue = 9;
        int index = binarySearch(sortedArray, searchValue);
        System.out.println("Element found at index: "+index);
        }
    public static int binarySearch(int[] sortedArray, int searchValue){
        int start = 0;
        int end = sortedArray.length - 1;

        while (start <= end) {
            int mid = (start + end) / 2;
            if (searchValue == sortedArray[mid]) {
                return mid;
            }
            if (searchValue < sortedArray[mid]) {
                end = mid - 1;
            } else {
                start = mid + 1;
            }
        }
    return -1;
    }

}

