import java.util.Scanner;

public class TicTacToe {

 public static void main(String[] args) {

  Scanner sc = new Scanner(System.in); 

  // array with 3 rows and 3 columns of '-'
  char[][] board = {
    { '-', '-', '-' },
    { '-', '-', '-' },
    { '-', '-', '-' }
 };

 char currentPlayer = 'X'; 
 int row, col; 

 while (true) {
    System.out.println("Player " + currentPlayer + ", please enter row number: ");
    row = sc.nextInt() - 1;
    System.out.println("Player " + currentPlayer + ", please enter column number: ");
    col = sc.nextInt() -1;

    if (row < board.length && col < board.length && board[row][col] == '-') {
        board[row][col] = currentPlayer;
    }

    if (isWinningPosition(board, currentPlayer)) {
        System.out.println("Player " + currentPlayer + " wins!");
        break;
    }

    if (isDrawPosition(board)) {
        System.out.println("It's a draw!");
        break;
    }

    if (currentPlayer == 'X') {
        currentPlayer = 'O'; 
    } else {
        currentPlayer = 'X';
    }

    printBoard(board);
 }

 sc.close();
 }

 private static void printBoard(char[][] board) {
    for (int i = 0; i < board.length; i++) {
        for (int j = 0; j < board.length; j++) {
            System.out.print(board[i][j] + " ");
        }
        System.out.println();
    }
 }

 public static boolean isWinningPosition(char[][] board, char currentPlayer) {
    // check rows
    for (int row = 0; row < board.length; row++) {
        int countCharInRow = 0;
        for (int col = 0; col < board[row].length; col++) {
            if (board[row][col] == currentPlayer) {
                countCharInRow++;
            }
        }
        if (countCharInRow == 3) {
            return true;
        }
    }

    // check columns
    for (int col = 0; col < board[0].length; col++) {
        int countCharInCol = 0;
        for (int row = 0; row < board.length; row++) {
            if (board[row][col] == currentPlayer) {
                countCharInCol++;
            }
        }
        if (countCharInCol == 3) {
            return true;
        } 
    }

    // check diagonals
    if (board[0][0] == currentPlayer &&
        board[1][1] == currentPlayer &&
        board[2][2] == currentPlayer) {
        return true;
    }

    if (board[0][2] == currentPlayer &&
        board[1][1] == currentPlayer &&
        board[2][0] == currentPlayer) {
        return true;
    }

    return false;
 }

 public static boolean isDrawPosition(char[][] board) {
    for (int i = 0; i < board.length; i++) {
        for (int j = 0; j < board.length; j++) {
            if (board[i][j] == '-') {
                return false;
            }
        }
    }
    return true;
 }
}

def a_star_search(grid, start, goal):
    open_set = PriorityQueue()
    closed_set = set()
    open_set.put(start, 0)
    prev = {start: None}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while not open_set.empty():
        current = open_set.get()

        if current == goal:
            return reconstruct_path(prev, goal)

        closed_set.add(current)
        for neighbor in get_neighbors(grid, current):
            if neighbor in closed_set:
                continue

            tentative_g_score = g_score[current] + 1 
            if neighbor not in open_set.queue or tentative_g_score < g_score[neighbor]:
                prev[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = g_score[neighbor] + heuristic(neighbor, goal)
                if neighbor not in open_set.queue:
                    open_set.put(neighbor, f_score[neighbor])

    raise ValueError("No Path Found")

