public class MainActivity extends Activity implements View.OnClickListener {
    private TextView tvTime;
    private Button btnStart;
    private Button btnStop;

    private Handler handler = new Handler();
    private long startsMillis;
    private long totalMillis = 0;
    private boolean isRunning = false;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        tvTime = (TextView) findViewById(R.id.tv_time);
        btnStart = (Button) findViewById(R.id.btn_start);
        btnStop = (Button) findViewById(R.id.btn_stop);

        btnStart.setOnClickListener(this);
        btnStop.setOnClickListener(this);
    }

    @Override
    public void onClick(View view) {
        if (view.getId() == R.id.btn_start) {
            start();
        } else if (view.getId() == R.id.btn_stop) {
            stop();
        }
    }

    private void start() {
        startsMillis = System.currentTimeMillis();
        handler.postDelayed(runnable, 0);
        isRunning = true;
    }

    private void stop() {
        totalMillis += System.currentTimeMillis() - startsMillis;
        handler.removeCallbacks(runnable);
        isRunning = false;
        calculateAverageTime();
    }

    private void calculateAverageTime() {
     // TODO: Calculate the average running time
    }

    private Runnable runnable = new Runnable() {
        @Override
        public void run() {
            long millis = System.currentTimeMillis() - startsMillis;
            long seconds = (millis / 1000) % 60;
            long minutes = (millis / (1000 * 60)) % 60;
            tvTime.setText(String.format("%d:%02d", minutes, seconds));

            handler.postDelayed(this, 500);
        }
    };

}

