// Finds the maximum contiguous subarray in an array.
// Returns the start and end index of the array.
function findMaxSubarray(arr) {
 let start = 0;
 let end = 0;
 let sum = 0;
 let maxSum = -Infinity;

 for (let i = 0; i < arr.length; i++) {
  sum += arr[i];
  if (sum > maxSum) {
   maxSum = sum;
   end = i;
  }
  if (sum < 0) {
   start = i + 1;
   sum = 0;
  }
 }

 return [start, end];
}

