def generate_top_features_report(data, n_features=10):
    '''This function generates a report about the top features of a dataset.'''
    feature_frequencies = {}
    for feature_set in data:
        for feature in feature_set:
            if feature not in feature_frequencies:
                feature_frequencies[feature] = 1
            else:
                feature_frequencies[feature] += 1
    top_features = sorted(feature_frequencies, key=feature_frequencies.get, reverse=True)[:n_features]
    report = 'The top {} features are: \n'.format(n_features)
    for feature in top_features:
        report += '- {} \n'.format(feature)
    return report

