public static int LongestCommonSubsequenceLength(String X,
                                                 String Y,
                                                 int m,
                                                 int n) {

    int[][] dp = new int[m + 1][n + 1];

    for (int i = 0; i <= m; i++) {
        for (int j = 0; j <= n; j++) {
            if (i == 0 || j == 0) {
                dp[i][j] = 0;
            } else if (X.charAt(i - 1) == Y.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i - 1][j],
                                    dp[i][j - 1]);
            }
        }
    }
    return dp[m][n];
}

//A function addProductToCart() will be used to add a product to the customer's cart.
function addProductToCart(product) {
  let cart = [];
  //Check if the cart is empty and add the new product
  if (cart.length === 0) {
    cart.push(product);
  } else {
    //Loop through the cart to check if the product already exists
    let found = false;
    for (let i = 0; i < cart.length; i++) {
      if (cart[i].id === product.id) {
        found = true;
      }
    }
    //If the product was not found, add the product to the cart
    if (!found) {
      cart.push(product);
    }
  }
  return cart;
}

