boolean search(Node head, int key)  
{ 
    // start from the first node 
    Node current = head; 

    // if list is empty 
    if (head == null) 
        return false; 

    // traverse the list until end 
    while (current. next != null)  
    { 
        // if data found, return true 
        if (current.data == key) 
            return true; 

        current = current.next; 
    } 

    // Data not found 
    return false;  
}

