bool isPrime(int x) 
{ 
    // Assume that x is a prime number 
    bool isPrime = true; 
    for (int i = 2; i * i <= x; i++) { 

        if (x % i == 0) { 
            isPrime = false; 
            break; 
        } 
    } 
    return isPrime; 
} 

// Function to find primes
void findPrimes(int n) 
{ 
    // Store all prime numbers in an array 
    vector<int> primes; 
    int count = 0; 
    int i = 2;
    while (count < n) { 
        if (isPrime(i)) { 
            primes.push_back(i); 
            count++; 
        } 
        i++; 
    } 
    // Print all primes 
    for (int i = 0; i < primes.size(); i++) 
        cout << primes[i] << " "; 
} 

// Driver Function 
int main() 
{ 
    int n = 10;
    findPrimes(n); 
    return 0; 
}

