public static int[] mergeArrays(int[] arr1, int[] arr2) {
    // create new array of size arr1 + arr2
    int[] newArr = new int[arr1.length + arr2.length];
    int counter = 0;
    int i = 0;
    int j = 0;

    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] <= arr2[j]) {
            newArr[counter] = arr1[i];
            i++;
        } else {
            newArr[counter] = arr2[j];
            j++;
        }
        counter++;
    }
    while (i < arr1.length) {
        newArr[counter] = arr1[i];
        i++;
        counter++;
    }
    while (j < arr2.length) {
        newArr[counter] = arr2[j];
        j++;
        counter++;
    }
    return newArr;
}

let detectLoop = (list) => {
  let slow = list.head;
  let fast = list.head;

  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;

    if (slow === fast)
      return true;
  }

  return false;
};

