def valid_sudoku(nums):
    n = len(nums)
    if n != 81:
        return False

    # create 9x9 array
    board = [[0 for x in range(9)] for y in range(9)]

    # populate board with input numbers
    for i in range(n): 
        x = i % 9 
        y = i // 9
        board[y][x] = nums[i]

    # check each row
    for row in range(9):
        if not valid_row(board[row]):
            return False

    # check each column
    for col in range(9):
        if not valid_row(get_column(board, col)):
            return False

    # check each sub-box
    for x in range(3):
        for y in range(3):
            if not valid_row(get_box(board, x, y)):
                return False

    return True

