// Function to solve the travelling salesman problem
const travellingSalesman = (cities, start) => {
 let bestPath = [];
 let bestDistance = Infinity;
 // Trying all paths
 for (let i = 0; i < Math.pow(2, cities.length); i++) {
 let path = [];
 let distance = 0;
 // Creating a binary pattern for current iteration
 let binPattern = i.toString(2).padStart(cities.length, 0);
 // Looping through each bit
 for (let j = 0; j < binPattern.length; j++) {
 if (binPattern[j] === '1') {
 // Add the city to the path
 path.push(cities[j]);
 // If there is more than one city, add the distance
 // between them
 if (path.length > 1) {
 distance += distanceMatrix[path[path.length - 1]][path[path.length - 2]];
 }
 }
 }
 // Add the distance from the last city back to the first
 distance += distanceMatrix[path[0]][path[path.length - 1]];
 // If the path is better than the best, set it as the
 // new "best"
 if (distance < bestDistance) {
 bestDistance = distance;
 bestPath = path;
 }
 }
 return {
 path: bestPath,
 distance: bestDistance
 };
}

