        let bigram = words[i] + ' ' + words[i+1];
        if (ngrams[bigram]) {
            ngrams[bigram]++;
        } else {
            ngrams[bigram] = 1;
        }
    }

    let maxVal = 0;
    let maxKey = "";
    for (let key in ngrams) {
        if (ngrams[key] > maxVal) {
            maxVal = ngrams[key];
            maxKey = key;
        }
    }
