{
    public static void findSumPairs(int[] arr, int n)
    {
        // Set of pairs 
        HashSet<Pair> pairSet= new HashSet<Pair>(); 
        QuickSort quick_sort=new QuickSort(); 
        quick_sort.sortInPlace(arr); 

        // Indexes for left side (l) and right side (r) 
        int l = 0; 
        int r = arr.length -1;         

        while (l < r) 
        { 
            int temp = arr[l] + arr[r]; 
            if (temp == n) 
            { 

                // pair found 
                pairSet.add(new Pair(arr[l], arr[r])); 

                // move to next element on left side 
                l++; 
            } 
            else if(temp > n) 
            { 

                // move to next element on right side 
                r--; 
            } 
            else
            { 

                // move to next element on left side 
                l++; 
            } 
        } 

        // Print all pairs 
        for (Pair intPair : pairSet) 
            System.out.println(intPair); 
    } 
}

