def freq_word(sentence):
    words = sentence.split()
    # make a dictionary to count the occurrance of each word
    d = {}
    for word in words:
        # if the word is already in the dictionary, increment its count
        if word in d.keys():
            d[word] += 1
        # else add the word in the dictionary
        else:
            d[word] = 1
    # set the first most_freq to the first word in the sentence
    most_freq = words[0]
    # loop trough the words
    for word in words:
        # if we find a word with higher frequency, set most_freq to that word
        if d[word] > d[most_freq]:
            most_freq = word
    return most_freq

public static String getMaxCommonSubstring(String s1, String s2) {
    int m = s1.length();
    int n = s2.length();

    int maxLength = 0;
    int endIndex = 0;

    int[][] dp = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (s1.charAt(i) == s2.charAt(j)) {
                if (i == 0 || j == 0) {
                    dp[i][j] = 1;
                } else {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                }

                if (maxLength < dp[i][j]) {
                    maxLength = dp[i][j];
                    endIndex = i;
                }
            }
        }
    }

    return s1.substring(endIndex - maxLength + 1, endIndex + 1);
}

