// A heuristic search algorithm to solve the 8-Puzzle problem.
function aStarSearch(puzzle, heuristic) {
 // Create a priority queue for storing nodes.
 let queue = new PriorityQueue();

 // Create the initial node.
 let initialNode = {
  puzzle: puzzle,
  g: 0,
  h: heuristic(puzzle),
  parent: null
 };
 queue.enqueue(initialNode, initialNode.g + initialNode.h);

 // Create a dictionary for storing visited nodes.
 let visited = {};
 visited[puzzle.toString()] = true;

 // Start the search.
 while (queue.size() > 0) {
  // Get the node with lowest f-value.
  let node = queue.dequeue();

  // If the puzzle is solved return the solution.
  if (node.puzzle.isSolved()) {
   return getSolution(node);
  }

  // Get the list of actions available for this puzzle.
  let actions = node.puzzle.getActions();

  // Loop through the actions and generate child nodes.
  for (let action of actions) {
   // Generate the child node.
   let childNode = {
    puzzle: node.puzzle.applyAction(action),
    g: node.g + 1,
    h: heuristic(node.puzzle.applyAction(action)),
    parent: node
   };

   // Check if this node has been already visited.
   if (!visited[childNode.puzzle.toString()]) {
    // Add the child node to the priority queue.
    queue.enqueue(childNode, childNode.g + childNode.h);
    // Add the child node to the visited set.
    visited[childNode.puzzle.toString()] = true;
   }
  }
 }

 return [];
}

// Helper function to generate the solution by backtracking.
function getSolution(node) {
 let solution = [];
 let currentNode = node;
 while (currentNode !== null) {
  solution.push(currentNode.action);
  currentNode = currentNode.parent;
 }
 solution.reverse();
 return solution;
}

