def calculate(expression):
 stack = [] 
 result = 0 

 for char in expression:
 if char.isdigit():
     stack.append(int(char))
 elif char in "+-/*":
     right = stack.pop()
     left = stack.pop()

     if char == "+":
         result = left + right
     elif char == "-":
         result = left - right
     elif char == "/":
         result = left / right
     elif char == "*":
         result = left * right

     stack.append(result)

 return result

