int minCoins(int value) 
{ 
	int coins[] = {1, 5, 10, 25}; 
	int m = sizeof(coins)/sizeof(coins[0]); 

	int table[value+1]; 

	table[0] = 0; 

	for (int i=1; i<=value; i++) 
		table[i] = INT_MAX; 

	for (int i=1; i<=value; i++) 
	{ 
		for (int j=0; j<m; j++) 
		if (coins[j] <= i) 
		{ 
			int sub_res = table[i-coins[j]]; 
			if (sub_res != INT_MAX && sub_res + 1 < table[i]) 
				table[i] = sub_res + 1; 
		} 
	} 
	return table[value]; 
} 

