Implement a Java program to modify an array of numbers such that all the odd numbers come before all the even 
"""

public class ModifyArray {

    public static void modify(int[] arr) { 
        // Initialize left and right pointers
        int left = 0; 
        int right = arr.length - 1; 

        // Traverse the array elements 
        while (left < right) { 
            // Increment left pointer if we  
            // find an even number 
            while (arr[left] % 2 == 0 && left < right) 
                left++; 

            // Decrement right pointer if we 
            // find an odd number 
            while (arr[right] % 2 == 1 && left < right) 
                right--; 

            // Swap the elements 
            if (left < right) { 
                int temp = arr[left]; 
                arr[left] = arr[right]; 
                arr[right] = temp; 
                left++; 
            } 
        } 
    } 

    public static void main(String[] args) 
    {

        int[] arr = {12, 34, 7, 8, 1, 100}; 
        modify(arr); 

        System.out.println("Modified array: "); 
        for (int i = 0; i < arr.length; i++) 
            System.out.print(arr[i] + " "); 
    } 
}

