public class LongestIncreasingSubsequence {

    public static int getLisLength(int[] arr) {

        //Length of the Longest increasing subsequence
        int lisLength = 1;

        //Initialize temp array with 1
        int[] tempLis = new int[arr.length];
        for (int i=0; i<arr.length; i++) {
            tempLis[i] = 1;
        }

        //calculating LIS length
        for (int i = 0; i < arr.length-1; i++) {
            for (int j = i+1; j < arr.length; j++) {
                if ((arr[i] < arr[j]) && (tempLis[i] + 1 > tempLis[j])) {
                    tempLis[j] = tempLis[i] + 1;
                }
            }
        }

        //finding maximum of all LIS 
        for (int i = 0; i < arr.length; i++) {
            if (lisLength < tempLis[i]) {
                lisLength = tempLis[i];
            }
        }

        return lisLength;
    }

    public static void main(String[] args) {

        int arr[] = {10, 22, 9, 33, 21, 50, 41, 60}; 
        System.out.println("Length of longest increasing subsequence is : " + getLisLength(arr));
    }
}

