function isPalindrome(inputString) {
 // remove special characters and make the string lowercase
 inputString = inputString.toLowerCase().replace(/[^a-zA-Z0-9]+/g, '');

 // store the length of the string
 const n = inputString.length;

 // initialize start and end of the string
 let start = 0;
 let end = n - 1;

 while (start < end) {
 // if the characters at start and end do not match, we can exit the loop
 // and return false immediately
 if (inputString[start] != inputString[end]) {
 return false;
 }
 // move start and end to the next characters
 start++;
 end--;
 }
 // if the loop ends, all characters match, so the string is a palindrome
 return true;
}

