    for (int i = 0; i < inputArray.Length; i++)
    {
        // If the value does not exist in the dictionary, add it
        if (!uniqueValuesDictionary.ContainsKey(inputArray[i]))
        {
            outputArray[outputArrayIndex] = inputArray[i];
            uniqueValuesDictionary.Add(inputArray[i], 1);
            outputArrayIndex++;
        }
    }

    return outputArray.Take(outputArrayIndex).ToArray(); // Return new array with only uniqe values
}

