function treeDepth(root) {
  if (root === null) {
    return 0;
  }

  // get the depth of the left side of the tree
  let leftDepth = treeDepth(root.left);
  // get the depth of the right side of the tree
  let rightDepth = treeDepth(root.right);

  // compare and return the depth (depth of the longest sub-tree + 1)
  if (leftDepth > rightDepth) {
    return leftDepth + 1;
  } else {
    return rightDepth + 1;
  }
}

