import java.util.*;

public class WordFrequency {

 public static Map<String, Integer> getWordFrequency(String[] words, int n) {
  Map<String, Integer> frequencyMap = new HashMap<String, Integer>();
  for (String word : words) {
   Integer count = frequencyMap.get(word);
   if (count == null) {
    frequencyMap.put(word, 1);
   } else {
    frequencyMap.put(word, count + 1);
   }
  }

  // Use TreeMap to sort by frequency
  Map<String, Integer> sortedFrequencyMap = new TreeMap<String, Integer>(new Comparator<String>() {
   public int compare(String a, String b) {
    return frequencyMap.get(b).compareTo(frequencyMap.get(a));
   }
  });
  sortedFrequencyMap.putAll(frequencyMap);

  // Return the top N most frequently used words
  Map<String, Integer> result = new LinkedHashMap<String, Integer>();
  int i = 0;
  for (String key : sortedFrequencyMap.keySet()) {
   if (i >= n) {
    break;
   }
   result.put(key, sortedFrequencyMap.get(key));
   i++;
  }
  return result;
 }

 public static void main(String[] args) {
  String[] words = "This is a sample string with many words".split(" ");
  int n = 2;
  System.out.println("Input Text: " + String.join(" ", words));
  Map<String, Integer> out = getWordFrequency(words, n);
  System.out.println("Output Top " + n + ": " + out.toString());
 }
