function convertToRoman(num) {
    let roman = "";
    // Define the roman numerals values
    let romanValues = {
        M:1000,
        CM: 900,
        D: 500,
        CD: 400,
        C: 100,
        XC: 90,
        L: 50,
        XL: 40,
        X: 10,
        IX: 9,
        V: 5,
        IV: 4,
        I: 1
    }

    // loop through the values
    for(let key in romanValues){
        // use math.floor to check if the value is less then the number
        while(num >= romanValues[key]){
            // append the letter to the output
            roman+=key;
            // subtract the value from the number
            num -= romanValues[key];
        }
    }
    return roman;
}

