// Dynamic Programming Algorithm
int findLongestCommonSubsequence(string string1, string string2) 
{ 
    // construct 2D array of size n+1 * m+1
    int n = string1.length(), m = string2.length();
    int LCSLength[n+1][m+1]; 

    // initializing the table with
    // 0s 
    for(int i = 0; i <= n; i++)
    {
        for(int j = 0; j <= m; j++)
        {
            if(i == 0 || j == 0) 
                LCSLength[i][j] = 0;
        }
    }

    // Modifying the table according to
    // given strings
    for(int i = 1; i <= n; i++) 
    {
        for(int j = 1; j <= m; j++) 
        {
            if(string1[i-1] == string2[j-1])
                LCSLength[i][j] = LCSLength[i-1][j-1] + 1;
            else
                LCSLength[i][j] = max(LCSLength[i-1][j], LCSLength[i][j-1]);
        } 
    } 

    // return LCS length
    return LCSLength[n][m];
}

