def combinations(string, k):
    result = []
    if k == 0 or len(string) == 0:
        return result
    if k == len(string):
        result.append(string)
        return result
    first_char = string[0]
    remaining_string = string[1:]
    for c in combinations(remaining_string, k-1):
        result.append(first_char + c)
    for c in combinations(remaining_string, k):
        result.append(c)
    return result

