// The main function that returns the maximum number 
// possible from given array. 
// arr[]: input array 
// n: size of the array 
unsigned long long int formBiggestNo(int arr[], int n) 
{ 
    int j; 

    // Start from the right most digit and find the largest 
    // digit to include in biggest number
    unsigned long long int bigNo = 0; 
    for (int i = n-1; i >= 0 ; i--) 
    { 
        int temp = arr[i]; 
        int max = arr[i]; 
        for (j = i-1; j >= 0; j--) 
            if (arr[j] > max) 
            { 
                max = arr[j]; 
                temp = j; 
            } 

        // Swap the maximum digit with the current digit 
        // and add this digit to Big No. 
        bigNo = bigNo * 10 + max; 
        arr[temp] = arr[i]; 
        arr[i] = max; 
   } 

   return bigNo; 
} 

