#include <iostream> 

using namespace std; 

// A linked list node 
struct Node 
{ 
    int data; 
    struct Node* next; 
}; 

// Function to create new node with given data 
Node* newNode(int data) 
{ 
    Node* new_node = new Node; 
    new_node->data = data; 
    new_node->next = NULL; 
    return new_node; 
} 

// Function to insert a node at the beginning of the linked list 
void push(struct Node** head_ref, int new_data) 
{ 
    // Allocate node 
    Node* new_node = new Node; 

    // Put in the data 
    new_node->data = new_data; 

    // Make next of new node as head 
    new_node->next = (*head_ref); 

    // Move the head to point to the new node 
    (*head_ref) = new_node; 
} 

// Function to delete a node in a Linked List. 
void deleteNode(struct Node **head_ref, int key) 
{ 
    // Store head node 
    Node* temp = *head_ref, *prev; 

    // If head node itself holds the key to be deleted 
    if (temp != NULL && temp->data == key) 
    { 
        *head_ref = temp->next;   // Changed head 
        free(temp);               // free old head 
        return; 
    } 

    // Search for the key to be deleted, keep track of the 
    // previous node as we need to change 'prev->next' 
    while (temp != NULL && temp->data != key) 
    { 
        prev = temp; 
        temp = temp->next; 
    } 

    // If key was not present in linked list 
    if (temp == NULL) return; 

    // Unlink the node from linked list 
    prev->next = temp->next; 

    free(temp);  // Free memory 
} 

// Function to print all the nodes linked list
void printList(struct Node *node) 
{ 
    while (node != NULL) 
    { 
        cout << node->data << " "; 
        node = node->next; 
    } 
} 

int main() 
{ 
    // Start with the empty list 
    Node* head = NULL; 

    // Insert 10. So linked list becomes 10->NULL 
    push(&head, 10); 

    // Insert 8 at the beginning. So linked list becomes 8->10->NULL 
    push(&head, 8); 

    // Insert 6 at the beginning. So linked list becomes 6->8->10->NULL 
    push(&head, 6); 

    // Insert 4 at the beginning. So linked list becomes 4->6->8->10->NULL 
    push(&head, 4); 

    cout << "Created Linked List: "; 
    printList(head); 

    // Deleting node from the Linked list
    deleteNode(&head, 8);   // Delete node with value 4 

    cout << "\nLinked List after Deletion of 1 node: "; 
    printList(head); 

    return 0; 
}

