#include <stdio.h>

void bubbleSort(int arr[], int n)
{
 int i, j;

 // Perform n-1 iteration for bubble sort
 for (i = 0; i < n-1; i++)

 // Last n-i-1 elements are already in place
 for (j = 0; j < n-i-1; j++)
 if (arr[j] > arr[j+1])
 {
 int temp = arr[j];
 arr[j] = arr[j+1];
 arr[j+1] = temp;
 }

 // Optimized code
 bool isSwapped;
 for (i = 0; i < n-1; i++)
 {
  isSwapped = false;
  for (j = 0; j < n-i-1; j++)
  {
   if (arr[j] > arr[j+1])
   {
    int temp = arr[j];
    arr[j] = arr[j+1];
    arr[j+1] = temp;
    isSwapped = true;
   }
  }

  // If no elements were swapped by inner loop, then break
  if (isSwapped == false)
   break;
 }
}

