int longestIncreasingSubsequence(vector<int> arr)  
{  
    int n = arr.size();  
    vector<int> lis(n, 1);

    for (int i = 1; i < n; i++ ) {  
        for (int j = 0; j < i; j++ ) {  
            if ( arr[i] > arr[j] && lis[i] < lis[j] + 1)  
            {  
                lis[i] = lis[j] + 1;  
            }  
        }  
    }  
    int result = *max_element(lis.begin(), lis.end()); 
    return result;
}

