    maxi = 0
    c = [[0 for x in range(n2+1)] for x in range(n1+1)] 

    result = 0
    for i in range(n1): 
        for j in range(n2): 
            if (str1[i] == str2[j]): 
                if(i == 0 or j == 0): 
                    c[i][j] = 1
                else: 
                    c[i][j] = c[i -1][j-1] + 1
                if (c[i][j] > maxi): 
                    maxi = c[i][j] 
                    result = i - maxi + 1
    return str1[result:result + maxi]

