fn quickselect(nums: &mut [i32], k: usize) -> i32 {
 let len = nums.len();
 if len == 0 {
 return 0;
 }

 let pivot_index = partition(nums, 0, len -1);

 while pivot_index != k - 1 {
 if pivot_index > k - 1 {
 pivot_index = partition(nums, 0, pivot_index - 1);
 } else {
 pivot_index = partition(nums, pivot_index + 1, len - 1);
 }
 }

 nums[pivot_index]
}

fn partition(nums: &mut [i32], left: usize, right: usize) -> usize {
 let pivot_index = (left + right) / 2;

 nums.swap(pivot_index, right);

 let mut store_index = left;

 for i in left..right {
 if nums[i] < nums[right] {
 nums.swap(store_index, i);
 store_index += 1;
 }
 }

 nums.swap(store_index, right);

 store_index
}

fn main() {
 let mut nums = [5, 3, 12, 9, 15, 8];
 let k = 4;
 println!("The {}th smallest element in the array is {}", k, quickselect(&mut nums, k));
}

