vector<int> twoSum(vector<int>& array, int target) 
{ 
	vector<int> result; 
	for (int i = 0; i < array.size(); i++) { 
		for (int j = i + 1; j < array.size(); j++) { 
			if (array[i] + array[j] == target) { 
				result.push_back(i); 
				result.push_back(j); 
			} 
		} 
	} 
	return result; 
} 

