function vigenereCipher(message, key) {
	let result = '';

	for (let i = 0, k = 0; i < message.length; i++) {
		let c = message.charCodeAt(i);

		if (c >= 97 && c <= 122) {
			let offset = key.charCodeAt(k % key.length)-97; //97 is ASCII code of letter 'a'
			result += String.fromCharCode((c - 97 + offset) % 26 + 97);
			k++;
		} else {
			result += message.charAt(i);
		}
	}

 	return result;
}

