struct Node
{
 int data;
 Node* next;
 Node* prev;
};

void convertToDLL(Node* head)
{
 // Set prev pointer of the first node to NULL. 
 head->prev = NULL; 

 // Initialize prev and curr pointers 
 Node* prev = NULL;
 Node* curr = head; 

 // Traverse list and change next and prev pointers 
 while (curr)
 {  
  // Set prev pointer of current node as prev 
  curr->prev = prev;  

  // Change prev of next node 
  if (curr->next != NULL) 
   curr->next->prev = curr; 

  // Move prev and curr one step ahead 
  prev = curr;
  curr = curr->next;
 } 
}

