// This function takes a string, a string containing the original set of 
// characters, a start index and an end index. The function prints all 
// possible combinations of the characters present between start and end index. 
void print_all_combinations(char str[], char original_set[], int start, int end) 
{ 
	int i; 

	// If start and end index are same, store the combination and print it 
	if (start == end) 
	{ 
		for (i = 0; original_set[i]; i++) 
			str[start] = original_set[i]; 
		printf("%s\n", str); 
	} 

	// If end index is more than start index 
	else
	{ 
		// Store the first character of the original set at the start index 
		// for the current combination being considered 
		str[start] = original_set[0]; 

		// Update the string for next recursive call
		print_all_combinations(str, original_set, start + 1, end); 

		// Store the second character of the original set at the start index 
		// for the current combination being considered 
		str[start] = original_set[1]; 

		// Update the string for next recursive call
		print_all_combinations(str, original_set, start + 1, end); 
	} 
} 

