public static int[] getIntersection(int[] arr1, int[] arr2) {
    int size1 = arr1.length;
    int size2 = arr2.length;
    int[] temp = new int[size1 > size2 ? size2 : size1];
    int x = 0;
    int i = 0;
    int j = 0;

    while (i < size1 && j < size2) {
        if (arr1[i] < arr2[j]) {
            i++;
        } else if (arr2[j] < arr1[i]) {
            j++;
        } else {
            temp[x++] = arr2[j++];
            i++;
        }
    }

    int[] common = new int[x];
    System.arraycopy(temp, 0, common, 0, x);

    return common;
}

