// Class to handle read, write, update, delete to MongoDB
public class MongoDBApi {
 private MongoClient mongoClient;
 private MongoDatabase mongoDatabase;

 // Constructor
 MongoDBApi() {
  mongoClient = new MongoClient("localhost", 27017);
  mongoDatabase = mongoClient.getDB("dbName");
 }

 // Method to insert a record into MongoDB
 public void insert(String jsonString) {
  MongoCollection<Document> collection = mongoDatabase.getCollection("collectionName");
  collection.insertOne(Document.parse(jsonString));
 }

 // Method to update an existing record in MongoDB
 public void update(String jsonString) {
  MongoCollection<Document> collection = mongoDatabase.getCollection("collectionName");
  collection.updateOne(Filters.eq("_id", 1), Updates.set("fieldName", "value"));
 }

 // Method to delete an existing record from MongoDB
 public void delete(int id) {
  MongoCollection<Document> collection = mongoDatabase.getCollection("collectionName");
  collection.deleteOne(Filters.eq("_id", id));
 }

 // Method to read an existing record from MongoDB
 public String read(int id){
  MongoCollection<Document> collection = mongoDatabase.getCollection("collectionName");
  Document doc = collection.find(Filters.eq("_id", id)).first();
  return doc.toJson();
 }
}

