public class RotateArray
{
    // rotate an array of integers to the left by a given number
    public static int[] RotateLeft(int[] arr, int step)
    {
        int[] result = new int[arr.Length];
        for (int i = 0; i < arr.Length; i++)
        {
            int offset = (i + step) % arr.Length; 
            result[offset] = arr[i];
        }
        return result;
    }

    public static void Main()
    {
        // example
        int[] arr = {1, 2, 3, 4, 5};
        int step = 2;

        int[] rotated = RotateLeft(arr, step); 
        foreach (int i in rotated)
