function sort(head) { 
	let curr = head; 
	let next = curr.next; 
	while(curr !== null) {
		while(next !== null) { 
			if (curr.val > next.val) { 
				let temp = curr.val; 
				curr.val = next.val; 
				next.val = temp; 
			} 
			next = next.next; 
		} 
		curr = curr.next; 
		if (curr !== null) { 
			next = curr.next; 
		} 
	} 
}

