def intersecting_node(head1, head2):
    """
    Function to find the intersecting node in two given linked lists
    """
    list1_curr, list2_curr = head1, head2
    list1_set, list2_set = set(), set()
    while list1_curr is not None and list2_curr is not None:
        list1_set.add(list1_curr.data)
        list2_set.add(list2_curr.data)
        if list1_curr.data in list2_set:
            return list1_curr.data
        if list2_curr.data in list1_set:
            return list2_curr.data
        list1_curr, list2_curr = list1_curr.next, list2_curr.next

    return None

