class AreaCalculator extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      shape: '',
      area: 0
    }
  }

  renderCalculator = () => {
    return (
      <div>
        <label for="shape-selector">Please select the shape:</label>
        <select name="shape-selector" id="shape-selector" onChange={this.selectShape}>
          <option value="Triangle">Triangle</option>
          <option value="Square">Square</option>
          <option value="Circle">Circle</option>
        </select>

        <form onSubmit={this.calculateArea}>
          {this.renderInputs()}
          <input type="submit" value="Calculate"/>
        </form>

        <p>The area is {this.state.area}</p>
      </div>
    )
  }

  selectShape = (event) => {
    this.setState({ shape: event.target.value });
  }

  renderInputs = () => {
    switch (this.state.shape) {
      case 'Triangle':
        return (
          <div>
            <label for="base">Please enter the base:</label>
            <input type="text" name="base" id="base"/>
            <br/>
            <label for="height">Please enter the height:</label>
            <input type="text" name="height" id="height"/>
          </div>
        );
      case 'Square':
        return (
          <div>
            <label for="side">Please enter the side length:</label>
            <input type="text" name="side" id="side"/>
          </div>
        );
      case 'Circle': 
        return (
          <div>
            <label for="radius">Please enter the radius:</label>
            <input type="text" name="radius" id="radius"/>
          </div>
        );
      default:
        return null;
    }
  }

  calculateArea = (event) => {
    event.preventDefault();
    switch (this.state.shape) {
      case 'Triangle':
        const base = event.target.base.value;
        const height = event.target.height.value;
        this.setState({
          area: 0.5 * base * height
        });
        break;
      case 'Square':
        const side = event.target.side.value;
        this.setState({
          area: side * side
        });
        break;
      case 'Circle': 
        const radius = event.target.radius.value;
        this.setState({
          area: Math.PI * radius * radius
        });
        break;
      default:
        return;
    }
  }

  render() {
    return (
      <div>
        {this.renderCalculator()}
        <script src="index.js"></script>
      </div>
    );
  }
}

