class BookStore {
    //Create a dictionary to keep track of book and stock
    var books = [String: Int]()

    //Function to restock books
    func restock(book: String, stock: Int) {
        books[book] = stock
    }

    //Function to search books
    func searchBooks(for: String) -> [String] {
        var matchingBooks = [String]()
        for (book, _) in books {
            if book.contains(for) {
                matchingBooks.append(book)
            }
        }
        return matchingBooks
    }

    //Function to remove books from inventory after a purchase
    func purchaseBook(book: String) {
        if var currentStock = books[book] {
            if currentStock > 0 {
                books[book] = currentStock - 1
            }
        }
    }
}

