def longest_common_prefix(arr):
    if len(arr) == 0:
        return ""
    if len(arr) == 1:
        return arr[0]

    prefix = arr[0]

    n = len(prefix)
    for i in range(1, len(arr)):

        while arr[i][:n] != prefix[:n]:
            n -= 1
            prefix = prefix[:n]
    return prefix

