void findPaths(Node* node, vector<int>& path, vector<vector<int>>& paths) {
  if (!node) return;

  path.push_back(node->val);

  if (!node->left && !node->right) 
    paths.push_back(path);

  findPaths(node->left, path, paths);
  findPaths(node->right, path, paths);

  path.pop_back();
}

