        int n = str.length(); 
        int longestLength = 0; 
        int startIndex = 0; 
        boolean visited[] = new boolean[256]; 

        for (int i = 0; i < n; i++) { 
            int cur_len = 0; 
            Arrays.fill(visited, false); 
            for (int j = i; j < n; j++) { 
                if (visited[str.charAt(j)] == true) 
                    break; 

                visited[str.charAt(j)] = true; 
                cur_len++; 
            } 
            if (cur_len > longestLength) { 
                longestLength = cur_len; 
                startIndex = i; 
            } 
        } 
        return str.substring(startIndex, startIndex + longestLength); 
    }

