import java.util.Arrays;

public class AverageCalculator {
    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5};

        // Create a thread pool with three threads
        int threadCount = 3;
        Thread[] threads = new Thread[threadCount];

        // Calculate average using multi-threading
        for (int i = 0; i < threadCount; i++) {
            int startIndex = array.length * i / threadCount;
            int endIndex = array.length * (i + 1) / threadCount;
            threads[i] = new Thread(new AverageCalculatorThread(Arrays.copyOfRange(array, startIndex, endIndex)));
            threads[i].start();
        }

        // Wait for threads to finish and calculate final result
        double avg = 0;
        for (int i = 0; i < threadCount; i++) {
            try {
                threads[i].join();
                avg += threads[i].getAverage();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
        avg /= threadCount;

        System.out.println("Average of numbers in array is: " + avg);
    }
}

class AverageCalculatorThread extends Thread {
    private int[] array;
    private double average;

    public AverageCalculatorThread(int[] array) {
        this.array = array;
        this.average = 0;
    }

    public void run() {
        double sum = 0;
        for (int i : array) {
            sum += i;
        }
        average = sum / array.length;
    }

    public double getAverage() {
        return average;
    }
}

