function Users() {
 const [users, setUsers] = useState([]);
 const [error, setError] = useState(true);
 const [newUser, setNewUser] = useState('');

 useEffect(() => {
 axios.get('url_to_api')
 .then(response => {
 setUsers(response.data);
 setError(false);
 })
 .catch(err => {
 setError(true);
 });
 }, []);

 const addUser = () => {
 axios.post('url_to_api', newUser)
 .then(res => {
 const newUserAdded = [
 ...users,
 res.data
 ];
 setUsers(newUserAdded);
 setError(false);
 });
 }

