class RollingAverage:
    def __init__(self, size):
        self.size = size
        self.arr = []

    def push(self, x):
        self.arr.append(x)
        if len(self.arr) > self.size:
            self.arr.pop(0)

    def average(self):
        avg = 0
        for x in self.arr:
            avg += x
        return avg / len(self.arr)

