def isPrime(num):
    if num > 1:
        # Iterate from 2 to num // 2 
        for i in range(2, num//2): 
            # If num is divisible by any number between 
            # 2 and num // 2, it is not a prime number
            if (num % i) == 0: 
                return False
        else: 
            return True
    else: 
        return False

