public class Division {

    public static int divide(int a, int b) {

        // Initialize result
        int result = 0;

        // Handling negative values.
        int sign = ((a < 0) ^ (b < 0)) ? -1 : 1;
        a = Math.abs(a);
        b = Math.abs(b);

        while (a >= b) {
            a -= b;
            result++;
        }

        // Handling negative values.
        return sign * result;
    }

    public static void main(String[] args) {
        int a = 20;
        int b = 4;
        System.out.println("a / b = " + divide(a, b));
    }
}

