def find_prime_numbers(num):
    if num < 2:
        return

    prime_nums = [2]

    for i in range(3, num+1, 2):
        is_prime = True

        for p in prime_nums:
            if i % p == 0:
                is_prime = False
                break

        if is_prime:
            prime_nums.append(i)

    return prime_nums

