 let left = 0;
 let right = numbers.length-1;

 while (left <= right) {
 let mid = Math.floor((left + right) / 2);
 let guess = numbers[mid];
 if (guess == item) {
 return mid;
 }
 if (guess > item) {
 right = mid - 1;
 } else {
 left = mid + 1;
 }
 }
 return null;
