def add_binary(a, b):
    carry = 0
    result = []

    for i in range(max(len(a), len(b))):
        sum_ = carry
        if i < len(a):
            sum_ += a[i]
        if i < len(b):
            sum_ += b[i]
        carry = 0
        if sum_ > 1 and i < max(len(a), len(b)) - 1:
            sum_ = sum_ % 2
            carry = 1
        result.append(sum_)
