public class LCS { 

    // Returns length of LCS for X[0..m-1], Y[0..n-1]  
    static int lcs(String X, String Y, int m, int n) 
    { 
        // Base case 
        if (m == 0 || n == 0) 
            return 0; 
        // If last characters of X and Y are same 
        if (X.charAt(m - 1) == Y.charAt(n - 1)) 
            return 1 + lcs(X, Y, m - 1, n - 1); 
        else
            // Otherwise, find the max of two cases 
            // a) Consider all characters of X and ignore last character of Y 
            // b) Consider all characters of Y and ignore last character of X 
            return Math.max(lcs(X, Y, m, n - 1), lcs(X, Y, m - 1, n)); 
    } 

    public static void main(String[] args) 
    { 
        String X = "abcdgh"; 
        String Y = "aedfhr"; 

        int m = X.length(); 
        int n = Y.length(); 

        System.out.println("Length of LCS is" + " " + lcs(X, Y, m, n)); 
    } 
}

def is_palindrome(word):
    # find the length of the word
    length = len(word)
    # if length is 0 or 1, return true
    if length == 0 or length == 1:
        return True

    # compare first and last characters
    if word[0] != word[length-1]:
        return False

