def minimax(state, depth, is_max, player):
  if is_over(state):
    score = evaluate(state, player)
    return score
  if is_max: 
    best = -math.inf
    for action in available_actions(state):
      curr = minimax(state, depth+1, False, player)
      best = max(best, curr)
    return best
  else:
    best = math.inf
    for action in available_actions(state):
      curr = minimax(state, depth+1, True, player)
      best = min(best, curr)
    return best

