// Function that implements Boyer Moore algorithm 
void findString(string text, string pattern) 
{ 
	int n = text.length(); 
	int m = pattern.length(); 

	int last[256]; 

	// eke the last occurence index of all characters 
	for (int i = 0; i < 256; i++) {
		last[i] = -1; 
	}

	for (int i = 0; i < m; i++) {
		last[pattern[i]] = i; 
	} 

	int s = 0;
	while (s <= (n - m)) {
		int j = m - 1;

		while (j >= 0 && pattern[j] == text[s + j]) {
			j--; 
		}

		if (j < 0) {
			// Match found 
			cout << "Pattern occur at shift " << s << endl; 

			s += (s + m < n) ? m - last[text[s + m]] : 1;

		} else {
			s += max(1, j-last[text[s+j]]);
		}
	}
}

