def knapSack(items, size): 

    total_items = len(items) 
    K = [[0 for x in range(size+1)] for x in range(total_items+1)] 
    for i in range(total_items + 1): 
        for j in range(size + 1): 
            if i == 0 or j == 0: 
                K[i][j] = 0
            elif items[i-1][1] <= j: 
                K[i][j] = max(items[i-1][0] + K[i-1][j-items[i-1][1]],  K[i-1][j])
            else: 
                K[i][j] = K[i-1][j] 
    return K[total_items][size] 


