def partition(array, start, end): 
    pivot = array[end] 
    p_index = start 

    for i in range(start, end): 
        if array[i] <= pivot: 
            array[i], array[p_index] = array[p_index], array[i] 
            p_index += 1
    array[p_index], array[end] = array[end], array[p_index] 
    return p_index 

def quick_select(array, start, end, k): 
    if start == end: 
        return array[start] 

    # partition the array about the pivot element 
    p_index = partition(array, start, end) 

    # if the partition index is same as k 
    # return the pivot element
    if p_index == k - 1: 
        return array[p_index] 

    # if k is less than the partition index 
    # search in the left sub-array 
    if k - 1 < p_index: 
        return quick_select(array, start, p_index - 1, k) 

    # if k is more than the partition index 
    # search in the right sub-array 
    return quick_select(array, p_index + 1, end, k) 

