	public static void solveQuadraticEquation(int a, int b, int c){
		//The roots of the quadratic equation ax2 + bx + c = 0 can be calculated using below formula:
		//x1 = (-b + sqrt(b2 - 4ac))/2a
		//x2 = (-b - sqrt(b2 - 4ac))/2a

		double x1, x2;
		double discriminant = Math.sqrt(Math.pow(b, 2) - 4*a*c);
		x1 = (-b + discriminant)/(2*a);
		x2 = (-b - discriminant)/(2*a);

		System.out.println("The roots of the quadratic equation "+ a + "x2 + " + b + "x + " 
						+ c + " = 0 are x1 = " + x1 + " and x2 = " + x2);
