// AI-based solution for a Sudoku puzzle

// Solving a given Sudoku Puzzle
public static void solveSudoku(int[][] board) { 
    // Empty cell where the solution will be stored 
    int row = -1, col = -1; 
    boolean isEmpty = true; 

    for (int i = 0; i < 9; i++) { 
        for (int j = 0; j < 9; j++) { 
            if (board[i][j] == 0){ 
                row = i; 
                col = j; 

                // since there is one empty 
                // cell, set isEmpty to false 
                isEmpty = false;  
                break; 
            } 
        } 
        if (!isEmpty){ 
            break; 
        } 
    } 

    // no empty space left 
    if (isEmpty){ 
        return; 
    } 

    // else for each-row backtrack 
    for (int num = 1; num <= 9; num++) { 
        if (isSafe(board, row, col, num)) { 
            board[row][col] = num; 
            solveSudoku(board); 
            board[row][col] = 0; 
        } 
    } 
}

// Check if the number is safe to insert
public static boolean isSafe(int[][] board, 
                int row, int col, int num) { 

    // Check the row 
    for (int j = 0; j < 9; j++) { 
        if (board[row][j] == num) { 
            return false; 
        }
    }

    // Check the column 
    for (int i = 0; i < 9; i++) { 
        if (board[i][col] == num) { 
            return false; 
        } 
    }

    // Check the sub-box 
    int boxRow = row - row % 3; 
    int boxCol = col - col % 3; 

    for (int i = boxRow; i < boxRow + 3; i++) { 
        for (int j = boxCol; j < boxCol + 3; j++) { 
            if (board[i][j] == num) { 
                return false; 
            } 
        } 
    } 

    return true; 
}

