def prime_numbers(n):
    """ Outputs all the prime numbers between 0 and the user input. """
    prime_list = []
    for num in range(2, n+1):
        for i in range(2, num):
            if (num % i == 0):
                break
        else:
            prime_list.append(num)
    return (prime_list)

