def is_valid_IPv4_address(ip_addr):
    sections = ip_addr.split('.')
    if len(sections) != 4:
        return False
    for section in sections:
        try:
            if not(0 <= int(section) < 256):
                return False
        except ValueError:
            return False
    return True

