import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;

public class NetworkMonitoring {

 public static void main(String args[]) throws Exception {
  // list to store ip addresses
  ArrayList<String> list = new ArrayList<String>();

  // command to execute
  String command = "arp -a";

  // executing command, store in buffered reader
  Process p = Runtime.getRuntime().exec(command);
  BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));

  // reading each line of output
  String line;
  while ((line = reader.readLine()) != null) {
   // extracting ip address from the line
   String ipAddr = line.substring(line.indexOf("at") + 3, line.indexOf("on") - 1);

   // creating ip address object and storing ips
   InetAddress addr = InetAddress.getByName(ipAddr);
   list.add(addr.getHostAddress()); 
  }

  // printing list of ips
  System.out.println(list);
 }
}

